    15	import "./audit.css";
    16	
    17	interface Row {
    18	  id: string; ts: string; actor_type: "ai" | "system" | "human"; actor: string; model: string | null;
    19	  kind: string; stage: string | null; action: string; payload: Record<string, unknown>; checkpoint: string | null; summary: string | null;
    20	}
    21	interface Page { items: Row[]; more: boolean }
    22	type Who = Row["actor_type"];
    23	type Item = { day: string; rows: Row[] };   // one row, or a fold of identical consecutive steps (newest first)
    24	
    25	const CP_LABEL: Record<string, string> = { cp1: "JAN 26", cp2: "JUL 26", ab: "A/B TEST" };
    26	const WHO: Record<Who, string> = { ai: "AI", system: "System", human: "PM" };
    27	const WHO_ORDER: Who[] = ["ai", "system", "human"];
    28	const WHAT: Record<"evidence" | "structure" | "all", string> = {
    29	  evidence: "What entered the data, and when.",
    30	  structure: "When the agent ran each stage, and every AI step.",
    31	  all: "Every recorded change at both checkpoints, append-only. Nothing is ever edited or removed.",
    32	};
    33	// steps whose counts add up when folded ("Classified 20 comments" × 153 → "Classified 3,060 comments")
    34	const SUMMABLE = new Set(["classify_comments", "map_study", "map_options", "map_research", "standardize", "duplicates"]);
    35	
    36	const day = (ts: string) => new Date(ts).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });
    37	const time = (ts: string) => new Date(ts).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
    38	const text = (r: Row) => r.summary ?? line({ action: r.action, stage: r.stage ?? "", payload: r.payload });
    39	
    40	const GAP = 10 * 60_000;
    41	function fold(rows: Row[]): Item[] {
    42	  const out: Item[] = [];
    43	  const open = new Map<string, Item>();
    44	  const stream = (r: Row) => `${r.actor_type}|${r.kind}|${r.stage}|${r.action}|${r.checkpoint}`;
    45	  for (const r of rows) {                                    // newest first
    46	    if (r.kind === "run") {                                  // a stage starting or finishing closes its streams
    47	      for (const k of [...open.keys()]) if (k.includes(`|${r.stage}|`) && k.endsWith(`|${r.checkpoint}`)) open.delete(k);
    48	      out.push({ day: day(r.ts), rows: [r] });
    49	      continue;
    50	    }
    51	    const g = open.get(stream(r));
    52	    const prev = g?.rows[g.rows.length - 1];
    53	    if (g && prev && g.day === day(r.ts) && Date.parse(prev.ts) - Date.parse(r.ts) <= GAP) { g.rows.push(r); continue; }
    54	    const item = { day: day(r.ts), rows: [r] };
    55	    out.push(item);
    56	    open.set(stream(r), item);
    57	  }
    58	  return out;
    59	}
    60	
    61	function foldText(rows: Row[]) {
    62	  const f = rows[0];
    63	  if (rows.length === 1 || f.summary != null || !SUMMABLE.has(f.action)) return text(f);
    64	  const payload: Record<string, unknown> = { ...f.payload };
    65	  for (const k of Object.keys(payload)) {
    66	    if (typeof payload[k] === "number") payload[k] = rows.reduce((s, r) => s + (Number(r.payload[k]) || 0), 0);
    67	  }
    68	  return line({ action: f.action, stage: f.stage ?? "", payload });
    69	}
