 31	                               staleTime: 30_000, placeholderData: (prev) => prev });
 32	  const [hoverKey, setHoverKey] = useState<string | null>(null);
 33	  const activity = useActivity();
 34	  // when a stage finishes, show its output without a reload
 35	  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
 36	  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
 37	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
 38	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
 39	  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
 40	  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
 41	  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
 42	    const vals = new Set(f[d]);
 43	    if (vals.has(v)) vals.delete(v); else vals.add(v);
 44	    const next = { ...f, [d]: vals };
 45	    if (!vals.size) delete next[d];
 46	    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
 47	  });
 48	  const clear = (d?: Dim) => setChosen(({ f, order }) => {
 49	    if (!d) return { f: {}, order: [] };
 50	    const next = { ...f }; delete next[d];
 51	    return { f: next, order: order.filter((x) => x !== d) };
 52	  });
 53	  const [hover, setHover] = useState<Hover | null>(null);
