100	                                     onToggle={toggle} onClear={clear} />}
101	        </div>
102	      ) : <Funnel data={structure.data} />}
103	      <Dock mode={mode} sel={selected?.sel ?? null} agent={mode === "structure" ? <AgentPanel /> : undefined} running={!!activity.data?.running} />
