132	/* ------------------------------------------------------------------------------------------- readout */
133	// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
134	// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
135	// While filters are set, every count is what they leave visible.
136	function Readout({ points, mask, filter }: { points: PointsPayload | undefined; mask: Uint8Array; filter: Filter | null }) {
137	  const { current, position } = useCheckpoint();
138	  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
139	  const s = current?.sources;
140	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
141	  const comments = useMemo(() => {
142	    if (!filter || !points) return { n: s?.feedback.visible, nu: s?.feedback.new };
143	    let n = 0, nu = 0;
144	    for (let i = 0; i < points.n; i++) if (mask[i] && points.cols.cp[i] <= position) { n++; if (points.cols.cp[i] === position && position > 1) nu++; }
145	    return { n, nu };
146	  }, [filter, points, mask, position, s]);
147	  const research = (ring: ResearchItem["ring"]) => {
148	    const items = (src?.research ?? []).filter((r) => r.ring === ring && (position > 1 || !r.new) && passResearch(filter, r));
149	    return src ? { n: items.length, nu: items.filter((r) => r.new).length } : undefined;
150	  };
151	  const time = research(null), rating = research("study"), news = research("options"), pub = research("sales");
152	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number; pub?: { label: string; c?: { n: number; nu: number } } }[] = [
153	    { k: "comment", label: "Customer comments", n: comments.n, nu: comments.nu },
154	    { k: "research", label: "Web research", n: time?.n, nu: time?.nu },
155	    { k: "study", label: "Customer study", n: src?.study.filter((x) => passStudy(filter, x)).length, pub: { label: "public ratings", c: rating } },
156	    { k: "option", label: "Equipment options", n: src?.options.filter((x) => passOption(filter, x)).length, pub: { label: "product news", c: news } },
157	    { k: "sales", label: "Sales volumes", n: src?.sales.filter((r) => r.units && r.units > 0 && passSales(filter, r)).length, pub: { label: "public sales", c: pub } },
158	  ];
159	  return (
160	    <dl className="readout" aria-label="Evidence at this checkpoint">
161	      {cells.map((c) => (
162	        <div key={c.label}>
163	          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
164	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
165	          {c.pub && (
166	            <dd className="readout-pub">
167	              <i style={{ borderColor: GLYPH_COLOR[c.k] }} aria-hidden />
168	              <span>{fmt(c.pub.c?.n)} {c.pub.label}</span>{plus(c.pub.c?.nu)}
169	            </dd>
170	          )}
171	        </div>
172	      ))}
173	    </dl>
174	  );
175	}
