177	/* ------------------------------------------------------------------------------------------- filters */
178	// One chip per dimension, under the readout, always shown. Dimensions in use come first, in the order they were set,
179	// so choosing a value never moves a chip that is already set. A toggle at the head of the row folds the unused chips
180	// away (the ones in use stay, so nothing is filtered unseen) and unfolds them to the right again; the choice is kept
181	// per browser. Hovering a chip opens its values; choosing one closes the list again, so only the choice stays. Car and
182	// market filter every data type; the other chips belong to one type and carry its glyph (comments: channel, label,
183	// engine, length; research: trust, topic, fact type; study: result; options: category, availability; sales: year).
184	const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
185	const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";
186	
187	interface FilterProps {
188	  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
189	  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
190	}
191	
192	const FOLD_KEY = "scan.filters.folded";
193	const readFolded = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };
194	
195	function FilterBar(p: FilterProps) {
196	  const [folded, setFolded] = useState(readFolded);
197	  const [open, setOpen] = useState<Dim | null>(null);
198	  const fold = (f: boolean) => {
199	    setFolded(f); setOpen(null);
200	    try { localStorage.setItem(FOLD_KEY, f ? "1" : "0"); } catch { /* storage blocked: the choice just isn't kept */ }
201	  };
202	  const active = p.order.filter((d) => p.filter[d]?.size);
203	  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
204	  return (
205	    <div className="filters" role="toolbar" aria-label="Filter the scan" data-folded={folded ? "" : undefined}>
206	      <button className="filters-fold" aria-expanded={!folded} aria-controls="scan-filter-chips"
207	              aria-label={folded ? "Show all filters" : "Hide unused filters"} title={folded ? "Show all filters" : "Hide unused filters"}
208	              onClick={() => fold(!folded)}>
209	        <SlidersHorizontal size={12} aria-hidden />
210	        {folded && <span>Filter{idle.length ? ` · ${idle.length}` : ""}</span>}
211	        {folded ? <ChevronsRight size={13} aria-hidden /> : <ChevronsLeft size={13} aria-hidden />}
212	      </button>
213	      <div className="filters-chips" id="scan-filter-chips">
214	        {[...active, ...(folded ? [] : idle)].map((d) => (
215	          <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
216	        ))}
217	        {active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
218	      </div>
219	    </div>
220	  );
221	}
