223	function Chip({ dim, open, setOpen, ...p }: FilterProps & { dim: Dim; open: boolean; setOpen: (o: boolean) => void }) {
224	  const meta = DIMS.find((d) => d.id === dim)!;
225	  const chosen = p.filter[dim];
226	  const values = useMemo(() => (open ? keyValues(dim, p.points, p.sources, p.position, p.filter) : []),
227	    [open, dim, p.points, p.sources, p.position, p.filter]);
228	  const max = Math.max(1, ...values.map((v) => v.n));
229	  const names = [...(chosen ?? [])].map((v) => valueName(dim, v));
230	  return (
231	    <div className="fchip" data-on={chosen?.size ? "" : undefined} data-open={open ? "" : undefined}
232	         onPointerEnter={(e) => isMouse(e) && setOpen(true)} onPointerLeave={(e) => isMouse(e) && setOpen(false)}>
233	      <button className="fchip-btn" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
234	        {meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}
235	        <span className="fchip-dim">{meta.name}</span>
236	        {names.length > 0 && <span className="fchip-val">{names[0]}{names.length > 1 ? ` +${names.length - 1}` : ""}</span>}
237	      </button>
238	      {chosen?.size ? <button className="fchip-x" aria-label={`Clear ${meta.name} filter`} onClick={() => p.onClear(dim)}><X size={12} /></button> : null}
239	      {open && (
240	        <div className="fpop">
241	          <div className="fpop-panel" role="listbox" aria-multiselectable aria-label={meta.name}>
242	            <p className="fpop-scope">{meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}{SCOPE_NOTE[meta.scope]}</p>
243	            {values.map(({ v, name, n }) => (
244	              <button key={v} role="option" aria-selected={!!chosen?.has(v)} onClick={() => { p.onToggle(dim, v); setOpen(false); }}>
245	                <span className="fpop-name">{name}</span>
246	                <span className="fpop-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
247	                <span className="fpop-n">{fmt(n)}</span>
248	              </button>
249	            ))}
250	          </div>
251	        </div>
252	      )}
253	    </div>
254	  );
255	}
