 88	// Focus choreography: the chosen layer springs up (slight overshoot) with a soft scale pulse; the others sink and
 89	// fade in a ripple outward from it. Releasing focus ripples back the same way. Under reduced motion the layers still
 90	// glide (the move is what shows which layer the item belongs to), just without overshoot, pulse or ripple.
 91	function Layer({ id, focus, children }: { id: LayerId; focus: LayerId | null; children: ReactNode }) {
 92	  const ref = useRef<THREE.Group>(null);
 93	  const st = useRef({ y: 0, a: 1, fy: 0, fa: 1, t0: -1, delay: 0, rising: false, focus: null as LayerId | null });
 94	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
 95	  useFrame(({ clock }) => {
 96	    const g = ref.current;
 97	    if (!g) return;
 98	    const s = st.current, now = clock.elapsedTime;
 99	    if (s.focus !== focus) {                 // new target: start a tween from wherever the layer is now
100	      const anchor = focus ?? s.focus;       // ripple out from the layer gaining (or losing) focus
101	      s.focus = focus;
102	      s.fy = s.y; s.fa = s.a; s.t0 = now; s.rising = focus === id;
103	      s.delay = reduced || anchor == null || s.rising ? 0 : Math.abs(ORDER.indexOf(id) - ORDER.indexOf(anchor)) * STAGGER;
104	    }
105	    const [ty, ta] = focus == null ? [0, 1] : focus === id ? [LIFT, 1] : [SINK, FADE];
106	    let p = 1;
107	    if (s.t0 >= 0) p = Math.min(1, Math.max(0, (now - s.t0 - s.delay) / (s.rising ? RISE : FALL)));
108	    if (p >= 1 && s.y === ty && s.a === ta && g.userData.settled === children) return;
109	    s.y = s.fy + (ty - s.fy) * (s.rising && !reduced ? easeOutBack(p) : easeInOut(p));
110	    s.a = s.fa + (ta - s.fa) * easeOut(p);
111	    if (p >= 1) { s.y = ty; s.a = ta; }
112	    g.position.y = s.y;
113	    g.scale.setScalar(s.rising && !reduced ? 1 + 0.04 * Math.sin(Math.PI * p) : 1);
114	    g.userData.settled = children;
115	    g.traverse((o) => {
116	      const mat = (o as THREE.Mesh).material;
117	      if (!mat) return;
118	      for (const m of Array.isArray(mat) ? mat : [mat]) {
119	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uFade) m.uniforms.uFade.value = s.a; continue; }
120	        if (m.userData.written !== m.opacity) m.userData.baseOpacity = m.opacity;   // React set a new opacity (e.g. a filter)
121	        m.opacity = m.userData.written = m.userData.baseOpacity * s.a;
122	      }
123	    });
124	  });
125	  return <group ref={ref}>{children}</group>;
126	}
