130	type LabelState = "rest" | "up" | "down";
131	function LabelLift({ state, children }: { state: LabelState; children: ReactNode }) {
132	  const ref = useRef<THREE.Group>(null);
133	  const st = useRef({ fy: 0, t0: -1, state: "rest" as LabelState });
134	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
135	  useFrame(({ clock }) => {
136	    const g = ref.current;
137	    if (!g) return;
138	    const s = st.current, now = clock.elapsedTime;
139	    if (s.state !== state) { s.state = state; s.fy = g.position.y; s.t0 = now; }
140	    if (s.t0 < 0) return;
141	    const up = state === "up", ty = state === "rest" ? 0 : up ? LIFT : SINK;
142	    const p = Math.min(1, (now - s.t0) / (up ? RISE : FALL));
143	    g.position.y = s.fy + (ty - s.fy) * (up && !reduced ? easeOutBack(p) : easeInOut(p));
