 20	const NODE_VERT = /* glsl */ `
 21	attribute float aState; attribute float aPol; attribute float aSize; attribute float aIdx;
 22	uniform float uScale, uShow, uHover;
 23	varying float vState; varying float vPol; varying float vHov;
 24	void main() {
