 50	 *  container they live in, and they are taken out entirely at 0: on the Evidence page none of them show. */
 51	function FadeIn({ morph, children }: { morph: MutableRefObject<number>; children: ReactNode }) {
 52	  const ref = useRef<THREE.Group>(null);
 53	  // the element drei <Html> mounts its labels into (the event source, else the canvas's parent)
 54	  const host = useThree((s) => ((s.events.connected as HTMLElement | undefined) ?? s.gl.domElement.parentElement) as HTMLElement | null);
 55	  const last = useRef(-1);
 56	  useFrame(() => {
 57	    const g = ref.current;
 58	    if (!g) return;
 59	    const a = Math.max(0, (morph.current - 0.45) / 0.55);
 60	    g.visible = a > 0.01;
 61	    if (host && Math.abs(a - last.current) > 0.004) {
 62	      last.current = a;
 63	      host.style.setProperty("--structure-fade", a.toFixed(3));
 64	      host.toggleAttribute("data-structure-off", a <= 0.01);
 65	    }
 66	    g.traverse((o) => {
 67	      const mat = (o as THREE.Mesh).material;
 68	      if (!mat) return;
 69	      for (const m of Array.isArray(mat) ? mat : [mat]) {
 70	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uShow) m.uniforms.uShow.value = a; continue; }
