124	export function StructureLayer(p: Props) {
125	  const clusters = useMemo(() => p.data.clusters.filter((c) => c.comments > 0 && !c.tail), [p.data]);
126	  const themeOf = useMemo(() => Object.fromEntries(p.data.themes.map((t) => [t.key, t])), [p.data]);
127	
128	
129	  /* cluster nodes */
130	  const nodeMat = useMemo(() => new THREE.ShaderMaterial({
131	    vertexShader: NODE_VERT, fragmentShader: NODE_FRAG, transparent: true, depthWrite: false,
132	    uniforms: { uScale: { value: 24 * p.dpr }, uShow: { value: 0 }, uHover: { value: -1 } },
133	  }), [p.dpr]);
134	  const nodes = useMemo(() => {
135	    const n = clusters.length;
136	    const pos = new Float32Array(n * 3), st = new Float32Array(n), pol = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
137	    clusters.forEach((c, i) => {
138	      pos.set([c.x, c.y, c.z], i * 3);
139	      st[i] = STATE_CODE[c.state ?? "held"]; pol[i] = c.polarity === "improve" ? 1 : 0;
140	      size[i] = 1.2 + Math.sqrt(c.comments) * 0.32; idx[i] = i;
141	    });
142	    const g = new THREE.BufferGeometry();
143	    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
144	    for (const [k, v] of Object.entries({ aState: st, aPol: pol, aSize: size, aIdx: idx })) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
145	    g.computeBoundingSphere();
146	    return g;
147	  }, [clusters]);
148	  nodeMat.uniforms.uHover.value = Math.max(-1, clusters.findIndex((c) => c.key === p.hoverKey));
149	
150	  /* cluster → theme lines */
151	  const memberLines = useMemo(() => {
152	    const v: number[] = [];
153	    for (const c of clusters) {
154	      const t = c.theme ? themeOf[c.theme] : null;
155	      if (t) v.push(c.x, c.y, c.z, t.x, t.y, t.z);
156	    }
157	    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
158	  }, [clusters, themeOf]);
159	
160	  /* requirement areas float on a ring above the galaxy: each at an evenly spaced slot, in the order of its themes'
161	     bearing, so labels never pile up over the centre; stems tie every area to its themes below */
162	  const areas = useMemo(() => {
163	    const placed: { a: AreaNode; ts: ThemeNode[]; bearing: number }[] = [];
164	    for (const a of p.data.areas) {
165	      const ts = a.themes.map((k) => themeOf[k]).filter(Boolean);
166	      if (!ts.length) continue;
167	      const w = ts.reduce((n, t) => n + (t.comments || 1), 0);
168	      const x = ts.reduce((n, t) => n + t.x * (t.comments || 1), 0) / w, z = ts.reduce((n, t) => n + t.z * (t.comments || 1), 0) / w;
169	      placed.push({ a, ts, bearing: Math.atan2(z, x) });
170	    }
171	    placed.sort((m, n) => m.bearing - n.bearing);
172	    const n = placed.length || 1;
173	    return placed.map(({ a, ts }, i) => {
174	      const ang = (i / n) * Math.PI * 2 - Math.PI / 2;
175	      const r = a.kind === "quality" ? 0.35 : 1.05;
176	      const y = a.kind === "quality" ? AREA_Y - 0.25 : AREA_Y + (i % 2) * 0.12;   // alternate heights for neighbours
177	      return { a, ts, at: [r * Math.cos(ang), y, r * Math.sin(ang)] as [number, number, number] };
178	    });
179	  }, [p.data, themeOf]);
180	  const focusArea = p.selected?.kind === "area" ? p.selected.key : null;
181	  const stems = useMemo(() => {
182	    const v: number[] = [], hot: number[] = [];
183	    for (const { a, at, ts } of areas) for (const t of ts) (a.key === focusArea ? hot : v).push(t.x, t.y, t.z, ...at);
184	    const g = (xs: number[]) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(xs, 3));
185	    return { all: g(v), hot: g(hot) };
186	  }, [areas, focusArea]);
187	
188	  /* evidence arcs for the theme in focus */
189	  const focusTheme = p.selected?.kind === "theme" ? p.selected.key
190	    : p.selected?.kind === "cluster" ? clusters.find((c) => c.key === (p.selected as { key: string }).key)?.theme ?? null
191	    : p.hoverKey && themeOf[p.hoverKey] ? p.hoverKey : null;
192	  const arcs = useMemo(() => {
193	    if (!focusTheme || !themeOf[focusTheme]) return [];
194	    const t = themeOf[focusTheme];
195	    const out: THREE.Line[] = [];
196	    for (const e of p.data.edges) {
197	      if (e.dst_id !== focusTheme || !(e.src_type in SRC_COLOR)) continue;
198	      const end = p.ends(e.src_type, e.src_id);
199	      if (!end) continue;
200	      const a = new THREE.Vector3(t.x, t.y, t.z), b = new THREE.Vector3(...end);
201	      const mid = a.clone().lerp(b, 0.5).add(new THREE.Vector3(0, 0.45 + a.distanceTo(b) * 0.15, 0));
202	      const pts = new THREE.QuadraticBezierCurve3(a, mid, b).getPoints(40);
203	      const geom = new THREE.BufferGeometry().setFromPoints(pts);
204	      const contra = e.relation === "contradicts";
205	      const line = new THREE.Line(geom, contra
206	        ? new THREE.LineDashedMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.7, dashSize: 0.03, gapSize: 0.03 })
207	        : new THREE.LineBasicMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.85 }));
208	      if (contra) line.computeLineDistances();
209	      out.push(line);
210	    }
211	    return out;
212	  }, [focusTheme, themeOf, p.data, p.ends]);
213	
214	  const topThemes = useMemo(() => [...p.data.themes].sort((a, b) => b.comments - a.comments).slice(0, 8).map((t) => t.key), [p.data]);
215	  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) => e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
216	  const register = useLabelCollisions();
217	
218	  return (
219	    <LabelCtx.Provider value={register}>
220	    <FadeIn morph={p.morph}>
221	      <lineSegments geometry={memberLines}><lineBasicMaterial color="#ffffff" transparent opacity={0.07} /></lineSegments>
222	      <points geometry={nodes} material={nodeMat}
223	              onPointerMove={(e) => {
224	                const i = pick(e); if (i == null) return;
225	                const c = clusters[i]; e.stopPropagation(); p.setCursor(true);
226	                p.onHover({ title: c.insight?.title ?? c.category ?? "Cluster", sub: `${c.comments} comments · ${c.state ?? ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, c.key);
227	              }}
228	              onPointerOut={() => { p.setCursor(false); p.onHover(null, null); }}
229	              onClick={(e) => { const i = pick(e); if (i == null) return; e.stopPropagation(); const c = clusters[i]; p.onSelect({ kind: "cluster", key: c.key }, [c.x, c.y, c.z]); }} />
230	      {p.data.themes.map((t) => <ThemeHalo key={t.key} t={t} active={t.key === focusTheme} label={topThemes.includes(t.key) || t.key === focusTheme}
231	                                            hot={p.hoverKey === t.key}
232	                                            onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
233	      <lineSegments geometry={stems.all}><lineBasicMaterial color="#ffffff" transparent opacity={0.12} /></lineSegments>
234	      <lineSegments geometry={stems.hot}><lineBasicMaterial color="#ffffff" transparent opacity={0.7} /></lineSegments>
235	      {areas.map(({ a, at }) => <Diamond key={a.key} a={a} at={at} active={focusArea === a.key} hot={p.hoverKey === a.key}
236	                                         onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
237	      {arcs.map((l, i) => <primitive key={`${focusTheme}-${i}`} object={l} />)}
238	    </FadeIn>
239	    </LabelCtx.Provider>
240	  );
241	}
