243	function ThemeHalo({ t, active, hot, label, onHover, onSelect, setCursor }: {
244	  t: ThemeNode; active: boolean; hot: boolean; label: boolean;
245	  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
246	}) {
247	  const r = 0.05 + Math.sqrt(t.comments) * 0.006;
248	  const lost = t.state === "lost", changed = t.state === "strengthened" || t.state === "new";
249	  const register = useContext(LabelCtx);
250	  const { k } = useSpread();   // the halo keeps its size when the spread opens the universe up
251	  return (
252	    <Billboard position={[t.x, t.y, t.z]} scale={k}>
253	      <mesh onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: t.title, sub: `Theme · ${t.comments} comments${t.state ? ` · ${t.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, t.key); }}
254	            onPointerOut={() => { setCursor(false); onHover(null, null); }}
255	            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "theme", key: t.key }, [t.x, t.y, t.z]); }}>
256	        <ringGeometry args={[r, r + (active ? 0.008 : 0.004), 48]} />
257	        <meshBasicMaterial color={lost ? "#f5a524" : "#ffffff"} transparent opacity={active ? 0.95 : changed ? 0.55 : 0.32} depthWrite={false} />
258	      </mesh>
259	      {label && (
260	        <Html position={[0, r + 0.06, 0]} center zIndexRange={[12, 0]}>
261	          <div className="theme-label" data-active={active ? "" : undefined}
262	               ref={register(`theme:${t.key}`, active || hot ? FOCUS : t.comments)}>{t.title}</div>
263	        </Html>
264	      )}
265	    </Billboard>
266	  );
267	}
