269	function Diamond({ a, at, active, hot, onHover, onSelect, setCursor }: {
270	  a: AreaNode; at: [number, number, number]; active: boolean; hot: boolean;
271	  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
272	}) {
273	  const ref = useRef<THREE.Mesh>(null);
274	  const register = useContext(LabelCtx);
275	  useFrame((_, dt) => { if (ref.current) ref.current.rotation.y += dt * (active ? 1.6 : 0.4); });
276	  const quality = a.kind === "quality";
277	  const color = quality ? "#f5a524" : a.kind === "keep" ? "#eef1f5" : a.kind === "emerging" ? "#d95926" : "#3987e5";
278	  const size = 0.028 + Math.min(0.03, Math.sqrt(a.metrics.comments ?? 1) * 0.0012);
279	  const { k } = useSpread();
280	  return (
281	    <group position={at} scale={k}>
282	      <mesh ref={ref}
283	            onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: a.title, sub: quality ? "Quality hand-over" : `Requirement area · ${a.kind} · ${a.metrics.comments ?? 0} comments${a.state ? ` · ${a.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, a.key); }}
284	            onPointerOut={() => { setCursor(false); onHover(null, null); }}
285	            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "area", key: a.key }, at); }}>
286	        <octahedronGeometry args={[active ? size * 1.5 : size, 0]} />
287	        <meshBasicMaterial color={color} wireframe={a.state === "new" || quality} transparent opacity={active ? 1 : 0.9} />
288	      </mesh>
289	      {(active || (a.metrics.comments ?? 0) > 0) && (
290	        <Html position={[0, size + 0.05, 0]} center zIndexRange={[12, 0]}>
291	          <div className="area-label" data-active={active ? "" : undefined}
292	               ref={register(`area:${a.key}`, active || hot ? FOCUS : AREA + (a.metrics.comments ?? 0))}>{a.title}</div>
293	        </Html>
294	      )}
295	    </group>
296	  );
297	}
