275	// ------------------------------------------------------------------------------------------------ zone glow + x-ray
276	function ZoneFocus({
277	  carRef,
278	  carVersion,
279	  target,
280	  xray,
281	  reduced,
282	}: {
283	  carRef: React.RefObject<THREE.Object3D | null>;
284	  carVersion: number;
285	  target: Vec3 | null;
286	  xray: boolean;
287	  reduced: boolean;
288	}) {
289	  const sprite = useRef<THREE.Sprite>(null);
290	  const pool = useRef<THREE.Mesh>(null);
291	  const light = useRef<THREE.PointLight>(null);
292	  const mats = useRef<MatState[]>([]);
293	  const k = useRef(0); // x-ray amount 0..1
294	  const g = useRef(0); // glow amount 0..1
295	  const tex = useMemo(() => glowTexture(), []);
296	  const lastTarget = useRef<Vec3>([0, 0, 0]);
297	
298	  useEffect(() => {
299	    mats.current = carRef.current ? collectMaterials(carRef.current) : [];
300	    k.current = 0;
301	    return () => {
302	      for (const s of mats.current) {
303	        s.m.opacity = s.opacity;
304	        s.m.transparent = s.transparent;
305	        s.m.depthWrite = s.depthWrite;
306	        s.m.needsUpdate = true;
307	      }
308	    };
309	  }, [carRef, carVersion]);
310	
311	  if (target) lastTarget.current = target;
312	
313	  useFrame((_, dt) => {
314	    const rate = reduced ? 1 : 1 - Math.exp(-dt * 4.5);
315	    const kGoal = xray ? 1 : 0;
316	    const gGoal = target ? 1 : 0;
317	    const kPrev = k.current;
318	    k.current += (kGoal - k.current) * rate;
319	    if (Math.abs(k.current - kGoal) < 0.002) k.current = kGoal;
320	    g.current += (gGoal - g.current) * rate;
321	    if (Math.abs(g.current - gGoal) < 0.002) g.current = gGoal;
322	
323	    if (kPrev !== k.current || (k.current > 0 && kPrev === 0)) {
324	      const kk = k.current;
325	      for (const s of mats.current) {
326	        const wantTransparent = kk > 0.001 ? true : s.transparent;
327	        const wantDepth = kk > 0.35 ? false : s.depthWrite;
328	        if (s.m.transparent !== wantTransparent) {
329	          s.m.transparent = wantTransparent;
330	          s.m.needsUpdate = true;
331	        }
332	        s.m.depthWrite = wantDepth;
333	        s.m.opacity = s.opacity + (Math.min(s.opacity, XRAY_OPACITY) - s.opacity) * kk;
334	      }
335	    }
336	
337	    const [x, y, z] = lastTarget.current;
338	    const gg = g.current;
339	    if (sprite.current) {
340	      sprite.current.position.set(x, y, z);
341	      const pulse = reduced ? 1 : 1 + Math.sin(performance.now() / 700) * 0.06;
342	      sprite.current.scale.setScalar(1.5 * pulse * (0.6 + 0.4 * gg));
343	      (sprite.current.material as THREE.SpriteMaterial).opacity = 0.55 * gg;
344	      sprite.current.visible = gg > 0.01;
345	    }
346	    if (pool.current) {
347	      pool.current.position.set(x, 0.006, z);
348	      (pool.current.material as THREE.MeshBasicMaterial).opacity = 0.5 * gg;
349	      pool.current.visible = gg > 0.01;
350	    }
351	    if (light.current) {
352	      light.current.position.set(x, y + 0.25, z);
353	      light.current.intensity = 6 * gg;
354	    }
355	  });
356	
357	  return (
358	    <>
359	      <sprite ref={sprite} renderOrder={10} visible={false}>
360	        <spriteMaterial map={tex} color={THEME.blueBright} transparent depthTest={false} depthWrite={false} blending={THREE.AdditiveBlending} toneMapped={false} />
361	      </sprite>
362	      <mesh ref={pool} rotation-x={-Math.PI / 2} renderOrder={2} visible={false}>
363	        <planeGeometry args={[3.2, 3.2]} />
364	        <meshBasicMaterial map={tex} color={THEME.blue} transparent depthWrite={false} blending={THREE.AdditiveBlending} toneMapped={false} />
365	      </mesh>
366	      <pointLight ref={light} color={THEME.blueBright} intensity={0} distance={3.2} decay={2} />
367	    </>
368	  );
369	}
