372	// Pins are plain DOM in an overlay above the canvas (normal React tree, crisp text, real <button>s).
373	// A projector inside the canvas writes their screen transform/opacity every frame through refs.
374	type PinItem = { h: Hotspot; z: ZoneDef; pos: THREE.Vector3; facing: THREE.Vector3 };
375	type PinEls = Map<string, HTMLDivElement>;
376	
377	function PinProjector({
378	  items,
379	  els,
380	  xray,
381	  selectedZone,
382	}: {
383	  items: PinItem[];
384	  els: React.RefObject<PinEls>;
385	  xray: boolean;
386	  selectedZone: string | null;
387	}) {
388	  const tmp = useMemo(() => new THREE.Vector3(), []);
389	  const last = useRef(new Map<string, { x: number; y: number; o: string; z: number }>());
390	  useFrame(({ camera, size }) => {
391	    const map = els.current;
392	    for (const it of items) {
393	      const el = map.get(it.h.zone);
394	      if (!el) continue;
395	      tmp.copy(it.pos).project(camera);
396	      const visible = tmp.z < 1 && Math.abs(tmp.x) < 1.2 && Math.abs(tmp.y) < 1.2;
397	      const x = Math.round((tmp.x * 0.5 + 0.5) * size.width * 10) / 10;
398	      const y = Math.round((-tmp.y * 0.5 + 0.5) * size.height * 10) / 10;
399	      tmp.copy(camera.position).sub(it.pos).normalize();
400	      const sel = it.h.zone === selectedZone;
401	      const behind = !xray && !sel && tmp.dot(it.facing) < -0.05;
402	      const o = !visible ? "0" : behind ? "0.3" : "1";
403	      const zi = sel ? 30 : behind ? 5 : 10 + Math.round((1 - Math.min(1, camera.position.distanceTo(it.pos) / 30)) * 10);
404	      const prev = last.current.get(it.h.zone);
405	      if (!prev || prev.x !== x || prev.y !== y) el.style.transform = `translate3d(${x}px, ${y}px, 0)`;
406	      if (!prev || prev.o !== o) {
407	        el.style.opacity = o;
408	        el.style.visibility = o === "0" ? "hidden" : "visible";
409	      }
410	      if (!prev || prev.z !== zi) el.style.zIndex = String(zi);
411	      if (prev) {
412	        prev.x = x;
413	        prev.y = y;
414	        prev.o = o;
415	        prev.z = zi;
416	      } else last.current.set(it.h.zone, { x, y, o, z: zi });
417	    }
418	  });
419	  return null;
420	}
