642	  const reduced = usePrefersReducedMotion();
643	  const compact = mode === "compact";
644	  const [failedUrl, setFailedUrl] = useState<string | null>(null);
645	  const modelFailed = !!modelUrl && failedUrl === modelUrl;
646	  const down = useRef<{ x: number; y: number } | null>(null);
647	  // stable orientation identity so the model isn't re-normalised on every parent render
648	  const orient = useMemo<Orientation>(() => ({ up: orientation.up, front: orientation.front }), [orientation.up, orientation.front]);
649	
650	  const onModelError = useCallback(
651	    (e: Error) => {
652	      console.warn("[CarStage] model failed to load, showing placeholder:", modelUrl, e);
653	      setFailedUrl(modelUrl);
654	    },
655	    [modelUrl],
656	  );
657	
658	  const showNote = !modelUrl || modelFailed;
659	
660	  const [frame, setFrame] = useState<CarFrame>(PLACEHOLDER_FRAME);
661	  const onFrame = useCallback((f: CarFrame) => {
662	    setFrame((prev) => (prev.L === f.L && prev.W === f.W && prev.H === f.H ? prev : f));
663	  }, []);
664	  const pinEls = useRef<PinEls>(new Map());
665	  const pinItems = useMemo<PinItem[]>(
666	    () =>
667	      hotspots
668	        .filter((h) => zones[h.zone])
669	        .map((h) => {
670	          const z = zones[h.zone];
671	          return { h, z, pos: new THREE.Vector3(...zoneToWorld(z.pos, frame)), facing: new THREE.Vector3(...frameDir(z.view)) };
672	        }),
673	    [hotspots, zones, frame],
674	  );
675	
676	  return (
677	    <div
678	      className={`cs-root${compact ? " cs-compact" : ""}${className ? ` ${className}` : ""}`}
679	      tabIndex={-1}
680	      onKeyDown={(e) => {
681	        if (e.key === "Escape" && selectedZone) onSelectZone(null);
682	      }}
683	      onPointerDown={(e) => {
684	        down.current = { x: e.clientX, y: e.clientY };
685	      }}
686	    >
687	      <Canvas
688	        dpr={[1, 2]}
689	        frameloop="always"
690	        shadows={false}
691	        gl={{ antialias: true, powerPreference: "high-performance" }}
692	        camera={{ fov: 40, near: 0.1, far: 80, position: poseFor(null, PLACEHOLDER_FRAME).eye }}
693	        onCreated={({ gl }) => {
694	          gl.toneMapping = THREE.ACESFilmicToneMapping;
695	          gl.toneMappingExposure = 1.15;
696	        }}
697	        onPointerMissed={(e) => {
698	          const d = down.current;
699	          if (compact || !d || Math.hypot(e.clientX - d.x, e.clientY - d.y) > 4) return;
700	          if (selectedZone) onSelectZone(null);
701	        }}
702	      >
703	        <Scene
704	          modelUrl={modelUrl}
705	          orientation={orient}
706	          frame={frame}
707	          onFrame={onFrame}
708	          zones={zones}
709	          pinItems={pinItems}
710	          pinEls={pinEls}
711	          selectedZone={selectedZone}
712	          compact={compact}
713	          reduced={reduced}
714	          onModelError={onModelError}
715	          modelFailed={modelFailed}
716	        />
717	      </Canvas>
718	      <PinLayer items={pinItems} els={pinEls} selectedZone={selectedZone} hoverZone={hoverZone} onSelectZone={onSelectZone} />
719	      <LoadingLine />
720	      {showNote && !compact && <div className="cs-note">3D

