     1	// The checkpoint is app-wide state: every screen reads what is visible at the current checkpoint, and every screen
     2	// can animate the change from the previous one (the sweep). The URL (?cp=) is the source of truth so a view can be
     3	// linked; ← / → step between checkpoints anywhere in the app.
     4	import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
     5	import { useQuery } from "@tanstack/react-query";
     6	import { useSearchParams } from "react-router-dom";
     7	import { api } from "@/lib/api";
     8	import type { Checkpoint, CheckpointId } from "@/lib/types";
     9	
    10	const ORDER: CheckpointId[] = ["cp1", "cp2"];
    11	const isCp = (v: string | null): v is CheckpointId => v === "cp1" || v === "cp2";
    12	
    13	interface Ctx {
    14	  cp: CheckpointId;
    15	  from: CheckpointId;        // checkpoint before the latest switch (equals cp when settled)
    16	  sweepId: number;           // increments on every switch; screens restart their sweep on change
    17	  setCp: (cp: CheckpointId) => void;
    18	  checkpoints: Checkpoint[] | undefined;
    19	  current: Checkpoint | undefined;
    20	  position: number;          // 1 | 2
    21	}
    22	
    23	const CheckpointCtx = createContext<Ctx | null>(null);
    24	
    25	export function CheckpointProvider({ children }: { children: ReactNode }) {
    26	  const [params, setParams] = useSearchParams();
    27	  const urlCp = params.get("cp");
    28	  // No checkpoint in the URL: open at the first one and play the sweep to the latest once (the signature moment).
    29	  const arrival = useRef(!isCp(urlCp));
    30	  const cp: CheckpointId = isCp(urlCp) ? urlCp : "cp1";
    31	  const prev = useRef<CheckpointId>(cp);
    32	  const [from, setFrom] = useState<CheckpointId>(cp);
    33	  const [sweepId, setSweepId] = useState(0);
    34	  const { data: checkpoints } = useQuery({ queryKey: ["checkpoints"], queryFn: () => api.get<Checkpoint[]>("/api/checkpoints") });
    35	
    36	  useEffect(() => {
    37	    if (prev.current !== cp) {
    38	      setFrom(prev.current);
    39	      setSweepId((n) => n + 1);
    40	      prev.current = cp;
    41	    }
    42	  }, [cp]);
    43	
    44	  const setCp = useCallback(
    45	    (next: CheckpointId) => {
    46	      setParams((p) => { const q = new URLSearchParams(p); q.set("cp", next); return q; }, { replace: true });
    47	    },
    48	    [setParams],
    49	  );
    50	
    51	  useEffect(() => {
    52	    if (!arrival.current || !checkpoints) return;
    53	    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    54	    const t = window.setTimeout(() => { arrival.current = false; setCp(ORDER[ORDER.length - 1]); }, reduced ? 0 : 1200);
    55	    return () => window.clearTimeout(t);
    56	  }, [checkpoints, setCp]);
    57	
    58	  useEffect(() => {
    59	    const onKey = (e: KeyboardEvent) => {
    60	      if (e.target instanceof HTMLElement && e.target.closest("input, textarea, [contenteditable]")) return;
    61	      const i = ORDER.indexOf(cp);
    62	      if (e.key === "ArrowRight" && i < ORDER.length - 1) setCp(ORDER[i + 1]);
    63	      if (e.key === "ArrowLeft" && i > 0) setCp(ORDER[i - 1]);
    64	    };
    65	    window.addEventListener("keydown", onKey);
    66	    return () => window.removeEventListener("keydown", onKey);
    67	  }, [cp, setCp]);
    68	
    69	  const value = useMemo<Ctx>(() => {
    70	    const current = checkpoints?.find((c) => c.id === cp);
    71	    return { cp, from, sweepId, setCp, checkpoints, current, position: ORDER.indexOf(cp) + 1 };
    72	  }, [cp, from, sweepId, setCp, checkpoints]);
    73	
    74	  return <CheckpointCtx.Provider value={value}>{children}</CheckpointCtx.Provider>;
    75	}
