    31	async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
    32	  let res: Response;
    33	  try {
    34	    res = await fetch(path, {
    35	      method,
    36	      headers: { "Content-Type": "application/json", "X-Actor": getActor() },
    37	      body: body === undefined ? undefined : JSON.stringify(body),
    38	    });
    39	  } catch {
    40	    throw new ApiError(0, "The local API isn't reachable. Start it with `uv run python -m api`.");
    41	  }
    42	  if (!res.ok) {
    43	    let msg = `${res.status} ${res.statusText}`;
    44	    try {
    45	      const j = await res.json();
    46	      if (typeof j.detail === "string") msg = j.detail;
    47	      else if (Array.isArray(j.detail)) msg = j.detail.map((d: { msg?: string }) => d.msg).join("; ");
    48	    } catch {
    49	      /* keep status text */
    50	    }
    51	    throw new ApiError(res.status, msg);
    52	  }
    53	  if (res.status === 204) return undefined as T;
    54	  return (await res.json()) as T;
    55	}
