     1	// Moving through the scan volume. Spread scales the whole universe (layout positions) while marks grow only by its
     2	// square root, so the space between contacts opens up instead of everything just getting bigger. The camera scales
     3	// with it, so the framing holds and the PM can then fly in. Flying moves the camera and the orbit centre together:
     4	// W/S forward and back, A/D sideways, Q/E down and up (Shift: faster), or hold the pad's buttons.
     5	import { createContext, useContext, useEffect, useRef, type MutableRefObject, type PointerEvent as ReactPointerEvent } from "react";
     6	import { useFrame, useThree } from "@react-three/fiber";
     7	import { ArrowDown, ArrowUp, LocateFixed } from "lucide-react";
     8	import * as THREE from "three";
     9	
    10	export const SPREAD_MIN = 1, SPREAD_MAX = 4;
    11	export const HOME: [number, number, number] = [0, 2.3, 5.3];
    12	
    13	/** spread: layout scale; grow: how much marks grow with it; k: counter-scale for a mark inside the scaled world */
    14	export interface Spread { spread: number; grow: number; k: number }
    15	const make = (spread: number): Spread => { const grow = Math.sqrt(spread); return { spread, grow, k: grow / spread }; };
    16	export const spreadOf = make;
    17	export const SpreadCtx = createContext<Spread>(make(1));
    18	export const useSpread = () => useContext(SpreadCtx);
    19	
    20	/** what the pad's buttons hold down; reset counts up once per press */
    21	export interface NavInput { fwd: number; reset: number }
    22	export const newNav = (): NavInput => ({ fwd: 0, reset: 0 });
    23	
    24	const KEYS: Record<string, [number, number, number]> = {   // [forward, right, up]
    25	  w: [1, 0, 0], s: [-1, 0, 0], a: [0, -1, 0], d: [0, 1, 0], e: [0, 0, 1], q: [0, 0, -1],
    26	};
    27	const typing = (t: EventTarget | null) =>
    28	  t instanceof HTMLElement && (t.isContentEditable || /^(TEXTAREA|SELECT)$/.test(t.tagName) ||
    29	                               (t instanceof HTMLInputElement && !/^(range|checkbox|radio|button)$/.test(t.type)));
    30	
    31	type Orbit = { target: THREE.Vector3; update: () => void };
    32	
    33	export function Navigator({ spread, nav, fit }: { spread: number; nav: MutableRefObject<NavInput>; fit: () => number }) {
    34	  const { camera } = useThree();
    35	  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
    36	  const prev = useRef(spread);
    37	  const held = useRef(new Set<string>());
    38	  const fast = useRef(false);
    39	  const home = useRef<{ t0: number; from: THREE.Vector3; fromT: THREE.Vector3 } | null>(null);
    40	  const lastReset = useRef(nav.current.reset);
    41	
    42	  // spread changed: scale camera and orbit centre with the world, so the view keeps its framing
    43	  useEffect(() => {
    44	    const k = spread / prev.current;
    45	    prev.current = spread;
    46	    if (k === 1) return;
    47	    camera.position.multiplyScalar(k);
    48	    controls?.target.multiplyScalar(k);
    49	    controls?.update();
    50	  }, [spread, camera, controls]);
    51	
    52	  useEffect(() => {
    53	    const down = (e: KeyboardEvent) => {
    54	      if (e.metaKey || e.ctrlKey || e.altKey || typing(e.target)) return;
    55	      const key = e.key.toLowerCase();
    56	      fast.current = e.shiftKey;
    57	      if (KEYS[key]) { held.current.add(key); e.preventDefault(); }
    58	    };
    59	    const up = (e: KeyboardEvent) => { fast.current = e.shiftKey; held.current.delete(e.key.toLowerCase()); };
    60	    const clear = () => held.current.clear();
    61	    window.addEventListener("keydown", down);
    62	    window.addEventListener("keyup", up);
    63	    window.addEventListener("blur", clear);
    64	    return () => { window.removeEventListener("keydown", down); window.removeEventListener("keyup", up); window.removeEventListener("blur", clear); };
    65	  }, []);
    66	
    67	  const fwd = new THREE.Vector3(), right = new THREE.Vector3(), step = new THREE.Vector3();
    68	  useFrame(({ clock }, dt) => {
    69	    if (!controls) return;
    70	    // reset: glide back to the opening view at the current spread
    71	    if (nav.current.reset !== lastReset.current) {
    72	      lastReset.current = nav.current.reset;
    73	      home.current = { t0: clock.elapsedTime, from: camera.position.clone(), fromT: controls.target.clone() };
    74	    }
    75	    if (home.current) {
    76	      const h = home.current, p = Math.min(1, (clock.elapsedTime - h.t0) / 0.7), e = 1 - Math.pow(1 - p, 3);
    77	      const goal = new THREE.Vector3(...HOME).setLength(fit() * spread);
    78	      camera.position.lerpVectors(h.from, goal, e);
    79	      controls.target.lerpVectors(h.fromT, new THREE.Vector3(), e);
    80	      controls.update();
    81	      if (p >= 1) home.current = null;
    82	      return;
    83	    }
    84	    let f = nav.current.fwd, r = 0, u = 0;
    85	    for (const k of held.current) { const [a, b, c] = KEYS[k]; f += a; r += b; u += c; }
    86	    if (!f && !r && !u) return;
    87	    camera.getWorldDirection(fwd);
    88	    right.crossVectors(fwd, camera.up).normalize();
    89	    const speed = 1.4 * spread * (fast.current ? 2.5 : 1) * Math.min(dt, 0.05);
    90	    step.copy(fwd).multiplyScalar(f).addScaledVector(right, r).addScaledVector(camera.up, u).multiplyScalar(speed);
    91	    camera.position.add(step);
    92	    controls.target.add(step);
    93	    controls.update();
    94	  });
    95	  return null;
    96	}
