    98	/** Bottom-centre pad: the spread slider, hold-to-fly buttons and a reset. */
    99	export function NavPad({ spread, onSpread, nav }: { spread: number; onSpread: (s: number) => void; nav: MutableRefObject<NavInput> }) {
   100	  const hold = (dir: number) => ({
   101	    onPointerDown: (e: ReactPointerEvent<HTMLButtonElement>) => { e.currentTarget.setPointerCapture(e.pointerId); nav.current.fwd = dir; },
   102	    onPointerUp: () => { nav.current.fwd = 0; },
   103	    onPointerCancel: () => { nav.current.fwd = 0; },
   104	    onLostPointerCapture: () => { nav.current.fwd = 0; },
   105	  });
   106	  return (
   107	    <div className="navpad" role="group" aria-label="Move through the universe">
   108	      <label className="navpad-spread">
   109	        <span>Spread</span>
   110	        <input type="range" min={SPREAD_MIN} max={SPREAD_MAX} step={0.05} value={spread}
   111	               onChange={(e) => onSpread(Number(e.target.value))} aria-valuetext={`${spread.toFixed(1)} times`} />
   112	        <output className="num">{spread.toFixed(1)}×</output>
   113	      </label>
   114	      <div className="navpad-fly">
   115	        <button type="button" title="Fly back (S)" aria-label="Fly back" {...hold(-1)}><ArrowDown size={14} /></button>
   116	        <button type="button" title="Fly forward (W)" aria-label="Fly forward" {...hold(1)}><ArrowUp size={14} /></button>
   117	        <button type="button" title="Reset view" aria-label="Reset view" onClick={() => { nav.current.reset++; }}><LocateFixed size={14} /></button>
   118	      </div>
   119	      <span className="navpad-hint">W/S fly · A/D side · Q/E down/up · right-drag pan · scroll zooms to cursor</span>
   120	    </div>
   121	  );
   122	}
