    98	/** The values a dimension offers, with how many items carry each one at this checkpoint, given the other filters. */
    99	export function keyValues(dim: Dim, points: PointsPayload, src: SourcesPayload | undefined, position: number, f: Filter | null = null) {
   100	  const rest = without(f, dim);
   101	  const n = new Map<string, number>();
   102	  const add = (v: string | null | undefined) => n.set(key(v), (n.get(key(v)) ?? 0) + 1);
   103	  if (isCommentDim(dim)) {
   104	    const mask = commentMask(points, rest);
   105	    const col = points.cols[dim], dict = points.dict[dim] as (string | null)[], cps = points.cols.cp;
   106	    for (let i = 0; i < points.n; i++) if (mask[i] && col[i] >= 0 && cps[i] <= position) add(dict[col[i]]);
   107	  }
   108	  if (dim === "length") {
   109	    const mask = commentMask(points, rest), cps = points.cols.cp;
   110	    for (let i = 0; i < points.n; i++) if (mask[i] && cps[i] <= position) add(lengthOf(points.cols.len[i]));
   111	  }
   112	  const research = (src?.research ?? []).filter((r) => (position > 1 || !r.new) && passResearch(rest, r));
   113	  const study = (src?.study ?? []).filter((s) => passStudy(rest, s));
   114	  const options = (src?.options ?? []).filter((o) => passOption(rest, o));
   115	  const sales = (src?.sales ?? []).filter((r) => r.units && r.units > 0 && passSales(rest, r));   // as drawn: one bar per figure
   116	  if (dim === "car") {
   117	    for (const r of research) new Set(researchCars(r)).forEach(add);
   118	    for (const s of study) add(s.car);
   119	    for (const o of options) add(o.car);
   120	    for (const r of sales) add(r.car);
   121	  }
   122	  if (dim === "market") {
   123	    for (const r of research) if (r.market) add(r.market);
   124	    for (const s of study) add(s.market);
   125	    for (const r of sales) add(r.market);
   126	  }
   127	  if (dim === "tier") for (const r of research) add(r.tier);
   128	  if (dim === "topic") for (const r of research) add(r.topic);
   129	  if (dim === "fact") for (const r of research) add(r.kind);
   130	  if (dim === "category") for (const o of options) add(o.category);
   131	  if (dim === "availability") for (const o of options) add(o.availability);
   132	  if (dim === "rating") for (const s of study) add(ratingOf(s));
   133	  if (dim === "year") for (const r of sales) add(yearOf(r));
   134	
   135	  // a chosen value stays listed even when the other filters leave nothing for it, so it can be unchosen
   136	  const chosen = on(f, dim);
   137	  const order: string[] =
   138	    dim === "car" ? [...CARS] : dim === "market" ? ["EU", "US", "CN", "RoW"] : dim === "tier" ? ["T1", "T2", "T3"]
   139	      : dim === "rating" ? ["above", "around", "below"] : dim === "year" ? [...new Set((src?.sales ?? []).map(yearOf))].sort()
   140	      : dim === "length" ? [...LENGTHS] : dim === "availability" ? ["standard", "optional", "package", NONE]
   141	      : isCommentDim(dim) ? (points.dict[dim] as (string | null)[]).map(key)
   142	        : [...n.keys(), ...(chosen ?? [])].filter((v, i, a) => a.indexOf(v) === i)   // topic, fact type, category: largest first
   143	            .sort((a, b) => (n.get(b) ?? 0) - (n.get(a) ?? 0));
   144	  return order.filter((v) => n.get(v) || chosen?.has(v)).map((v) => ({ v, name: valueName(dim, v), n: n.get(v) ?? 0 }));
   145	}
   146	
   147	export function valueName(dim: Dim, v: string) {
   148	  if (v === NONE) return dim === "type" ? "Unlabelled" : "Unknown";
   149	  if (dim === "car") return CAR_NAME[v] ?? v;
   150	  if (dim === "market") return MARKET_NAME[v] ?? v;
   151	  if (dim === "tier") return TIER_NAME[v] ?? v;
   152	  if (dim === "rating") return RATING_NAME[v] ?? v;
   153	  if (dim === "year") return v === "2030" ? "2030 forecast" : v;
   154	  if (dim === "length") return LENGTH_NAME[v] ?? v;
   155	  if (dim === "topic") return TOPIC_NAME[v] ?? humanize(v);
   156	  if (dim === "fact") return FACT_NAME[v] ?? humanize(v);
   157	  if (dim === "availability") return AVAILABILITY_NAME[v] ?? humanize(v);
   158	  return v;
   159	}
