     1	// Pure car-frame math (no React, no WebGL) so it can be unit-tested.
     2	//
     3	// Normalised car frame: f along the length (-1 rear … +1 front), r across (-1 left … +1 right, seen from the
     4	// driver's seat), h up (0 ground … 1 roof). After normalisation every car sits in world space with
     5	// front = +X, up = +Y, centred on the origin, wheels on y = 0. The right-hand side is front × up = +Z.
     6	
     7	export type Vec3 = [number, number, number];
     8	export type Axis = "+x" | "-x" | "+y" | "-y" | "+z" | "-z";
     9	export type Orientation = { up: Axis; front: Axis };
    10	
    11	export type ZoneDef = { label: string; pos: Vec3; view: Vec3; dist: number };
    12	
    13	/** World-space frame of a normalised car. L = half-length, W = half-width, H = height (roof). */
    14	export type CarFrame = { L: number; W: number; H: number };
    15	
    16	export const DEFAULT_ORIENTATION: Orientation = { up: "+y", front: "+z" };
    17	
    18	export const WORLD_FRONT: Vec3 = [1, 0, 0];
    19	export const WORLD_UP: Vec3 = [0, 1, 0];
    20	export const cross = (a: Vec3, b: Vec3): Vec3 => [
    21	  a[1] * b[2] - a[2] * b[1],
    22	  a[2] * b[0] - a[0] * b[2],
    23	  a[0] * b[1] - a[1] * b[0],
    24	];
    25	/** right = front × up → +Z in world. */
    26	export const WORLD_RIGHT: Vec3 = cross(WORLD_FRONT, WORLD_UP);
    27	
    28	export function axisVec(a: Axis): Vec3 {
    29	  const s = a[0] === "-" ? -1 : 1;
    30	  const i = a[1] === "x" ? 0 : a[1] === "y" ? 1 : 2;
    31	  const v: Vec3 = [0, 0, 0];
    32	  v[i] = s;
    33	  return v;
    34	}
    35	
    36	/**
    37	 * Row-major 3×3 rotation that maps the model's local front → world +X, local up → world +Y and
    38	 * local right (front × up) → world right (+Z). Rows are front, up, right (an orthonormal basis, det = +1).
    39	 * Returns null when front and up are parallel (invalid orientation).
    40	 */
    41	export function orientationMatrix(o: Orientation): number[] | null {
    42	  const f = axisVec(o.front);
    43	  const u = axisVec(o.up);
    44	  const r = cross(f, u);
    45	  if (r[0] === 0 && r[1] === 0 && r[2] === 0) return null;
    46	  // world = M · local, with M rows expressed so that M·f = X, M·u = Y, M·r = Z (r maps to WORLD_RIGHT = +Z).
    47	  return [...f, ...u, ...r];
    48	}
    49	
    50	/** Frame from the normalised bounding-box size (world units, after rotation + scale). */
    51	export function frameFromSize(size: Vec3): CarFrame {
    52	  return { L: size[0] / 2, W: size[2] / 2, H: size[1] };
    53	}
    54	
    55	/** A normalised zone position [f, r, h] → world [x, y, z]. */
    56	export function zoneToWorld(pos: Vec3, frame: CarFrame): Vec3 {
    57	  const [f, r, h] = pos;
    58	  return [
    59	    f * frame.L * WORLD_FRONT[0] + r * frame.W * WORLD_RIGHT[0],
    60	    h * frame.H,
    61	    f * frame.L * WORLD_FRONT[2] + r * frame.W * WORLD_RIGHT[2],
    62	  ];
    63	}
    64	
    65	/** A view direction [f, r, h] in the frame → unit world vector (not scaled by the car's proportions). */
    66	export function frameDir(view: Vec3): Vec3 {
    67	  const [f, r, h] = view;
    68	  const v: Vec3 = [f * WORLD_FRONT[0] + r * WORLD_RIGHT[0], h, f * WORLD_FRONT[2] + r * WORLD_RIGHT[2]];
    69	  const n = Math.hypot(v[0], v[1], v[2]) || 1;
    70	  return [v[0] / n, v[1] / n, v[2] / n];
    71	}
    72	
    73	export type CameraPose = { eye: Vec3; target: Vec3 };
    74	
    75	/** Overview: front-left three-quarter, slightly elevated. */
    76	export const OVERVIEW = { target: [0, 0, 0.42] as Vec3, view: [0.85, -0.95, 0.42] as Vec3, dist: 2.75 };
    77	
    78	export function poseFor(zone: Pick<ZoneDef, "pos" | "view" | "dist"> | null, frame: CarFrame): CameraPose {
    79	  const z = zone ?? { pos: OVERVIEW.target, view: OVERVIEW.view, dist: OVERVIEW.dist };
    80	  const target = zoneToWorld(z.pos, frame);
    81	  const d = frameDir(z.view);
    82	  const k = z.dist * frame.L;
    83	  return { target, eye: [target[0] + d[0] * k, target[1] + d[1] * k, target[2] + d[2] * k] };
    84	}
