    24	  const added = parent ? sum(cur, "new") : sum(cur, "visible");
    25	  const cutoff = (id: CheckpointId) => byId[id]?.cutoff ?? FALLBACK[id];
    26	  const label = (id: CheckpointId) => byId[id]?.label ?? (id === "cp1" ? "JAN 26" : "JUL 26");
    27	  const at = CHECKPOINT_ORDER.indexOf(cp);
    28	  const known = frac(cutoff(cp));
    29	
    30	  return (
    31	    <div className="sweepctl">
    32	      <div className="sweepctl-top">
    33	        <span className="sweepctl-title">Checkpoint</span>
    34	        <span className="label">Evidence known up to {longDate(cutoff(cp))}</span>
    35	      </div>
    36	
    37	      <div className="sweepctl-line" role="radiogroup" aria-label="Checkpoint">
    38	        <span className="sweepctl-rail" aria-hidden />
    39	        <span className="sweepctl-fill" aria-hidden style={{ transform: `scaleX(${known})` }} />
    40	        {MONTHS.map((x, i) => <span key={i} className="sweepctl-tick" aria-hidden style={{ left: `${x * 100}%` }} />)}
    41	        <span className="sweepctl-start label" aria-hidden>JUL 25</span>
    42	        {CHECKPOINT_ORDER.map((id, i) => (
    43	          <button key={id} role="radio" aria-checked={cp === id} className="sweepctl-node"
    44	                  data-state={id === cp ? "active" : i < at ? "built" : "idle"} data-end={frac(cutoff(id)) > 0.9 ? "" : undefined}
    45	                  style={{ left: `${frac(cutoff(id)) * 100}%` }} onClick={() => setCp(id)}>
    46	            <span className="sweepctl-name">{label(id)}</span>
    47	            <span className="sweepctl-dot" />
    48	          </button>
    49	        ))}
    50	      </div>
    51	
    52	      <div className="sweepctl-counts" aria-live="polite">
    53	        <span><i className="mark held" aria-hidden /><span className="num">{fmt(held)}</span><span className="label">held</span></span>
    54	        <span><i className="mark new" aria-hidden /><span className="num">{fmt(added)}</span><span className="label">new</span></span>
    55	        <span className="label sweepctl-keys" aria-hidden>← →</span>
    56	      </div>
    57	    </div>
    58	  );
    59	}

