1	     1	// CarStage — the real-time 3D studio for today's car, with requirement hotspots pinned to car zones.
2	     2	//
3	     3	// Everything is in a normalised world frame: front = +X, up = +Y, right = front × up = +Z, wheels on y = 0,
4	     4	// length = 4.8 units (see frame.ts). Zones (pos/view/dist) live in the car frame and map through `zoneToWorld`.
5	     5	// Per-frame work (camera turntable, x-ray fade, glow, pin dimming) runs in useFrame on refs — no React renders.
6	     6	import {
7	     7	  Component,
8	     8	  Suspense,
9	     9	  useCallback,
10	    10	  useEffect,
11	    11	  useLayoutEffect,
12	    12	  useMemo,
13	    13	  useRef,
14	    14	  useState,
15	    15	  type ErrorInfo,
16	    16	  type ReactNode,
17	    17	} from "react";
18	    18	import { Canvas, useFrame, useThree } from "@react-three/fiber";
19	    19	import {
20	    20	  CameraControls,
21	    21	  ContactShadows,
22	    22	  Environment,
23	    23	  Lightformer,
24	    24	  MeshReflectorMaterial,
25	    25	  useGLTF,
26	    26	  useProgress,
27	    27	} from "@react-three/drei";
28	    28	import type CameraControlsImpl from "camera-controls";
29	    29	import * as THREE from "three";
30	    30	import { THEME, CAR_LENGTH } from "./theme";
31	    31	import {
32	    32	  DEFAULT_ORIENTATION,
33	    33	  INTERIOR_ZONES,
34	    34	  frameDir,
35	    35	  frameFromSize,
36	    36	  orientationMatrix,
37	    37	  poseFor,
38	    38	  zoneToWorld,
39	    39	  type CarFrame,
40	    40	  type Orientation,
41	    41	  type Vec3,
42	    42	  type ZoneDef,
43	    43	} from "./frame";
44	    44	import { PLACEHOLDER_FRAME, PlaceholderCar } from "./PlaceholderCar";
45	    45	import "./carstage.css";
46	    46	
47	    47	export type { ZoneDef, Orientation, CarFrame } from "./frame";
48	    48	export { zoneToWorld } from "./frame";
49	    49	
50	    50	export type Priority = "Must" | "Should" | "Could";
51	    51	export type Hotspot = { zone: string; count: number; top: Priority; aiOnly?: boolean };
52	    52	
53	    53	export interface CarStageProps {
54	    54	  /** "/models/g60.glb", "/models/g60/scene.gltf", or null → placeholder car. */
55	    55	  modelUrl: string | null;
56	    56	  /** How the model's own axes map; default { up: "+y", front: "+z" }. */
57	    57	  orientation?: Orientation;
58	    58	  zones: Record<string, ZoneDef>;
59	    59	  hotspots: Hotspot[];
