69	    69	/** Warm the glTF cache before the stage mounts. */
70	    70	export function preloadCar(url: string) {
71	    71	  useGLTF.preload(url);
72	    72	}
73	    73	
74	    74	const IDLE_MS = 20_000;
75	    75	const TURN_SPEED = 0.15; // rad/s
76	    76	const XRAY_OPACITY = 0.18;
77	    77	
78	    78	// ------------------------------------------------------------------------------------------------ helpers
79	    79	function usePrefersReducedMotion() {
80	    80	  const [reduced, setReduced] = useState(
81	    81	    () => typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
82	    82	  );
83	    83	  useEffect(() => {
84	    84	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
85	    85	    if (!mq) return;
86	    86	    const on = () => setReduced(mq.matches);
87	    87	    mq.addEventListener("change", on);
88	    88	    return () => mq.removeEventListener("change", on);
89	    89	  }, []);
90	    90	  return reduced;
91	    91	}
92	    92	
93	    93	let glowTex: THREE.Texture | null = null;
94	    94	function glowTexture() {
95	    95	  if (glowTex) return glowTex;
96	    96	  const c = document.createElement("canvas");
97	    97	  c.width = c.height = 128;
98	    98	  const g = c.getContext("2d")!;
99	    99	  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
100	   100	  grd.addColorStop(0, "rgba(255,255,255,1)");
101	   101	  grd.addColorStop(0.25, "rgba(255,255,255,0.45)");
102	   102	  grd.addColorStop(0.6, "rgba(255,255,255,0.09)");
103	   103	  grd.addColorStop(1, "rgba(255,255,255,0)");
104	   104	  g.fillStyle = grd;
105	   105	  g.fillRect(0, 0, 128, 128);
106	   106	  glowTex = new THREE.CanvasTexture(c);
107	   107	  glowTex.colorSpace = THREE.SRGBColorSpace;
108	   108	  return glowTex;
109	   109	}
110	   110	
111	   111	type MatState = { m: THREE.Material; opacity: number; transparent: boolean; depthWrite: boolean };
112	   112	
113	   113	function collectMaterials(root: THREE.Object3D): MatState[] {
114	   114	  const out: MatState[] = [];
115	   115	  const seen = new Set<THREE.Material>();
116	   116	  root.traverse((o) => {
117	   117	    const mesh = o as THREE.Mesh;
118	   118	    if (!mesh.isMesh) return;
119	   119	    const ms = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
120	   120	    for (const m of ms) {
121	   121	      if (!m || seen.has(m)) continue;
122	   122	      seen.add(m);
123	   123	      out.push({ m, opacity: m.opacity, transparent: m.transparent, depthWrite: m.depthWrite });
124	   124	    }
125	   125	  });
126	   126	  return out;
127	   127	}
128	   128	
129	   129	// ------------------------------------------------------------------------------------------------ model
130	   130	type CarReady = (root: THREE.Object3D, frame: CarFrame) => void;
131	   131	
132	   132	function GltfCar({ url, orientation, onReady }: { url: string; orientation: Orientation; onReady: CarReady }) {
133	   133	  const { scene } = useGLTF(url);
134	   134	  const groupRef = useRef<THREE.Group>(null);
135	   135	
136	   136	  // Own copy (shared geometry/textures, cloned materials) so x-ray / env boosts never leak into the glTF cache.
137	   137	  const prepared = useMemo(() => {
138	   138	    const car = scene.clone(true);
139	   139	    car.traverse((o) => {
140	   140	      const mesh = o as THREE.Mesh;
141	   141	      if (!mesh.isMesh) return;
142	   142	      mesh.castShadow = false;
143	   143	      mesh.receiveShadow = false;
144	   144	      const clone = (m: THREE.Material) => {
145	   145	        const c = m.clone();
146	   146	        const std = c as THREE.MeshStandardMaterial;
147	   147	        if ("envMapIntensity" in std && typeof std.envMapIntensity === "number") {
148	   148	          std.envMapIntensity = Math.max(1.2, std.envMapIntensity * 1.5);
149	   149	        }
150	   150	        return c;
151	   151	      };
152	   152	      mesh.material = Array.isArray(mesh.material) ? mesh.material.map(clone) : clone(mesh.material);
153	   153	    });
154	   154	
155	   155	    // rotate so the model's front → +X, up → +Y
156	   156	    const rot = new THREE.Group();
157	   157	    const m = orientationMatrix(orientation) ?? orientationMatrix(DEFAULT_ORIENTATION)!;
158	   158	    rot.quaternion.setFromRotationMatrix(
159	   159	      new THREE.Matrix4().set(m[0], m[1], m[2], 0, m[3], m[4], m[5], 0, m[6], m[7], m[8], 0, 0, 0, 0, 1),
160	   160	    );
161	   161	    rot.add(car);
162	   162	    rot.updateMatrixWorld(true);
163	   163	    const box = new THREE.Box3().setFromObject(rot);
164	   164	    const size = box.getSize(new THREE.Vector3());
165	   165	    const s = size.x > 0 ? CAR_LENGTH / size.x : 1;
166	   166	    const centre = box.getCenter(new THREE.Vector3());
167	   167	
168	   168	    const wrap = new THREE.Group();
169	   169	    wrap.name = "car-normalised";
170	   170	    wrap.scale.setScalar(s);
171	   171	    wrap.position.set(-centre.x * s, -box.min.y * s, -centre.z * s);
172	   172	    wrap.add(rot);
173	   173	    const frame = frameFromSize([size.x * s, size.y * s, size.z * s]);
174	   174	    return { wrap, frame };
175	   175	  }, [scene, orientation]);
176	   176	
177	   177	  useLayoutEffect(() => {
178	   178	    if (groupRef.current) onReady(groupRef.current, prepared.frame);
179	   179	  }, [prepared, onReady]);
180	   180	
181	   181	  return (
182	   182	    <group ref={groupRef}>
183	   183	      <primitive object={prepared.wrap} />
184	   184	    </group>
185	   185	  );
186	   186	}
187	   187	
188	   188	function Placeholder({ onReady }: { onReady: CarReady }) {
189	   189	  const ref = useRef<THREE.Group>(null);
190	   190	  useLayoutEffect(() => {
191	   191	    if (ref.current) onReady(ref.current, PLACEHOLDER_FRAME);
192	   192	  }, [onReady]);
193	   193	  return (
194	   194	    <group ref={ref}>
195	   195	      <PlaceholderCar />
196	   196	    </group>
197	   197	  );
198	   198	}
