224	   224	function Studio({ shadowKey }: { shadowKey: string }) {
225	   225	  return (
226	   226	    <>
227	   227	      <color attach="background" args={[THEME.bg]} />
228	   228	      <fog attach="fog" args={[THEME.bg, 12, 30]} />
229	   229	      <ambientLight intensity={0.08} />
230	   230	
231	   231	      <Environment resolution={256} frames={1}>
232	   232	        <color attach="background" args={["#020203"]} />
233	   233	        {/* long softbox strips overhead */}
234	   234	        {[-2.4, 0, 2.4].map((z) => (
235	   235	          <Lightformer key={z} form="rect" intensity={2.4} color="#f2f5fb" position={[0, 6, z]} rotation-x={Math.PI / 2} scale={[14, 0.7, 1]} />
236	   236	        ))}
237	   237	        {/* side strips → long highlight along the shoulder line */}
238	   238	        <Lightformer form="rect" intensity={2.8} color="#e6ecf7" position={[0, 1.6, 7]} scale={[16, 0.35, 1]} target={[0, 0.8, 0]} />
239	   239	        <Lightformer form="rect" intensity={2.8} color="#e6ecf7" position={[0, 1.6, -7]} scale={[16, 0.35, 1]} target={[0, 0.8, 0]} />
240	   240	        {/* key + cool rim */}
241	   241	        <Lightformer form="rect" intensity={3} color="#ffffff" position={[7, 3.5, -4]} scale={[3, 5, 1]} target={[0, 0.5, 0]} />
242	   242	        <Lightformer form="rect" intensity={2.2} color="#8fb6ff" position={[-8, 2, 3]} scale={[2.5, 6, 1]} target={[0, 0.5, 0]} />
243	   243	        <Lightformer form="ring" intensity={1.2} color={THEME.blueBright} position={[-4, 5, -6]} scale={3} target={[0, 0, 0]} />
244	   244	        {/* faint floor bounce */}
245	   245	        <Lightformer form="rect" intensity={0.25} color="#9aa3b5" position={[0, -2, 0]} rotation-x={-Math.PI / 2} scale={[14, 14, 1]} />
246	   246	      </Environment>
