250	   250	        <planeGeometry args={[70, 70]} />
251	   251	        <MeshReflectorMaterial
252	   252	          resolution={512}
253	   253	          blur={[400, 120]}
254	   254	          mixBlur={1}
255	   255	          mixStrength={3}
256	   256	          mixContrast={1.1}
257	   257	          mirror={0.4}
258	   258	          roughness={0.85}
