273	   273	}
274	   274	
275	   275	// ------------------------------------------------------------------------------------------------ zone glow + x-ray
276	   276	function ZoneFocus({
277	   277	  carRef,
278	   278	  carVersion,
279	   279	  target,
280	   280	  xray,
281	   281	  reduced,
282	   282	}: {
283	   283	  carRef: React.RefObject<THREE.Object3D | null>;
284	   284	  carVersion: number;
285	   285	  target: Vec3 | null;
286	   286	  xray: boolean;
287	   287	  reduced: boolean;
288	   288	}) {
289	   289	  const sprite = useRef<THREE.Sprite>(null);
290	   290	  const pool = useRef<THREE.Mesh>(null);
291	   291	  const light = useRef<THREE.PointLight>(null);
292	   292	  const mats = useRef<MatState[]>([]);
293	   293	  const k = useRef(0); // x-ray amount 0..1
294	   294	  const g = useRef(0); // glow amount 0..1
295	   295	  const tex = useMemo(() => glowTexture(), []);
296	   296	  const lastTarget = useRef<Vec3>([0, 0, 0]);
297	   297	
298	   298	  useEffect(() => {
299	   299	    mats.current = carRef.current ? collectMaterials(carRef.current) : [];
300	   300	    k.current = 0;
301	   301	    return () => {
302	   302	      for (const s of mats.current) {
303	   303	        s.m.opacity = s.opacity;
304	   304	        s.m.transparent = s.transparent;
305	   305	        s.m.depthWrite = s.depthWrite;
306	   306	        s.m.needsUpdate = true;
307	   307	      }
308	   308	    };
309	   309	  }, [carRef, carVersion]);
310	   310	
311	   311	  if (target) lastTarget.current = target;
312	   312	
313	   313	  useFrame((_, dt) => {
314	   314	    const rate = reduced ? 1 : 1 - Math.exp(-dt * 4.5);
315	   315	    const kGoal = xray ? 1 : 0;
316	   316	    const gGoal = target ? 1 : 0;
317	   317	    const kPrev = k.current;
318	   318	    k.current += (kGoal - k.current) * rate;
319	   319	    if (Math.abs(k.current - kGoal) < 0.002) k.current = kGoal;
320	   320	    g.current += (gGoal - g.current) * rate;
321	   321	    if (Math.abs(g.current - gGoal) < 0.002) g.current = gGoal;
322	   322	
323	   323	    if (kPrev !== k.current || (k.current > 0 && kPrev === 0)) {
324	   324	      const kk = k.current;
325	   325	      for (const s of mats.current) {
326	   326	        const wantTransparent = kk > 0.001 ? true : s.transparent;
327	   327	        const wantDepth = kk > 0.35 ? false : s.depthWrite;
328	   328	        if (s.m.transparent !== wantTransparent) {
329	   329	          s.m.transparent = wantTransparent;
330	   330	          s.m.needsUpdate = true;
331	   331	        }
332	   332	        s.m.depthWrite = wantDepth;
333	   333	        s.m.opacity = s.opacity + (Math.min(s.opacity, XRAY_OPACITY) - s.opacity) * kk;
334	   334	      }
335	   335	    }
336	   336	
337	   337	    const [x, y, z] = lastTarget.current;
338	   338	    const gg = g.current;
339	   339	    if (sprite.current) {
340	   340	      sprite.current.position.set(x, y, z);
341	   341	      const pulse = reduced ? 1 : 1 + Math.sin(performance.now() / 700) * 0.06;
342	   342	      sprite.current.scale.setScalar(1.5 * pulse * (0.6 + 0.4 * gg));
343	   343	      (sprite.current.material as THREE.SpriteMaterial).opacity = 0.55 * gg;
344	   344	      sprite.current.visible = gg > 0.01;
345	   345	    }
346	   346	    if (pool.current) {
347	   347	      pool.current.position.set(x, 0.006, z);
348	   348	      (pool.current.material as THREE.MeshBasicMaterial).opacity = 0.5 * gg;
349	   349	      pool.current.visible = gg > 0.01;
350	   350	    }
351	   351	    if (light.current) {
352	   352	      light.current.position.set(x, y + 0.25, z);
353	   353	      light.current.intensity = 6 * gg;
354	   354	    }
355	   355	  });
356	   356	
357	   357	  return (
358	   358	    <>
359	   359	      <sprite ref={sprite} renderOrder={10} visible={false}>
360	   360	        <spriteMaterial map={tex} color={THEME.blueBright} transparent depthTest={false} depthWrite={false} blending={THREE.AdditiveBlending} toneMapped={false} />
361	   361	      </sprite>
362	   362	      <mesh ref={pool} rotation-x={-Math.PI / 2} renderOrder={2} visible={false}>
363	   363	        <planeGeometry args={[3.2, 3.2]} />
364	   364	        <meshBasicMaterial map={tex} color={THEME.blue} transparent depthWrite={false} blending={THREE.AdditiveBlending} toneMapped={false} />
365	   365	      </mesh>
366	   366	      <pointLight ref={light} color={THEME.blueBright} intensity={0} distance={3.2} decay={2} />
367	   367	    </>
368	   368	  );
369	   369	}
370	   370	
371	   371	// ------------------------------------------------------------------------------------------------ hotspots
372	   372	// Pins are plain DOM in an overlay above the canvas (normal React tree, crisp text, real <button>s).
373	   373	// A projector inside the canvas writes their screen transform/opacity every frame through refs.
374	   374	type PinItem = { h: Hotspot; z: ZoneDef; pos: THREE.Vector3; facing: THREE.Vector3 };
375	   375	type PinEls = Map<string, HTMLDivElement>;
376	   376	
377	   377	function PinProjector({
378	   378	  items,
379	   379	  els,
380	   380	  xray,
381	   381	  selectedZone,
382	   382	}: {
383	   383	  items: PinItem[];
384	   384	  els: React.RefObject<PinEls>;
385	   385	  xray: boolean;
386	   386	  selectedZone: string | null;
387	   387	}) {
388	   388	  const tmp = useMemo(() => new THREE.Vector3(), []);
389	   389	  const last = useRef(new Map<string, { x: number; y: number; o: string; z: number }>());
390	   390	  useFrame(({ camera, size }) => {
391	   391	    const map = els.current;
392	   392	    for (const it of items) {
393	   393	      const el = map.get(it.h.zone);
394	   394	      if (!el) continue;
395	   395	      tmp.copy(it.pos).project(camera);
396	   396	      const visible = tmp.z < 1 && Math.abs(tmp.x) < 1.2 && Math.abs(tmp.y) < 1.2;
397	   397	      const x = Math.round((tmp.x * 0.5 + 0.5) * size.width * 10) / 10;
398	   398	      const y = Math.round((-tmp.y * 0.5 + 0.5) * size.height * 10) / 10;
399	   399	      tmp.copy(camera.position).sub(it.pos).normalize();
400	   400	      const sel = it.h.zone === selectedZone;
401	   401	      const behind = !xray && !sel && tmp.dot(it.facing) < -0.05;
402	   402	      const o = !visible ? "0" : behind ? "0.3" : "1";
403	   403	      const zi = sel ? 30 : behind ? 5 : 10 + Math.round((1 - Math.min(1, camera.position.distanceTo(it.pos) / 30)) * 10);
404	   404	      const prev = last.current.get(it.h.zone);
405	   405	      if (!prev || prev.x !== x || prev.y !== y) el.style.transform = `translate3d(${x}px, ${y}px, 0)`;
406	   406	      if (!prev || prev.o !== o) {
407	   407	        el.style.opacity = o;
408	   408	        el.style.visibility = o === "0" ? "hidden" : "visible";
409	   409	      }
410	   410	      if (!prev || prev.z !== zi) el.style.zIndex = String(zi);
411	   411	      if (prev) {
412	   412	        prev.x = x;
413	   413	        prev.y = y;
414	   414	        prev.o = o;
415	   415	        prev.z = zi;
416	   416	      } else last.current.set(it.h.zone, { x, y, o, z: zi });
417	   417	    }
418	   418	  });
419	   419	  return null;
420	   420	}
421	   421	
422	   422	function PinLayer({
423	   423	  items,
424	   424	  els,
425	   425	  selectedZone,
426	   426	  hoverZone,
427	   427	  onSelectZone,
428	   428	}: {
429	   429	  items: PinItem[];
430	   430	  els: React.RefObject<PinEls>;
431	   431	  selectedZone: string | null;
432	   432	  hoverZone: string | null;
433	   433	  onSelectZone: (z: string | null) => void;
434	   434	}) {
435	   435	  return (
436	   436	    <div className="cs-pins">
437	   437	      {items.map(({ h, z }) => {
438	   438	        const sel = selectedZone === h.zone;
439	   439	        const label = `${z.label} — ${h.count} recommendation${h.count === 1 ? "" : "s"}`;
440	   440	        return (
441	   441	          <div
442	   442	            key={h.zone}
443	   443	            ref={(el) => {
444	   444	              if (el) els.current.set(h.zone, el);
445	   445	              else els.current.delete(h.zone);
446	   446	            }}
447	   447	            className="cs-pin-anchor"
448	   448	          >
449	   449	            <div className="cs-pin-wrap" data-selected={sel ? "1" : "0"} data-hover={hoverZone === h.zone ? "1" : "0"}>
450	   450	              <button
451	   451	                type="button"
452	   452	                className="cs-pin"
453	   453	                data-top={h.top}
454	   454	                aria-label={label + (h.aiOnly ? " (AI suggestion, not yet confirmed)" : "")}
455	   455	                aria-pressed={sel}
456	   456	                onClick={(e) => {
457	   457	                  e.stopPropagation();
458	   458	                  onSelectZone(sel ? null : h.zone);
459	   459	                }}
460	   460	              >
461	   461	                {h.aiOnly && <span className="cs-pin-ai" aria-hidden />}
462	   462	                {h.count}
463	   463	              </button>
464	   464	              <span className="cs-label" aria-hidden>
465	   465	                {z.label}
466	   466	                <b>{h.count}</b>
467	   467	              </span>
468	   468	            </div>
469	   469	          </div>
470	   470	        );
471	   471	      })}
472	   472	    </div>
473	   473	  );
474	   474	}
475	   475	
476	   476	// ------------------------------------------------------------------------------------------------ camera
477	   477	function CameraRig({
478	   478	  frame,
479	   479	  zone,
480	   480	  compact,
481	   481	  reduced,
482	   482	}: {
483	   483	  frame: CarFrame;
484	   484	  zone: ZoneDef | null;
485	   485	  compact: boolean;
486	   486	  reduced: boolean;
487	   487	}) {
488	   488	  const ref = useRef<CameraControlsImpl>(null);
489	   489	  const lastInput = useRef(performance.now());
490	   490	  const first = useRef(true);
491	   491	
492	   492	  // constraints + input mapping (no pan)
493	   493	  useEffect(() => {
494	   494	    const c = ref.current;
495	   495	    if (!c) return;
496	   496	    const A = (c.constructor as typeof CameraControlsImpl).ACTION;
497	   497	    c.minPolarAngle = 0.12;
498	   498	    c.maxPolarAngle = Math.PI / 2 - 0.05;
499	   499	    c.minDistance = frame.L * 0.9;
500	   500	    c.maxDistance = frame.L * 5.5;
501	   501	    c.dollyToCursor = false;
502	   502	    c.mouseButtons.left = A.ROTATE;
503	   503	    c.mouseButtons.right = A.NONE;
504	   504	    c.mouseButtons.middle = A.DOLLY;
505	   505	    c.mouseButtons.wheel = A.DOLLY;
506	   506	    c.touches.one = A.TOUCH_ROTATE;
507	   507	    c.touches.two = A.TOUCH_DOLLY;
508	   508	    c.touches.three = A.NONE;
509	   509	    c.enabled = !compact;
510	   510	    const onStart = () => {
511	   511	      lastInput.current = performance.now();
512	   512	    };
513	   513	    c.addEventListener("controlstart", onStart);
514	   514	    c.addEventListener("control", onStart);
515	   515	    return () => {
516	   516	      c.removeEventListener("controlstart", onStart);
517	   517	      c.removeEventListener("control", onStart);
518	   518	    };
519	   519	  }, [frame, compact]);
520	   520	
521	   521	  // fly to zone / overview; portrait viewports pull the camera back so the whole car stays in frame
522	   522	  const aspect = useThree((st) => st.size.width / Math.max(1, st.size.height));
523	   523	  useEffect(() => {
524	   524	    const c = ref.current;
525	   525	    if (!c) return;
526	   526	    const raw = poseFor(zone, frame);
527	   527	    const pull = aspect < 1.25 ? Math.min(2.1, Math.pow(1.25 / aspect, 0.85)) : 1;
528	   528	    const p = {
529	   529	      target: raw.target,
530	   530	      eye: raw.eye.map((e, i) => raw.target[i] + (e - raw.target[i]) * pull) as typeof raw.eye,
531	   531	    };
532	   532	    const animate = !reduced && !first.current;
533	   533	    first.current = false;
534	   534	    c.smoothTime = 0.32; // ≈1.2 s settle, ease-out
535	   535	    lastInput.current = performance.now();
536	   536	    void c.setLookAt(p.eye[0], p.eye[1], p.eye[2], p.target[0], p.target[1], p.target[2], animate);
537	   537	  }, [zone, frame, reduced, aspect]);
538	   538	
539	   539	  useFrame((_, dt) => {
540	   540	    const c = ref.current;
541	   541	    if (!c || reduced || zone) return;
542	   542	    const idle = compact || performance.now() - lastInput.current > IDLE_MS;
543	   543	    if (idle) {
544	   544	      void c.rotate(TURN_SPEED * Math.min(dt, 0.1), 0, false);
545	   545	    }
546	   546	  });
547	   547	
548	   548	  return <CameraControls ref={ref} makeDefault />;
549	   549	}
550	   550	
551	   551	// ------------------------------------------------------------------------------------------------ scene
552	   552	function Scene({
553	   553	  modelUrl,
554	   554	  orientation,
555	   555	  frame,
556	   556	  onFrame,
557	   557	  zones,
558	   558	  pinItems,
559	   559	  pinEls,
560	   560	  selectedZone,
561	   561	  compact,
562	   562	  reduced,
563	   563	  onModelError,
564	   564	  modelFailed,
565	   565	}: {
566	   566	  modelUrl: string | null;
567	   567	  orientation: Orientation;
568	   568	  frame: CarFrame;
569	   569	  onFrame: (f: CarFrame) => void;
570	   570	  zones: Record<string, ZoneDef>;
571	   571	  pinItems: PinItem[];
572	   572	  pinEls: React.RefObject<PinEls>;
573	   573	  selectedZone: string | null;
574	   574	  compact: boolean;
575	   575	  reduced: boolean;
576	   576	  onModelError: (e: Error) => void;
577	   577	  modelFailed: boolean;
578	   578	}) {
579	   579	  const carRef = useRef<THREE.Object3D | null>(null);
580	   580	  const [carVersion, setCarVersion] = useState(0);
581	   581	
582	   582	  const onReady = useCallback<CarReady>(
583	   583	    (root, f) => {
584	   584	      carRef.current = root;
585	   585	      onFrame(f);
586	   586	      setCarVersion((v) => v + 1);
587	   587	    },
588	   588	    [onFrame],
589	   589	  );
590	   590	
591	   591	  const zone = selectedZone ? zones[selectedZone] ?? null : null;
592	   592	  const target = zone ? zoneToWorld(zone.pos, frame) : null;
593	   593	  const xray = !!selectedZone && INTERIOR_ZONES.has(selectedZone);
594	   594	
595	   595	  const placeholder = <Placeholder onReady={onReady} />;
596	   596	
597	   597	  return (
598	   598	    <>
599	   599	      <Studio shadowKey={`${modelUrl ?? "placeholder"}:${modelFailed}:${carVersion}`} />
600	   600	      {modelUrl && !modelFailed ? (
601	   601	        <ModelBoundary key={modelUrl} fallback={placeholder} onError={onModelError}>
602	   602	          <Suspense fallback={null}>
603	   603	            <GltfCar url={modelUrl} orientation={orientation} onReady={onReady} />
604	   604	          </Suspense>
605	   605	        </ModelBoundary>
606	   606	      ) : (
607	   607	        placeholder
608	   608	      )}
609	   609	      <ZoneFocus carRef={carRef} carVersion={carVersion} target={target} xray={xray} reduced={reduced} />
610	   610	      <PinProjector items={pinItems} els={pinEls} xray={xray} selectedZone={selectedZone} />
611	   611	      <CameraRig frame={frame} zone={zone} compact={compact} reduced={reduced} />
612	   612	    </>
613	   613	  );
614	   614	}
615	   615	
616	   616	function LoadingLine() {
617	   617	  const { active, progress } = useProgress();
618	   618	  if (!active) return null;
619	   619	  const pct = Math.round(progress);
620	   620	  return (
621	   621	    <div className="cs-progress" role="status" aria-live="polite">
622	   622	      <div className="cs-progress-track">
623	   623	        <div className="cs-progress-bar" style={{ width: `${pct}%` }} />
624	   624	      </div>
625	   625	      <div className="cs-progress-pct">{pct}%</div>
626	   626	    </div>
627	   627	  );
628	   628	}
629	   629	
630	   630	// ------------------------------------------------------------------------------------------------ public component
631	   631	export function CarStage({
632	   632	  modelUrl,
633	   633	  orientation = DEFAULT_ORIENTATION,
634	   634	  zones,
635	   635	  hotspots,
636	   636	  selectedZone,
637	   637	  onSelectZone,
638	   638	  hoverZone = null,
639	   639	  mode = "showroom",
640	   640	  className,
641	   641	}: CarStageProps) {
642	   642	  const reduced = usePrefersReducedMotion();
643	   643	  const compact = mode === "compact";
644	   644	  const [failedUrl, setFailedUrl] = useState<string | null>(null);
645	   645	  const modelFailed = !!modelUrl && failedUrl === modelUrl;
646	   646	  const down = useRef<{ x: number; y: number } | null>(null);
647	   647	  // stable orientation identity so the model isn't re-normalised on every parent render
648	   648	  const orient = useMemo<Orientation>(() => ({ up: orientation.up, front: orientation.front }), [orientation.up, orientation.front]);
649	   649	
650	   650	  const onModelError = useCallback(
651	   651	    (e: Error) => {
652	   652	      console.warn("[CarStage] model failed to load, showing placeholder:", modelUrl, e);
653	   653	      setFailedUrl(modelUrl);
654	   654	    },
655	   655	    [modelUrl],
656	   656	  );
657	   657	
658	   658	  const showNote = !modelUrl || modelFailed;
659	   659	
660	   660	  const [frame, setFrame] = useState<CarFrame>(PLACEHOLDER_FRAME);
661	   661	  const onFrame = useCallback((f: CarFrame) => {
662	   662	    setFrame((prev) => (prev.L === f.L && prev.W === f.W && prev.H === f.H ? prev : f));
663	   663	  }, []);
664	   664	  const pinEls = useRef<PinEls>(new Map());
665	   665	  const pinItems = useMemo<PinItem[]>(
666	   666	    () =>
667	   667	      hotspots
668	   668	        .filter((h) => zones[h.zone])
669	   669	        .map((h) => {
670	   670	          const z = zones[h.zone];
671	   671	          return { h, z, pos: new THREE.Vector3(...zoneToWorld(z.pos, frame)), facing: new THREE.Vector3(...frameDir(z.view)) };
672	   672	        }),
673	   673	    [hotspots, zones, frame],
674	   674	  );
675	   675	
676	   676	  return (
677	   677	    <div
678	   678	      className={`cs-root${compact ? " cs-compact" : ""}${className ? ` ${className}` : ""}`}
679	   679	      tabIndex={-1}
680	   680	      onKeyDown={(e) => {
681	   681	        if (e.key === "Escape" && selectedZone) onSelectZone(null);
682	   682	      }}
683	   683	      onPointerDown={(e) => {
684	   684	        down.current = { x: e.clientX, y: e.clientY };
685	   685	      }}
686	   686	    >
687	   687	      <Canvas
688	   688	        dpr={[1, 2]}
689	   689	        frameloop="always"
690	   690	        shadows={false}
691	   691	        gl={{ antialias: true, powerPreference: "high-performance" }}
692	   692	        camera={{ fov: 40, near: 0.1, far: 80, position: poseFor(null, PLACEHOLDER_FRAME).eye }}
693	   693	        onCreated={({ gl }) => {
694	   694	          gl.toneMapping = THREE.ACESFilmicToneMapping;
695	   695	          gl.toneMappingExposure = 1.15;
696	   696	        }}
697	   697	        onPointerMissed={(e) => {
698	   698	          const d = down.current;
699	   699	          if (compact || !d || Math.hypot(e.clientX - d.x, e.clientY - d.y) > 4) return;
700	   700	          if (selectedZone) onSelectZone(null);
701	   701	        }}
702	   702	      >
703	   703	        <Scene
704	   704	          modelUrl={modelUrl}
705	   705	          orientation={orient}
706	   706	          frame={frame}
707	   707	          onFrame={onFrame}
708	   708	          zones={zones}
709	   709	          pinItems={pinItems}
710	   710	          pinEls={pinEls}
711	   711	          selectedZone={selectedZone}
712	   712	          compact={compact}
713	   713	          reduced={reduced}
714	   714	          onModelError={onModelError}
715	   715	          modelFailed={modelFailed}
716	   716	        />
717	   717	      </Canvas>
718	   718	      <PinLayer items={pinItems} els={pinEls} selectedZone={selectedZone} hoverZone={hoverZone} onSelectZone={onSelectZone} />
719	   719	      <LoadingLine />
720	   720	      {showNote && !compact && <div className="cs-note">3D model not installed — showing a placeholder</div>}
721	   721	    </div>
722	   722	  );
723	   723	}
724	   724	
725	   725	export default CarStage;
