  1	// CarStage — the real-time 3D studio for today's car, with requirement hotspots pinned to car zones.
  2	//
  3	// Everything is in a normalised world frame: front = +X, up = +Y, right = front × up = +Z, wheels on y = 0,
  4	// length = 4.8 units (see frame.ts). Zones (pos/view/dist) live in the car frame and map through `zoneToWorld`.
  5	// Per-frame work (camera turntable, x-ray fade, glow, pin dimming) runs in useFrame on refs — no React renders.
  6	import {
  7	  Component,
  8	  Suspense,
  9	  useCallback,
 10	  useEffect,
 11	  useLayoutEffect,
 12	  useMemo,
 13	  useRef,
 14	  useState,
 15	  type ErrorInfo,
 16	  type ReactNode,
 17	} from "react";
 18	import { Canvas, useFrame, useThree } from "@react-three/fiber";
 19	import {
 20	  CameraControls,
 21	  ContactShadows,
 22	  Environment,
 23	  Lightformer,
 24	  MeshReflectorMaterial,
 25	  useGLTF,
 26	  useProgress,
 27	} from "@react-three/drei";
 28	import type CameraControlsImpl from "camera-controls";
 29	import * as THREE from "three";
 30	import { THEME, CAR_LENGTH } from "./theme";
 31	import {
 32	  DEFAULT_ORIENTATION,
 33	  INTERIOR_ZONES,
 34	  frameDir,
 35	  frameFromSize,
 36	  orientationMatrix,
 37	  poseFor,
 38	  zoneToWorld,
 39	  type CarFrame,
 40	  type Orientation,
 41	  type Vec3,
 42	  type ZoneDef,
 43	} from "./frame";
 44	import { PLACEHOLDER_FRAME, PlaceholderCar } from "./PlaceholderCar";
 45	import "./carstage.css";
 46	
 47	export type { ZoneDef, Orientation, CarFrame } from "./frame";
 48	export { zoneToWorld } from "./frame";
 49	
 50	export type Priority = "Must" | "Should" | "Could";
 51	export type Hotspot = { zone: string; count: number; top: Priority; aiOnly?: boolean };
 52	
 53	export interface CarStageProps {
 54	  /** "/models/g60.glb", "/models/g60/scene.gltf", or null → placeholder car. */
 55	  modelUrl: string | null;
 56	  /** How the model's own axes map; default { up: "+y", front: "+z" }. */
 57	  orientation?: Orientation;
 58	  zones: Record<string, ZoneDef>;
 59	  hotspots: Hotspot[];
 60	  selectedZone: string | null;
 61	  onSelectZone: (zone: string | null) => void;
 62	  /** Highlight a pin from outside (e.g. list hover). */
 63	  hoverZone?: string | null;
 64	  /** compact = thumbnail use: no controls, slow turntable. */
 65	  mode?: "showroom" | "compact";
 66	  className?: string;
 67	}
 68	
 69	/** Warm the glTF cache before the stage mounts. */
 70	export function preloadCar(url: string) {
 71	  useGLTF.preload(url);
 72	}
 73	
 74	const IDLE_MS = 20_000;
 75	const TURN_SPEED = 0.15; // rad/s
 76	const XRAY_OPACITY = 0.18;
 77	
 78	// ------------------------------------------------------------------------------------------------ helpers
 79	function usePrefersReducedMotion() {
 80	  const [reduced, setReduced] = useState(
 81	    () => typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
 82	  );
 83	  useEffect(() => {
 84	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
 85	    if (!mq) return;
 86	    const on = () => setReduced(mq.matches);
 87	    mq.addEventListener("change", on);
 88	    return () => mq.removeEventListener("change", on);
 89	  }, []);
 90	  return reduced;
 91	}
 92	
 93	let glowTex: THREE.Texture | null = null;
 94	function glowTexture() {
 95	  if (glowTex) return glowTex;
 96	  const c = document.createElement("canvas");
 97	  c.width = c.height = 128;
 98	  const g = c.getContext("2d")!;
 99	  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
100	  grd.addColorStop(0, "rgba(255,255,255,1)");
101	  grd.addColorStop(0.25, "rgba(255,255,255,0.45)");
102	  grd.addColorStop(0.6, "rgba(255,255,255,0.09)");
103	  grd.addColorStop(1, "rgba(255,255,255,0)");
104	  g.fillStyle = grd;
105	  g.fillRect(0, 0, 128, 128);
106	  glowTex = new THREE.CanvasTexture(c);
107	  glowTex.colorSpace = THREE.SRGBColorSpace;
108	  return glowTex;
109	}
110	
111	type MatState = { m: THREE.Material; opacity: number; transparent: boolean; depthWrite: boolean };
112	
113	function collectMaterials(root: THREE.Object3D): MatState[] {
114	  const out: MatState[] = [];
115	  const seen = new Set<THREE.Material>();
116	  root.traverse((o) => {
117	    const mesh = o as THREE.Mesh;
118	    if (!mesh.isMesh) return;
119	    const ms = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
120	    for (const m of ms) {
121	      if (!m || seen.has(m)) continue;
122	      seen.add(m);
123	      out.push({ m, opacity: m.opacity, transparent: m.transparent, depthWrite: m.depthWrite });
124	    }
125	  });
126	  return out;
127	}
128	
129	// ------------------------------------------------------------------------------------------------ model
130	type CarReady = (root: THREE.Object3D, frame: CarFrame) => void;
131	
132	function GltfCar({ url, orientation, onReady }: { url: string; orientation: Orientation; onReady: CarReady }) {
133	  const { scene } = useGLTF(url);
134	  const groupRef = useRef<THREE.Group>(null);
135	
136	  // Own copy (shared geometry/textures, cloned materials) so x-ray / env boosts never leak into the glTF cache.
137	  const prepared = useMemo(() => {
138	    const car = scene.clone(true);
139	    car.traverse((o) => {
140	      const mesh = o as THREE.Mesh;
141	      if (!mesh.isMesh) return;
142	      mesh.castShadow = false;
143	      mesh.receiveShadow = false;
144	      const clone = (m: THREE.Material) => {
145	        const c = m.clone();
146	        const std = c as THREE.MeshStandardMaterial;
147	        if ("envMapIntensity" in std && typeof std.envMapIntensity === "number") {
148	          std.envMapIntensity = Math.max(1.2, std.envMapIntensity * 1.5);
149	        }
150	        return c;
151	      };
152	      mesh.material = Array.isArray(mesh.material) ? mesh.material.map(clone) : clone(mesh.material);
153	    });
154	
155	    // rotate so the model's front → +X, up → +Y
156	    const rot = new THREE.Group();
157	    const m = orientationMatrix(orientation) ?? orientationMatrix(DEFAULT_ORIENTATION)!;
158	    rot.quaternion.setFromRotationMatrix(
159	      new THREE.Matrix4().set(m[0], m[1], m[2], 0, m[3], m[4], m[5], 0, m[6], m[7], m[8], 0, 0, 0, 0, 1),
160	    );
161	    rot.add(car);
162	    rot.updateMatrixWorld(true);
163	    const box = new THREE.Box3().setFromObject(rot);
164	    const size = box.getSize(new THREE.Vector3());
165	    const s = size.x > 0 ? CAR_LENGTH / size.x : 1;
166	    const centre = box.getCenter(new THREE.Vector3());
167	
168	    const wrap = new THREE.Group();
169	    wrap.name = "car-normalised";
170	    wrap.scale.setScalar(s);
171	    wrap.position.set(-centre.x * s, -box.min.y * s, -centre.z * s);
172	    wrap.add(rot);
173	    const frame = frameFromSize([size.x * s, size.y * s, size.z * s]);
174	    return { wrap, frame };
175	  }, [scene, orientation]);
176	
177	  useLayoutEffect(() => {
178	    if (groupRef.current) onReady(groupRef.current, prepared.frame);
179	  }, [prepared, onReady]);
180	
181	  return (
182	    <group ref={groupRef}>
183	      <primitive object={prepared.wrap} />
184	    </group>
185	  );
186	}
187	
188	function Placeholder({ onReady }: { onReady: CarReady }) {
189	  const ref = useRef<THREE.Group>(null);
190	  useLayoutEffect(() => {
191	    if (ref.current) onReady(ref.current, PLACEHOLDER_FRAME);
192	  }, [onReady]);
193	  return (
194	    <group ref={ref}>
195	      <PlaceholderCar />
196	    </group>
197	  );
198	}
