433	  onSelectZone: (z: string | null) => void;
434	}) {
435	  return (
436	    <div className="cs-pins">
437	      {items.map(({ h, z }) => {
438	        const sel = selectedZone === h.zone;
439	        const label = `${z.label} — ${h.count} recommendation${h.count === 1 ? "" : "s"}`;
440	        return (
441	          <div
442	            key={h.zone}
443	            ref={(el) => {
444	              if (el) els.current.set(h.zone, el);
445	              else els.current.delete(h.zone);
446	            }}
447	            className="cs-pin-anchor"
448	          >
449	            <div className="cs-pin-wrap" data-selected={sel ? "1" : "0"} data-hover={hoverZone === h.zone ? "1" : "0"}>
450	              <button
451	                type="button"
452	                className="cs-pin"
453	                data-top={h.top}
454	                aria-label={label + (h.aiOnly ? " (AI suggestion, not yet confirmed)" : "")}
455	                aria-pressed={sel}
456	                onClick={(e) => {
457	                  e.stopPropagation();
458	                  onSelectZone(sel ? null : h.zone);
459	                }}
460	              >
461	                {h.aiOnly && <span className="cs-pin-ai" aria-hidden />}
462	                {h.count}
463	              </button>
464	              <span className="cs-label" aria-hidden>
465	                {z.label}
466	                <b>{h.count}</b>
467	              </span>
468	            </div>
469	          </div>
470	        );
471	      })}
472	    </div>
473	  );
474	}
