476	// ------------------------------------------------------------------------------------------------ camera
477	function CameraRig({
478	  frame,
479	  zone,
480	  compact,
481	  reduced,
482	}: {
483	  frame: CarFrame;
484	  zone: ZoneDef | null;
485	  compact: boolean;
486	  reduced: boolean;
487	}) {
488	  const ref = useRef<CameraControlsImpl>(null);
489	  const lastInput = useRef(performance.now());
490	  const first = useRef(true);
491	
492	  // constraints + input mapping (no pan)
493	  useEffect(() => {
494	    const c = ref.current;
495	    if (!c) return;
496	    const A = (c.constructor as typeof CameraControlsImpl).ACTION;
497	    c.minPolarAngle = 0.12;
498	    c.maxPolarAngle = Math.PI / 2 - 0.05;
499	    c.minDistance = frame.L * 0.9;
500	    c.maxDistance = frame.L * 5.5;
501	    c.dollyToCursor = false;
502	    c.mouseButtons.left = A.ROTATE;
503	    c.mouseButtons.right = A.NONE;
504	    c.mouseButtons.middle = A.DOLLY;
505	    c.mouseButtons.wheel = A.DOLLY;
506	    c.touches.one = A.TOUCH_ROTATE;
507	    c.touches.two = A.TOUCH_DOLLY;
508	    c.touches.three = A.NONE;
509	    c.enabled = !compact;
510	    const onStart = () => {
511	      lastInput.current = performance.now();
512	    };
513	    c.addEventListener("controlstart", onStart);
514	    c.addEventListener("control", onStart);
515	    return () => {
516	      c.removeEventListener("controlstart", onStart);
517	      c.removeEventListener("control", onStart);
518	    };
519	  }, [frame, compact]);
520	
521	  // fly to zone / overview; portrait viewports pull the camera back so the whole car stays in frame
522	  const aspect = useThree((st) => st.size.width / Math.max(1, st.size.height));
523	  useEffect(() => {
524	    const c = ref.current;
525	    if (!c) return;
526	    const raw = poseFor(zone, frame);
527	    const pull = aspect < 1.25 ? Math.min(2.1, Math.pow(1.25 / aspect, 0.85)) : 1;
528	    const p = {
529	      target: raw.target,
530	      eye: raw.eye.map((e, i) => raw.target[i] + (e - raw.target[i]) * pull) as typeof raw.eye,
531	    };
532	    const animate = !reduced && !first.current;
533	    first.current = false;
534	    c.smoothTime = 0.32; // ≈1.2 s settle, ease-out
535	    lastInput.current = performance.now();
536	    void c.setLookAt(p.eye[0], p.eye[1], p.eye[2], p.target[0], p.target[1], p.target[2], animate);
537	  }, [zone, frame, reduced, aspect]);
538	
539	  useFrame((_, dt) => {
540	    const c = ref.current;
541	    if (!c || reduced || zone) return;
542	    const idle = compact || performance.now() - lastInput.current > IDLE_MS;
543	    if (idle) {
544	      void c.rotate(TURN_SPEED * Math.min(dt, 0.1), 0, false);
545	    }
546	  });
547	
548	  return <CameraControls ref={ref} makeDefault />;
549	}
