551	// ------------------------------------------------------------------------------------------------ scene
552	function Scene({
553	  modelUrl,
554	  orientation,
555	  frame,
556	  onFrame,
557	  zones,
558	  pinItems,
559	  pinEls,
560	  selectedZone,
561	  compact,
562	  reduced,
563	  onModelError,
564	  modelFailed,
565	}: {
566	  modelUrl: string | null;
567	  orientation: Orientation;
568	  frame: CarFrame;
569	  onFrame: (f: CarFrame) => void;
570	  zones: Record<string, ZoneDef>;
571	  pinItems: PinItem[];
572	  pinEls: React.RefObject<PinEls>;
573	  selectedZone: string | null;
574	  compact: boolean;
575	  reduced: boolean;
576	  onModelError: (e: Error) => void;
577	  modelFailed: boolean;
578	}) {
579	  const carRef = useRef<THREE.Object3D | null>(null);
580	  const [carVersion, setCarVersion] = useState(0);
581	
582	  const onReady = useCallback<CarReady>(
583	    (root, f) => {
584	      carRef.current = root;
585	      onFrame(f);
586	      setCarVersion((v) => v + 1);
587	    },
588	    [onFrame],
589	  );
590	
591	  const zone = selectedZone ? zones[selectedZone] ?? null : null;
592	  const target = zone ? zoneToWorld(zone.pos, frame) : null;
593	  const xray = !!selectedZone && INTERIOR_ZONES.has(selectedZone);
594	
595	  const placeholder = <Placeholder onReady={onReady} />;
596	
597	  return (
598	    <>
599	      <Studio shadowKey={`${modelUrl ?? "placeholder"}:${modelFailed}:${carVersion}`} />
600	      {modelUrl && !modelFailed ? (
601	        <ModelBoundary key={modelUrl} fallback={placeholder} onError={onModelError}>
602	          <Suspense fallback={null}>
603	            <GltfCar url={modelUrl} orientation={orientation} onReady={onReady} />
604	          </Suspense>
605	        </ModelBoundary>
606	      ) : (
607	        placeholder
608	      )}
609	      <ZoneFocus carRef={carRef} carVersion={carVersion} target={target} xray={xray} reduced={reduced} />
610	      <PinProjector items={pinItems} els={pinEls} xray={xray} selectedZone={selectedZone} />
611	      <CameraRig frame={frame} zone={zone} compact={compact} reduced={reduced} />
612	    </>
613	  );
614	}
