616	function LoadingLine() {
617	  const { active, progress } = useProgress();
618	  if (!active) return null;
619	  const pct = Math.round(progress);
620	  return (
621	    <div className="cs-progress" role="status" aria-live="polite">
622	      <div className="cs-progress-track">
623	        <div className="cs-progress-bar" style={{ width: `${pct}%` }} />
624	      </div>
625	      <div className="cs-progress-pct">{pct}%</div>
626	    </div>
627	  );
628	}
