1	     1	// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it.
2	     2	// Each raw data type has its own colour (TYPE_COLOR); track state is the mark's shape: held contacts (known at the
3	     3	// earlier checkpoint) are dots, contacts this sweep acquired are rings. The flare as the sweep passes, hover and the
4	     4	// lock reticle turn white; blue is the sweep blade itself.
5	     5	// The same rule drives the comments and the dated research on the time ring. Every ring element can be opened.
6	     6	// Opening one focuses its layer (the cluster or one ring): that layer rises, the others sink and fade out of the way.
7	     7	import { useEffect, useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
8	     8	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
9	     9	import { Billboard, Html, OrbitControls } from "@react-three/drei";
10	    10	import * as THREE from "three";
11	    11	import type { PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
12	    12	import { StructureLayer } from "../structure/StructureLayer";
13	    13	import { ClassifyPulse } from "../structure/ClassifyPulse";
