667	   667	      </Layer>
668	   668	      <Layer id="option" focus={focus}>
669	   669	        {guides("option")}
670	   670	        <points geometry={options.geom}
671	   671	                onPointerMove={(e) => { const i = pick(e); if (i != null) { const o = options.items[i]; hover(e, o.name ?? o.code ?? "Option", `Option · ${CAR_NAME[o.car]} · ${o.availability ?? ""}`); } }}
672	   672	                onPointerOut={out}
673	   673	                onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "option", item: options.items[i] }, pos(options.geom, i)); } }}>
674	   674	          <pointsMaterial color={TYPE_COLOR.option} size={0.014 * grow} transparent opacity={0.85} />
675	   675	        </points>
676	   676	        <points geometry={options.off}><pointsMaterial color={TYPE_COLOR.option} size={0.014 * grow} transparent opacity={OFF} /></points>
677	   677	        {slots.option}
678	   678	        {ringName("option")}
679	   679	      </Layer>
680	   680	      <Layer id="sales" focus={focus}>
681	   681	        {guides("sales")}
682	   682	        {bars.map((b, i) => passSales(filter, b.row) ? (
683	   683	          <mesh key={`on${i}`} position={b.pos} rotation={[0, b.rot, 0]} scale={[k, 1, k]}
684	   684	                onPointerMove={(e) => hover(e, `${(b.row.units ?? 0).toLocaleString("en-US")} cars`, `Sales · ${CAR_NAME[b.row.car]} · ${MARKET_NAME[b.row.market]} · ${b.row.year}${b.row.is_forecast ? " forecast" : ""}`)}
685	   685	                onPointerOut={out}
686	   686	                onClick={(e) => { e.stopPropagation(); onSelect({ kind: "sales", item: b.row }, [b.pos[0], b.h, b.pos[2]]); }}>
687	   687	            <boxGeometry args={[0.014, b.h, 0.014]} />
688	   688	            {b.row.is_forecast ? <meshBasicMaterial color={TYPE_COLOR.sales} wireframe transparent opacity={0.6} /> : <meshBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.85} />}
689	   689	          </mesh>
690	   690	        ) : (
691	   691	          <mesh key={`off${i}`} position={b.pos} rotation={[0, b.rot, 0]} scale={[k, 1, k]}>
692	   692	            <boxGeometry args={[0.014, b.h, 0.014]} />
693	   693	            <meshBasicMaterial color={TYPE_COLOR.sales} wireframe={!!b.row.is_forecast} transparent opacity={OFF} />
694	   694	          </mesh>
695	   695	        ))}
696	   696	        <primitive object={lwbArc} />
697	   697	        <Html position={polar(R.sales + 0.17, (sector("G68")[0] + sector("G68")[1]) / 2, 0.02)} center zIndexRange={[10, 0]}>
698	   698	          <div className="ring-sub" data-dim={dim("sales")}>LWB · China</div>
699	   699	        </Html>
700	   700	        {slots.sales}
701	   701	        {ringName("sales")}
702	   702	      </Layer>
703	   703	      {LINES.map((line) => {
704	   704	        const [a0, a1] = lineSector(line);
705	   705	        const state: LabelState = focusLines == null ? "rest" : focusLines.has(line) ? "up" : "down";
706	   706	        return (
707	   707	          <LabelLift key={line} state={state}>
708	   708	            <Html position={polar(R.labels, (a0 + a1) / 2, 0.18)} center zIndexRange={[10, 0]}>
709	   709	              <div className="ring-label" data-dim={state === "down" ? "" : undefined}><b>{CAR_NAME[line]}</b><span>{LINE_CODES[line]}</span></div>
710	   710	            </Html>
711	   711	          </LabelLift>
712	   712	        );
713	   713	      })}
714	   714	    </>
715	   715	  );
716	   716	}
