  1	// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it.
  2	// Each raw data type has its own colour (TYPE_COLOR); track state is the mark's shape: held contacts (known at the
  3	// earlier checkpoint) are dots, contacts this sweep acquired are rings. The flare as the sweep passes, hover and the
  4	// lock reticle turn white; blue is the sweep blade itself.
  5	// The same rule drives the comments and the dated research on the time ring. Every ring element can be opened.
  6	// Opening one focuses its layer (the cluster or one ring): that layer rises, the others sink and fade out of the way.
  7	import { useEffect, useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
  8	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
  9	import { Billboard, Html, OrbitControls } from "@react-three/drei";
 10	import * as THREE from "three";
 11	import type { PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
 12	import { StructureLayer } from "../structure/StructureLayer";
 13	import { ClassifyPulse } from "../structure/ClassifyPulse";
 14	import { passOption, passResearch, passSales, passStudy, type Filter } from "./filter";
 15	import { Navigator, SpreadCtx, spreadOf, useSpread, type NavInput } from "./navigate";
 16	import { CARS, CAR_NAME, LINES, LINE_CODES, MARKET_NAME, R, SWEEP_START, TAU, TIME_START, lineSector, optionLayout, polar, sector, studyLayout, timeAngle } from "./layout";
 17	
 18	const VERT = /* glsl */ `
 19	attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
 20	attribute vec3 aTarget; attribute float aClustered;
 21	uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim, uMorph, uGrow, uDepth;
 22	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
 23	const float TAU = 6.2831853;
 24	void main() {
 25	  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
 26	  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
 27	  float passed = step(d, uSweep);
 28	  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
 29	  vFlare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 14.0) * (1.0 - pow(uSweep, 12.0)) : 0.0;
 30	  vRing = abs(aCp - uCp) < 0.5 ? 1.0 : 0.0;          // acquired by the current sweep
 31	  vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
 32	  vec3 pp = mix(position, aTarget, uMorph);            // page 2: comments fly into their cluster
 33	  vec4 mv = modelViewMatrix * vec4(pp, 1.0);
 34	  float depth = smoothstep(3.2 * uDepth, 7.5 * uDepth, -mv.z);  // far contacts recede (scaled with the spread)
 35	  vAlpha = vis * mix(uDim, 1.0, aSel) * mix(0.95, 0.4, depth) * mix(1.0, mix(0.08, 0.4, aClustered), uMorph);
 36	  gl_Position = projectionMatrix * mv;
 37	  gl_PointSize = aSize * uScale * uGrow * (1.0 + vRing * 0.25 + vFlare * 2.0 + vHov * 2.2) / -mv.z;
 38	}`;
 39	const FRAG = /* glsl */ `
 40	uniform vec3 uColor; uniform float uFade;
 41	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
 42	void main() {
 43	  float r = length(gl_PointCoord - 0.5);
 44	  if (r > 0.5) discard;
 45	  float dot = smoothstep(0.5, 0.3, r);
 46	  float ring = smoothstep(0.5, 0.42, r) * smoothstep(0.24, 0.32, r);
 47	  float a = mix(dot, ring, vRing * (1.0 - vFlare));
 48	  vec3 col = mix(uColor, vec3(1.0), max(vFlare, vHov));
 49	  gl_FragColor = vec4(col, min(1.0, vAlpha + vHov) * a * uFade);
 50	}`;
 51	
 52	import { TYPE_COLOR } from "./colors";
 53	export { TYPE_COLOR };
 54	
 55	function contactMaterial(scale: number, color: string) {
 56	  return new THREE.ShaderMaterial({
 57	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
 58	    uniforms: {
 59	      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
 60	      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 }, uFade: { value: 1 }, uMorph: { value: 0 }, uGrow: { value: 1 }, uDepth: { value: 1 },
 61	      uColor: { value: new THREE.Color(color) },
 62	    },
 63	  });
 64	}
 65	
 66	function attrGeometry(pos: Float32Array, attrs: Record<string, Float32Array>) {
 67	  const g = new THREE.BufferGeometry();
 68	  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
 69	  for (const [k, v] of Object.entries(attrs)) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
 70	  g.computeBoundingSphere();
 71	  return g;
 72	}
 73	
 74	/* ------------------------------------------------------------------------------------------- focus layers */
 75	// One layer per raw data type: the comment cluster and the four rings. Public research sits on its car's ring.
 76	export type LayerId = "comment" | "research" | "study" | "option" | "sales";
 77	export const layerOf = (s: Selection): LayerId | null =>
 78	  s.kind === "cluster" || s.kind === "theme" || s.kind === "area" ? null
 79	    : s.kind !== "research" ? s.kind : s.item.ring === "options" ? "option" : (s.item.ring ?? "research");
 80	
 81	const LIFT = 0.12, SINK = -0.5, FADE = 0.08;
 82	const ORDER: LayerId[] = ["comment", "research", "study", "option", "sales"]; // inside out
 83	const RISE = 0.85, FALL = 0.7, STAGGER = 0.07;                                 // seconds
 84	const easeOutBack = (t: number) => 1 + 2.2 * Math.pow(t - 1, 3) + 1.2 * Math.pow(t - 1, 2);
 85	const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
 86	const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);
 87	
 88	// Focus choreography: the chosen layer springs up (slight overshoot) with a soft scale pulse; the others sink and
 89	// fade in a ripple outward from it. Releasing focus ripples back the same way. Under reduced motion the layers still
 90	// glide (the move is what shows which layer the item belongs to), just without overshoot, pulse or ripple.
 91	function Layer({ id, focus, children }: { id: LayerId; focus: LayerId | null; children: ReactNode }) {
 92	  const ref = useRef<THREE.Group>(null);
 93	  const st = useRef({ y: 0, a: 1, fy: 0, fa: 1, t0: -1, delay: 0, rising: false, focus: null as LayerId | null });
 94	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
 95	  useFrame(({ clock }) => {
 96	    const g = ref.current;
 97	    if (!g) return;
 98	    const s = st.current, now = clock.elapsedTime;
 99	    if (s.focus !== focus) {                 // new target: start a tween from wherever the layer is now
100	      const anchor = focus ?? s.focus;       // ripple out from the layer gaining (or losing) focus
101	      s.focus = focus;
102	      s.fy = s.y; s.fa = s.a; s.t0 = now; s.rising = focus === id;
103	      s.delay = reduced || anchor == null || s.rising ? 0 : Math.abs(ORDER.indexOf(id) - ORDER.indexOf(anchor)) * STAGGER;
104	    }
105	    const [ty, ta] = focus == null ? [0, 1] : focus === id ? [LIFT, 1] : [SINK, FADE];
106	    let p = 1;
107	    if (s.t0 >= 0) p = Math.min(1, Math.max(0, (now - s.t0 - s.delay) / (s.rising ? RISE : FALL)));
108	    if (p >= 1 && s.y === ty && s.a === ta && g.userData.settled === children) return;
109	    s.y = s.fy + (ty - s.fy) * (s.rising && !reduced ? easeOutBack(p) : easeInOut(p));
110	    s.a = s.fa + (ta - s.fa) * easeOut(p);
111	    if (p >= 1) { s.y = ty; s.a = ta; }
112	    g.position.y = s.y;
113	    g.scale.setScalar(s.rising && !reduced ? 1 + 0.04 * Math.sin(Math.PI * p) : 1);
114	    g.userData.settled = children;
115	    g.traverse((o) => {
116	      const mat = (o as THREE.Mesh).material;
117	      if (!mat) return;
118	      for (const m of Array.isArray(mat) ? mat : [mat]) {
119	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uFade) m.uniforms.uFade.value = s.a; continue; }
120	        if (m.userData.written !== m.opacity) m.userData.baseOpacity = m.opacity;   // React set a new opacity (e.g. a filter)
121	        m.opacity = m.userData.written = m.userData.baseOpacity * s.a;
122	      }
123	    });
124	  });
125	  return <group ref={ref}>{children}</group>;
126	}
127	
128	// A car name moves with the focus too: the selected item's car line rises with its layer, the other names sink and
129	// (via data-dim) fade. Items without a car (most research) sink every name.
130	type LabelState = "rest" | "up" | "down";
131	function LabelLift({ state, children }: { state: LabelState; children: ReactNode }) {
132	  const ref = useRef<THREE.Group>(null);
133	  const st = useRef({ fy: 0, t0: -1, state: "rest" as LabelState });
134	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
135	  useFrame(({ clock }) => {
136	    const g = ref.current;
137	    if (!g) return;
138	    const s = st.current, now = clock.elapsedTime;
139	    if (s.state !== state) { s.state = state; s.fy = g.position.y; s.t0 = now; }
140	    if (s.t0 < 0) return;
141	    const up = state === "up", ty = state === "rest" ? 0 : up ? LIFT : SINK;
142	    const p = Math.min(1, (now - s.t0) / (up ? RISE : FALL));
143	    g.position.y = s.fy + (ty - s.fy) * (up && !reduced ? easeOutBack(p) : easeInOut(p));
144	    if (p >= 1) { g.position.y = ty; s.t0 = -1; }
145	  });
146	  return <group ref={ref}>{children}</group>;
147	}
148	
149	/* ------------------------------------------------------------------------------------------- sweep clock */
150	function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
151	  const start = useRef<number | null>(null);
152	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
153	  useEffect(() => {
154	    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
155	    start.current = reduced || position === fromPosition ? null : performance.now();
156	  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
157	  useFrame(() => {
158	    if (start.current == null) { onAngle(null); return; }
159	    const t = Math.min(1, (performance.now() - start.current) / 2400);
160	    const e = 1 - Math.pow(1 - t, 3);
161	    for (const m of mats) m.uniforms.uSweep.value = e;
162	    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
163	    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
164	  });
165	}
166	
167	/* ------------------------------------------------------------------------------------------- camera fit */
168	/** Camera distance that frames the whole volume at spread 1. */
169	function useFit() {
170	  const { camera, size } = useThree();
171	  return () => {
172	    const aspect = size.width / size.height;
173	    const fit = (R.labels + 0.3) / (Math.tan(THREE.MathUtils.degToRad((camera as THREE.PerspectiveCamera).fov / 2)) * aspect);
174	    return Math.max(aspect < 1 ? 6 : 5.6, fit);
175	  };
176	}
177	function CameraFit({ fit, spread }: { fit: () => number; spread: number }) {
178	  const { camera, size } = useThree();
179	  useEffect(() => {
180	    const cam = camera as THREE.PerspectiveCamera;
181	    cam.fov = size.width / size.height < 1 ? 58 : 40;
182	    cam.position.setLength(fit() * spread);
183	    cam.updateProjectionMatrix();
184	  }, [camera, size.width, size.height]); // eslint-disable-line react-hooks/exhaustive-deps -- spread changes rescale in Navigator
185	  return null;
186	}
187	
188	/* ------------------------------------------------------------------------------------------- scene */
189	export interface Hover { title: string; sub?: string; comment?: number; acquiredHere?: boolean; x: number; y: number }
190	
191	interface SceneProps {
192	  points: PointsPayload;
193	  sources: SourcesPayload | undefined;
194	  mask: Uint8Array;
195	  position: number; fromPosition: number; sweepId: number;
196	  hoverComment: number | null;
197	  locked: [number, number, number] | null;
198	  focus: LayerId | null;
199	  onHover: (h: Hover | null) => void;
200	  onSelect: (s: Selection, at: [number, number, number]) => void;
201	  /** page 2: comments fly into their clusters and the AI's structure appears on top */
202	  mode?: "scan" | "structure";
203	  structure?: StructurePayload;
204	  selected?: Selection | null;
205	  hoverKey?: string | null;
206	  onStructureHover?: (h: Hover | null, key?: string | null) => void;
207	  /** source ids the agent just classified (they flash in place) */
208	  pulse?: number[];
209	  /** the Key's filter on page 1: what doesn't match dims like a masked comment and can't be picked */
210	  filter?: Filter | null;
211	  /** layout scale of the whole universe (navigate.tsx) */
212	  spread?: number;
213	  /** the pad's hold-to-fly buttons and reset */
214	  nav: MutableRefObject<NavInput>;
215	}
216	
217	export const studyValue = (s: { scale: string; value: number | null }) =>
218	  s.value == null ? "" : s.scale === "dist_7" ? `${Math.round(s.value * 100)}% top-2` : `${s.value.toFixed(1)} / 10`;
219	
220	export function Scene(p: SceneProps) {
221	  const { gl } = useThree();
222	  const dpr = gl.getPixelRatio();
223	  const commentMat = useMemo(() => contactMaterial(15 * dpr, TYPE_COLOR.comment), [dpr]);
224	  const researchMat = useMemo(() => contactMaterial(19 * dpr, TYPE_COLOR.research), [dpr]);
225	  const sweepRef = useRef<THREE.Group>(null);
226	  const setCursor = (on: boolean) => { gl.domElement.style.cursor = on ? "pointer" : ""; };
227	  const spread = useMemo(() => spreadOf(p.spread ?? 1), [p.spread]);
228	  const fit = useFit();
229	
230	  /* comments */
231	  const comments = useMemo(() => {
232	    const c = p.points.cols, n = p.points.n;
233	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
234	    for (let i = 0; i < n; i++) {
235	      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
236	      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
237	      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
238	    }
239	    return attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) });
240	  }, [p.points]);
241	  useEffect(() => {
242	    const a = comments.getAttribute("aSel") as THREE.BufferAttribute;
243	    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
244	    a.needsUpdate = true;
245	  }, [comments, p.mask]);
246	  useEffect(() => { commentMat.uniforms.uHover.value = p.hoverComment ?? -1; }, [commentMat, p.hoverComment]);
247	
248	  /* page 2 morph: each comment's target is its cluster centre (pulled in tight); unclustered comments stay and dim */
249	  useEffect(() => {
250	    const n = p.points.n, src = comments.getAttribute("position") as THREE.BufferAttribute;
251	    const target = new Float32Array(n * 3), clustered = new Float32Array(n);
252	    const st = p.structure;
253	    const at = new Map<number, number>();
254	    if (st?.ready) st.member.ids.forEach((id, i) => at.set(id, st.member.cluster[i]));
255	    for (let i = 0; i < n; i++) {
256	      const x = src.getX(i), y = src.getY(i), z = src.getZ(i);
257	      const ci = at.get(p.points.cols.id[i]);
258	      const c = ci != null && ci >= 0 ? st!.clusters[ci] : null;
259	      if (c && !c.tail) {
260	        target.set([c.x + (x - c.x) * 0.07, c.y + (y - c.y) * 0.07, c.z + (z - c.z) * 0.07], i * 3);
261	        clustered[i] = 1;
262	      } else target.set([x, y, z], i * 3);
263	    }
264	    comments.setAttribute("aTarget", new THREE.BufferAttribute(target, 3));
265	    comments.setAttribute("aClustered", new THREE.BufferAttribute(clustered, 1));
266	  }, [comments, p.points, p.structure]);
267	  const morph = useRef(0);
268	  useFrame((_, dt) => {
269	    const goal = p.mode === "structure" && p.structure?.ready ? 1 : 0;
270	    if (morph.current === goal) return;
271	    const step = dt / 1.6;
272	    morph.current = goal > morph.current ? Math.min(goal, morph.current + step) : Math.max(goal, morph.current - step);
273	    const t = morph.current;
274	    commentMat.uniforms.uMorph.value = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
275	  });
276	
277	  /* research on the time ring */
278	  const research = useMemo(() => {
279	    const items = (p.sources?.research ?? []).filter((r) => !r.ring);
280	    const n = items.length;
281	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
282	    items.forEach((it, i) => {
283	      const a = timeAngle(it.published_at);
284	      const lane = (it.id % 7) / 7;
285	      const [x, , z] = polar(R.time + (lane - 0.5) * 0.1, a);
286	      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
287	      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = i;
288	    });
289	    return { items, geom: attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) }) };
290	  }, [p.sources]);
291	
292	  /* public research about one car line, on that car's study / options / sales ring (D-042) */
293	  const studyMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.study), [dpr]);
294	  const optionMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.option), [dpr]);
295	  const salesMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.sales), [dpr]);
296	  const carRings = useMemo(() => {
297	    const all = (p.sources?.research ?? []).filter((r) => r.ring);
298	    const build = (ring: "study" | "options" | "sales", radius: number) => {
299	      // one entry per (item × car); the 5 Series' China items go to the long-wheelbase G68 part of the sector
300	      const slots = new Map<string, { it: ResearchItem; car: string }[]>();
301	      for (const it of all.filter((r) => r.ring === ring)) for (const car of it.cars) {
302	        const key = car === "G60" && it.region === "CN" ? "G68" : car;
303	        slots.set(key, [...(slots.get(key) ?? []), { it, car: key }]);
304	      }
