520	function Reticle({ at }: { at: [number, number, number] }) {
521	  const ref = useRef<THREE.Group>(null);
522	  const { k } = useSpread();
523	  useFrame(({ clock }) => { if (ref.current) ref.current.rotation.z = clock.elapsedTime * 0.8; });
524	  return (
525	    <Billboard position={at} scale={k}>
526	      <group ref={ref}>
527	        {[0, 1, 2, 3].map((k) => (
528	          <mesh key={k} rotation={[0, 0, (k * Math.PI) / 2]}>
529	            <ringGeometry args={[0.045, 0.052, 16, 1, -0.45, 0.9]} />
530	            <meshBasicMaterial color="#ffffff" transparent opacity={0.95} depthTest={false} />
531	          </mesh>
532	        ))}
533	      </group>
534	    </Billboard>
535	  );
536	}
