676	        <points geometry={options.off}><pointsMaterial color={TYPE_COLOR.option} size={0.014 * grow} transparent opacity={OFF} /></points>
677	        {slots.option}
678	        {ringName("option")}
679	      </Layer>
680	      <Layer id="sales" focus={focus}>
681	        {guides("sales")}
682	        {bars.map((b, i) => passSales(filter, b.row) ? (
683	          <mesh key={`on${i}`} position={b.pos} rotation={[0, b.rot, 0]} scale={[k, 1, k]}
684	                onPointerMove={(e) => hover(e, `${(b.row.units ?? 0).toLocaleString("en-US")} cars`, `Sales · ${CAR_NAME[b.row.car]} · ${MARKET_NAME[b.row.market]} · ${b.row.year}${b.row.is_forecast ? " forecast" : ""}`)}
685	                onPointerOut={out}
686	                onClick={(e) => { e.stopPropagation(); onSelect({ kind: "sales", item: b.row }, [b.pos[0], b.h, b.pos[2]]); }}>
687	            <boxGeometry args={[0.014, b.h, 0.014]} />
688	            {b.row.is_forecast ? <meshBasicMaterial color={TYPE_COLOR.sales} wireframe transparent opacity={0.6} /> : <meshBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.85} />}
689	          </mesh>
690	        ) : (
691	          <mesh key={`off${i}`} position={b.pos} rotation={[0, b.rot, 0]} scale={[k, 1, k]}>
692	            <boxGeometry args={[0.014, b.h, 0.014]} />
693	            <meshBasicMaterial color={TYPE_COLOR.sales} wireframe={!!b.row.is_forecast} transparent opacity={OFF} />
694	          </mesh>
695	        ))}
696	        <primitive object={lwbArc} />
697	        <Html position={polar(R.sales + 0.17, (sector("G68")[0] + sector("G68")[1]) / 2, 0.02)} center zIndexRange={[10, 0]}>
698	          <div className="ring-sub" data-dim={dim("sales")}>LWB · China</div>
699	        </Html>
700	        {slots.sales}
701	        {ringName("sales")}
702	      </Layer>
703	      {LINES.map((line) => {
704	        const [a0, a1] = lineSector(line);
705	        const state: LabelState = focusLines == null ? "rest" : focusLines.has(line) ? "up" : "down";
706	        return (
707	          <LabelLift key={line} state={state}>
708	            <Html position={polar(R.labels, (a0 + a1) / 2, 0.18)} center zIndexRange={[10, 0]}>
709	              <div className="ring-label" data-dim={state === "down" ? "" : undefined}><b>{CAR_NAME[line]}</b><span>{LINE_CODES[line]}</span></div>
710	            </Html>
711	          </LabelLift>
712	        );
713	      })}
714	    </>
715	  );
716	}

