1	     1	// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
2	     2	import { Suspense, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
3	     3	import { Canvas } from "@react-three/fiber";
4	     4	import { useQuery } from "@tanstack/react-query";
5	     5	import { ChevronsLeft, ChevronsRight, ExternalLink, SlidersHorizontal, X } from "lucide-react";
6	     6	import { api } from "@/lib/api";
7	     7	import type { Comment, PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
8	     8	import { AreaBody, ClusterBody, Funnel, SignalList, ThemeBody } from "../structure/panels";
9	     9	import { AgentPanel, useActivity } from "../structure/AgentPanel";
10	    10	import { PageSwitch } from "@/components/PageSwitch";
11	    11	import { Dock } from "@/components/Guide";
12	    12	import { useCheckpoint } from "@/state/checkpoint";
13	    13	import { Scene, TYPE_COLOR, layerOf, studyValue, type Hover } from "./Scene";
14	    14	import { CAR_NAME, MARKET_NAME } from "./layout";
15	    15	import { HOME, NavPad, SPREAD_MAX, SPREAD_MIN, newNav } from "./navigate";
16	    16	import { DIMS, SCOPE_NOTE, commentMask, isActive, keyValues, passOption, passResearch, passSales, passStudy, valueName, type Dim, type Filter, type Scope } from "./filter";
17	    17	import "./scan.css";
18	    18	
19	    19	// the spread is a per-viewer convenience: remembered in this browser, 1× when storage is unavailable
20	    20	const SPREAD_KEY = "scan.spread";
21	    21	function storedSpread() {
22	    22	  try { const v = Number(localStorage.getItem(SPREAD_KEY)); return v >= SPREAD_MIN && v <= SPREAD_MAX ? v : 1; } catch { return 1; }
23	    23	}
24	    24	
25	    25	const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));
26	    26	
27	    27	
28	    28	export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" }) {
29	    29	  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
30	    30	  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
31	    31	                               staleTime: 30_000, placeholderData: (prev) => prev });
32	    32	  const [hoverKey, setHoverKey] = useState<string | null>(null);
33	    33	  const activity = useActivity();
34	    34	  // when a stage finishes, show its output without a reload
35	    35	  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
36	    36	  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
37	    37	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
38	    38	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
39	    39	  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
40	    40	  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
41	    41	  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
42	    42	    const vals = new Set(f[d]);
43	    43	    if (vals.has(v)) vals.delete(v); else vals.add(v);
44	    44	    const next = { ...f, [d]: vals };
45	    45	    if (!vals.size) delete next[d];
46	    46	    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
47	    47	  });
48	    48	  const clear = (d?: Dim) => setChosen(({ f, order }) => {
49	    49	    if (!d) return { f: {}, order: [] };
50	    50	    const next = { ...f }; delete next[d];
51	    51	    return { f: next, order: order.filter((x) => x !== d) };
52	    52	  });
53	    53	  const [hover, setHover] = useState<Hover | null>(null);
54	    54	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
55	    55	  const [spread, setSpread] = useState(storedSpread);
56	    56	  useEffect(() => { try { localStorage.setItem(SPREAD_KEY, String(spread)); } catch { /* private mode */ } }, [spread]);
57	    57	  const nav = useRef(newNav());
58	    58	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
59	    59	
60	    60	  // the filters work on page 1 only; page 2 hides them, so nothing stays filtered there unseen
61	    61	  const filter = useMemo<Filter | null>(() => (mode === "scan" && isActive(chosen.f) ? chosen.f : null), [mode, chosen]);
62	    62	  const mask = useMemo(() => (points.data ? commentMask(points.data, filter) : new Uint8Array(0)), [points.data, filter]);
63	    63	
64	    64	  useEffect(() => {
65	    65	    const onKey = (e: KeyboardEvent) => {
66	    66	      if (e.key !== "Escape") return;
67	    67	      if (selected) setSelected(null); else clear();
68	    68	    };
69	    69	    window.addEventListener("keydown", onKey);
70	    70	    return () => window.removeEventListener("keydown", onKey);
71	    71	  }, [selected]);
72	    72	  useEffect(() => { setSelected(null); setHover(null); }, [mode]);
73	    73	
74	    74	  return (
75	    75	    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
76	    76	      <div className="scan-canvas">
77	    77	        {points.data && (
78	    78	          <Canvas dpr={[1, 2]} camera={{ position: HOME, fov: 40, near: 0.05, far: 60 }}
79	    79	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
80	    80	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
81	    81	                  onPointerMissed={() => setSelected(null)}>
82	    82	            <Suspense fallback={null}>
83	    83	              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
84	    84	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
85	    85	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
86	    86	                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
87	    87	                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter}
88	    88	                     spread={spread} nav={nav} />
89	    89	            </Suspense>
90	    90	          </Canvas>
91	    91	        )}
92	    92	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
93	    93	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
94	    94	      </div>
95	    95	
96	    96	      {mode === "scan" ? (
97	    97	        <div className="hud-tl">
98	    98	          <Readout points={points.data} mask={mask} filter={filter} />
99	    99	          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
100	   100	                                     onToggle={toggle} onClear={clear} />}
101	   101	        </div>
102	   102	      ) : <Funnel data={structure.data} />}
103	   103	      <Dock mode={mode} sel={selected?.sel ?? null} agent={mode === "structure" ? <AgentPanel /> : undefined} running={!!activity.data?.running} />
104	   104	      <PageSwitch />
105	   105	      {points.data && <NavPad spread={spread} onSpread={setSpread} nav={nav} />}
106	   106	
107	   107	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
108	   108	      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
109	   109	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
110	   110	    </main>
111	   111	  );
112	   112	}
113	   113	
114	   114	/* ------------------------------------------------------------------------------------------- glyphs */
115	   115	type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
116	   116	const GLYPH_COLOR: Record<GlyphKind, string> = {
117	   117	  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
118	   118	};
119	   119	function Glyph({ kind }: { kind: GlyphKind }) {
120	   120	  const c = "currentColor";
121	   121	  return (
122	   122	    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
123	   123	      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
124	   124	      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
125	   125	      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
126	   126	      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
127	   127	      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
128	   128	    </svg>
129	   129	  );
130	   130	}
131	   131	
132	   132	/* ------------------------------------------------------------------------------------------- readout */
133	   133	// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
134	   134	// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
135	   135	// While filters are set, every count is what they leave visible.
136	   136	function Readout({ points, mask, filter }: { points: PointsPayload | undefined; mask: Uint8Array; filter: Filter | null }) {
137	   137	  const { current, position } = useCheckpoint();
138	   138	  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
139	   139	  const s = current?.sources;
140	   140	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
141	   141	  const comments = useMemo(() => {
142	   142	    if (!filter || !points) return { n: s?.feedback.visible, nu: s?.feedback.new };
143	   143	    let n = 0, nu = 0;
144	   144	    for (let i = 0; i < points.n; i++) if (mask[i] && points.cols.cp[i] <= position) { n++; if (points.cols.cp[i] === position && position > 1) nu++; }
145	   145	    return { n, nu };
146	   146	  }, [filter, points, mask, position, s]);
147	   147	  const research = (ring: ResearchItem["ring"]) => {
148	   148	    const items = (src?.research ?? []).filter((r) => r.ring === ring && (position > 1 || !r.new) && passResearch(filter, r));
149	   149	    return src ? { n: items.length, nu: items.filter((r) => r.new).length } : undefined;
150	   150	  };
151	   151	  const time = research(null), rating = research("study"), news = research("options"), pub = research("sales");
152	   152	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number; pub?: { label: string; c?: { n: number; nu: number } } }[] = [
153	   153	    { k: "comment", label: "Customer comments", n: comments.n, nu: comments.nu },
154	   154	    { k: "research", label: "Web research", n: time?.n, nu: time?.nu },
155	   155	    { k: "study", label: "Customer study", n: src?.study.filter((x) => passStudy(filter, x)).length, pub: { label: "public ratings", c: rating } },
156	   156	    { k: "option", label: "Equipment options", n: src?.options.filter((x) => passOption(filter, x)).length, pub: { label: "product news", c: news } },
157	   157	    { k: "sales", label: "Sales volumes", n: src?.sales.filter((r) => r.units && r.units > 0 && passSales(filter, r)).length, pub: { label: "public sales", c: pub } },
158	   158	  ];
159	   159	  return (
160	   160	    <dl className="readout" aria-label="Evidence at this checkpoint">
161	   161	      {cells.map((c) => (
162	   162	        <div key={c.label}>
163	   163	          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
164	   164	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
165	   165	          {c.pub && (
166	   166	            <dd className="readout-pub">
167	   167	              <i style={{ borderColor: GLYPH_COLOR[c.k] }} aria-hidden />
168	   168	              <span>{fmt(c.pub.c?.n)} {c.pub.label}</span>{plus(c.pub.c?.nu)}
169	   169	            </dd>
170	   170	          )}
171	   171	        </div>
172	   172	      ))}
173	   173	    </dl>
174	   174	  );
175	   175	}
176	   176	
177	   177	/* ------------------------------------------------------------------------------------------- filters */
178	   178	// One chip per dimension, under the readout, always shown. Dimensions in use come first, in the order they were set,
179	   179	// so choosing a value never moves a chip that is already set. A toggle at the head of the row folds the unused chips
180	   180	// away (the ones in use stay, so nothing is filtered unseen) and unfolds them to the right again; the choice is kept
181	   181	// per browser. Hovering a chip opens its values; choosing one closes the list again, so only the choice stays. Car and
182	   182	// market filter every data type; the other chips belong to one type and carry its glyph (comments: channel, label,
183	   183	// engine, length; research: trust, topic, fact type; study: result; options: category, availability; sales: year).
184	   184	const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
185	   185	const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";
186	   186	
187	   187	interface FilterProps {
188	   188	  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
189	   189	  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
190	   190	}
191	   191	
192	   192	const FOLD_KEY = "scan.filters.folded";
193	   193	const readFolded = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };
194	   194	
195	   195	function FilterBar(p: FilterProps) {
196	   196	  const [folded, setFolded] = useState(readFolded);
197	   197	  const [open, setOpen] = useState<Dim | null>(null);
198	   198	  const fold = (f: boolean) => {
199	   199	    setFolded(f); setOpen(null);
200	   200	    try { localStorage.setItem(FOLD_KEY, f ? "1" : "0"); } catch { /* storage blocked: the choice just isn't kept */ }
201	   201	  };
202	   202	  const active = p.order.filter((d) => p.filter[d]?.size);
203	   203	  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
204	   204	  return (
205	   205	    <div className="filters" role="toolbar" aria-label="Filter the scan" data-folded={folded ? "" : undefined}>
206	   206	      <button className="filters-fold" aria-expanded={!folded} aria-controls="scan-filter-chips"
207	   207	              aria-label={folded ? "Show all filters" : "Hide unused filters"} title={folded ? "Show all filters" : "Hide unused filters"}
208	   208	              onClick={() => fold(!folded)}>
209	   209	        <SlidersHorizontal size={12} aria-hidden />
210	   210	        {folded && <span>Filter{idle.length ? ` · ${idle.length}` : ""}</span>}
211	   211	        {folded ? <ChevronsRight size={13} aria-hidden /> : <ChevronsLeft size={13} aria-hidden />}
212	   212	      </button>
213	   213	      <div className="filters-chips" id="scan-filter-chips">
214	   214	        {[...active, ...(folded ? [] : idle)].map((d) => (
215	   215	          <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
216	   216	        ))}
217	   217	        {active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
218	   218	      </div>
219	   219	    </div>
220	   220	  );
221	   221	}
222	   222	
223	   223	function Chip({ dim, open, setOpen, ...p }: FilterProps & { dim: Dim; open: boolean; setOpen: (o: boolean) => void }) {
224	   224	  const meta = DIMS.find((d) => d.id === dim)!;
225	   225	  const chosen = p.filter[dim];
226	   226	  const values = useMemo(() => (open ? keyValues(dim, p.points, p.sources, p.position, p.filter) : []),
227	   227	    [open, dim, p.points, p.sources, p.position, p.filter]);
228	   228	  const max = Math.max(1, ...values.map((v) => v.n));
229	   229	  const names = [...(chosen ?? [])].map((v) => valueName(dim, v));
230	   230	  return (
231	   231	    <div className="fchip" data-on={chosen?.size ? "" : undefined} data-open={open ? "" : undefined}
232	   232	         onPointerEnter={(e) => isMouse(e) && setOpen(true)} onPointerLeave={(e) => isMouse(e) && setOpen(false)}>
233	   233	      <button className="fchip-btn" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
234	   234	        {meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}
235	   235	        <span className="fchip-dim">{meta.name}</span>
236	   236	        {names.length > 0 && <span className="fchip-val">{names[0]}{names.length > 1 ? ` +${names.length - 1}` : ""}</span>}
237	   237	      </button>
238	   238	      {chosen?.size ? <button className="fchip-x" aria-label={`Clear ${meta.name} filter`} onClick={() => p.onClear(dim)}><X size={12} /></button> : null}
239	   239	      {open && (
240	   240	        <div className="fpop">
241	   241	          <div className="fpop-panel" role="listbox" aria-multiselectable aria-label={meta.name}>
242	   242	            <p className="fpop-scope">{meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}{SCOPE_NOTE[meta.scope]}</p>
243	   243	            {values.map(({ v, name, n }) => (
244	   244	              <button key={v} role="option" aria-selected={!!chosen?.has(v)} onClick={() => { p.onToggle(dim, v); setOpen(false); }}>
245	   245	                <span className="fpop-name">{name}</span>
246	   246	                <span className="fpop-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
247	   247	                <span className="fpop-n">{fmt(n)}</span>
248	   248	              </button>
249	   249	            ))}
250	   250	          </div>
251	   251	        </div>
252	   252	      )}
253	   253	    </div>
254	   254	  );
255	   255	}
256	   256	
257	   257	/* ------------------------------------------------------------------------------------------- hover */
258	   258	const useComment = (id: number | null) =>
259	   259	  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });
260	   260	
261	   261	function HoverCard({ hover, points }: { hover: Hover; points: PointsPayload | undefined }) {
262	   262	  const id = hover.comment != null && points ? points.cols.id[hover.comment] : null;
263	   263	  const q = useComment(id);
264	   264	  const left = Math.min(hover.x + 16, window.innerWidth - 336), top = Math.min(hover.y + 16, window.innerHeight - 140);
265	   265	  return (
266	   266	    <div className="hovercard" style={{ left, top }} role="tooltip">
267	   267	      {id != null ? (
268	   268	        <>
269	   269	          <p>{q.data?.text ?? " "}</p>
270	   270	          {q.data && (
271	   271	            <div className="hovercard-meta">
272	   272	              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
273	   273	              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
274	   274	            </div>
275	   275	          )}
276	   276	        </>
277	   277	      ) : (
278	   278	        <>
279	   279	          <p>{hover.title}</p>
280	   280	          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
281	   281	        </>
282	   282	      )}
283	   283	    </div>
284	   284	  );
285	   285	}
286	   286	
287	   287	/* ------------------------------------------------------------------------------------------- inspector */
288	   288	const LAYER: Record<Selection["kind"], { name: string; what: string; glyph: GlyphKind }> = {
289	   289	  comment: { name: "Customer comment", what: "Placed by meaning: comments that say similar things sit close together.", glyph: "comment" },
290	   290	  cluster: { name: "Cluster", what: "Signals from many comments that express the same need. Blue = improve, white = keep.", glyph: "comment" },
291	   291	  theme: { name: "Theme", what: "Related findings grouped by the AI, connected to research, study and options that confirm or contradict them.", glyph: "research" },
292	   292	  area: { name: "Potential requirement area", what: "Themes the AI grouped into an area a requirement could address. Requirements are drafted in the next step.", glyph: "sales" },
293	   293	  study: { name: "Customer study 2025", what: "Tick length: how far this topic is rated above or below this car's average.", glyph: "study" },
294	   294	  option: { name: "Equipment option", what: "Today's car, from the German price list.", glyph: "option" },
295	   295	  sales: { name: "BMW sales volume", what: "BMW-internal figures, stylized (Q-015). Outline = 2030 forecast.", glyph: "sales" },
296	   296	  research: { name: "Web research", what: "Cited source, placed on the outer ring by publication date.", glyph: "research" },
297	   297	};
298	   298	
299	   299	const PUBLIC_LAYER: Record<"sales" | "study" | "options", { name: string; what: string; glyph: GlyphKind }> = {
300	   300	  sales: { name: "Public sales figure", what: "Cited, published figure for this car. Dots and rings sit beside BMW's own bars, never mixed with them.", glyph: "sales" },
301	   301	  study: { name: "Public rating", what: "Published review, award or study result about this car.", glyph: "study" },
302	   302	  options: { name: "Product news", what: "Published news about this car's equipment, prices or availability.", glyph: "option" },
303	   303	};
304	   304	
305	   305	function Inspector({ sel, sales, onClose, cpLabel, structure }: { sel: Selection; sales: SourcesPayload["sales"]; onClose: () => void; cpLabel: (id: string) => string; structure?: StructurePayload }) {
306	   306	  const L = sel.kind === "research" && sel.item.ring ? PUBLIC_LAYER[sel.item.ring] : LAYER[sel.kind];
307	   307	  return (
308	   308	    <aside className="sheet" aria-label={L.name}>
309	   309	      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
310	   310	      <header className="sheet-head">
311	   311	        <span className="sheet-layer"><Glyph kind={L.glyph} />{L.name}</span>
312	   312	        <p className="sheet-what">{L.what}</p>
313	   313	      </header>
314	   314	      {sel.kind === "comment" && <><CommentBody id={sel.id} cpLabel={cpLabel} /><SignalList sourceId={sel.id} /></>}
315	   315	      {sel.kind === "cluster" && <ClusterBody k={sel.key} data={structure} />}
316	   316	      {sel.kind === "theme" && <ThemeBody k={sel.key} />}
317	   317	      {sel.kind === "area" && <AreaBody k={sel.key} data={structure} />}
318	   318	      {sel.kind === "study" && <><StudyBody s={sel.item} /><EvidenceUse type="study" id={sel.item.id} structure={structure} /></>}
319	   319	      {sel.kind === "option" && (
320	   320	        <>
321	   321	          <h2 className="sheet-title">{sel.item.name ?? sel.item.code}</h2>
322	   322	          <Facts rows={[["Car", CAR_NAME[sel.item.car] ?? sel.item.car], ["Category", sel.item.category], ["Availability", sel.item.availability],
323	   323	                        ["Package", sel.item.package], ["Option code", sel.item.code]]} />
324	   324	          <EvidenceUse type="option" id={sel.item.id} structure={structure} />
325	   325	        </>
326	   326	      )}
327	   327	      {sel.kind === "sales" && <SalesBody row={sel.item} all={sales} />}
328	   328	      {sel.kind === "research" && (
329	   329	        <>
330	   330	          <h2 className="sheet-title">{sel.item.headline}</h2>
331	   331	          {(sel.item.value != null || sel.item.yoy != null) && (
332	   332	            <div className="sheet-figure">
333	   333	              {sel.item.value != null && <span className="num">{sel.item.value.toLocaleString("en-US")}{sel.item.unit === "pct" ? "%" : ""}</span>}
334	   334	              {sel.item.yoy != null && <span className="sheet-yoy">{sel.item.yoy > 0 ? "+" : ""}{sel.item.yoy}% YoY</span>}
335	   335	            </div>
336	   336	          )}
337	   337	          <Facts rows={[["Published", sel.item.published_at ?? "undated"], ["Known from", sel.item.new ? "JUL 26" : "JAN 26"],
338	   338	                        ["About", sel.item.entity], ["Region", sel.item.region], ["Trust", sel.item.tier]]} />
339	   339	          {sel.item.url && <a className="sheet-link" href={sel.item.url} target="_blank" rel="noreferrer">Open source <ExternalLink size={13} /></a>}
340	   340	          <EvidenceUse type="research" id={sel.item.id} structure={structure} />
341	   341	          <SignalList sourceId={sel.item.id} />
342	   342	        </>
343	   343	      )}
344	   344	    </aside>
345	   345	  );
346	   346	}
347	   347	
348	   348	// Which themes the AI linked this research / study / option item to at this checkpoint, and why. Research, study and
349	   349	// options are not split into signals like comments: they enter the analysis as evidence for themes.
350	   350	const RELATION: Record<string, string> = {
351	   351	  supports: "Supports", contradicts: "Contradicts", competes_with: "Competitor", trend_for: "Trend",
352	   352	  available_as_option: "Already offered", context: "Context",
353	   353	};
354	   354	function EvidenceUse({ type, id, structure }: { type: "research" | "study" | "option"; id: number; structure?: StructurePayload }) {
355	   355	  if (!structure) return null;
356	   356	  const edges = structure.ready ? structure.edges.filter((e) => e.src_type === type && e.src_id === String(id) && e.dst_type === "theme") : [];
357	   357	  const theme = Object.fromEntries((structure.themes ?? []).map((t) => [t.key, t]));
358	   358	  return (
359	   359	    <div className="use">
360	   360	      <div className="label">Used as evidence</div>
361	   361	      {!structure.ready ? <p className="use-none">The AI has not structured this checkpoint yet.</p>
362	   362	        : !edges.length ? <p className="use-none">Not linked to any theme at this checkpoint.</p>
363	   363	        : edges.map((e) => (
364	   364	          <div key={`${e.relation}>${e.dst_id}`} className="use-row" data-rel={e.relation}>
365	   365	            <div className="use-head"><span className="use-theme">{theme[e.dst_id]?.title ?? e.dst_id}</span><span className="use-rel">{RELATION[e.relation] ?? e.relation}</span></div>
366	   366	            {e.why && <p className="use-why">{e.why}</p>}
367	   367	          </div>
368	   368	        ))}
369	   369	    </div>
370	   370	  );
371	   371	}
372	   372	
373	   373	function Facts({ rows }: { rows: [string, string | null | undefined][] }) {
374	   374	  return (
375	   375	    <dl className="sheet-facts">
376	   376	      {rows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
377	   377	    </dl>
378	   378	  );
379	   379	}
380	   380	
381	   381	function CommentBody({ id, cpLabel }: { id: number; cpLabel: (id: string) => string }) {
382	   382	  const q = useComment(id);
383	   383	  const c = q.data;
384	   384	  if (!c) return <div className="sheet-skel" aria-hidden><span /><span /><span /></div>;
385	   385	  const label = c.bmw_labels?.[0];
386	   386	  return (
387	   387	    <>
388	   388	      <blockquote className="sheet-quote">{c.text}</blockquote>
389	   389	      <Facts rows={[["Car", CAR_NAME[c.car] ?? c.car],
390	   390	                    ["Market", `${MARKET_NAME[c.market] ?? c.market}${c.country && c.country !== c.market ? ` · ${c.country}` : ""}`],
391	   391	                    ["Channel", c.channel], ["Engine", c.engine],
392	   392	                    ["BMW label", `${label?.feedback_type ?? "Unlabelled"}${label?.vfc_level2 && label.vfc_level2 !== "no_class_found" ? ` · ${label.vfc_level2}` : ""}`],
393	   393	                    ["Acquired", cpLabel(c.checkpoint)], ["ID", c.external_id]]} />
394	   394	    </>
395	   395	  );
396	   396	}
397	   397	
398	   398	function StudyBody({ s }: { s: Extract<Selection, { kind: "study" }>["item"] }) {
399	   399	  const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0));
400	   400	  return (
401	   401	    <>
402	   402	      <h2 className="sheet-title">{s.item}</h2>
403	   403	      <div className="sheet-figure"><span className="num">{studyValue(s)}</span></div>
404	   404	      <div className="zbar" role="img" aria-label={`${z >= 0 ? "Above" : "Below"} this car's average by ${Math.abs(z).toFixed(1)} standard deviations`}>
405	   405	        <span className="zbar-mid" />
406	   406	        <span className="zbar-fill" style={{ left: z >= 0 ? "50%" : `${50 + (z / 2.5) * 50}%`, width: `${(Math.abs(z) / 2.5) * 50}%` }} />
407	   407	        <span className="zbar-l label">below average</span><span className="zbar-r label">above average</span>
408	   408	      </div>
409	   409	      <Facts rows={[["Car", CAR_NAME[s.car] ?? s.car], ["Market", MARKET_NAME[s.market] ?? s.market],
410	   410	                    ["Scale", s.scale === "dist_7" ? "7-point, share of top two answers" : "Mean rating, 0–10"]]} />
411	   411	    </>
412	   412	  );
413	   413	}
414	   414	
415	   415	function SalesBody({ row, all }: { row: Extract<Selection, { kind: "sales" }>["item"]; all: SourcesPayload["sales"] }) {
416	   416	  const series = all.filter((s) => s.car === row.car && s.market === row.market).sort((a, b) => a.year - b.year);
417	   417	  const max = Math.max(1, ...series.map((s) => s.units ?? 0));
418	   418	  return (
419	   419	    <>
420	   420	      <h2 className="sheet-title">{CAR_NAME[row.car] ?? row.car} · {MARKET_NAME[row.market] ?? row.market}</h2>
421	   421	      <div className="minibars" role="img" aria-label="Sales by year">
422	   422	        {series.map((s) => (
423	   423	          <div key={s.year} className="minibar" data-on={s.year === row.year ? "" : undefined} data-forecast={s.is_forecast ? "" : undefined}>
424	   424	            <span className="minibar-n">{fmt(s.units)}</span>
425	   425	            <span className="minibar-col"><span style={{ transform: `scaleY(${(s.units ?? 0) / max})` }} /></span>
426	   426	            <span className="label">{s.year}{s.is_forecast ? " fc" : ""}</span>
427	   427	          </div>
428	   428	        ))}
429	   429	      </div>
430	   430	    </>
431	   431	  );
432	   432	}
