  1	// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
  2	import { Suspense, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
  3	import { Canvas } from "@react-three/fiber";
  4	import { useQuery } from "@tanstack/react-query";
  5	import { ChevronsLeft, ChevronsRight, ExternalLink, SlidersHorizontal, X } from "lucide-react";
  6	import { api } from "@/lib/api";
  7	import type { Comment, PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
  8	import { AreaBody, ClusterBody, Funnel, SignalList, ThemeBody } from "../structure/panels";
  9	import { AgentPanel, useActivity } from "../structure/AgentPanel";
 10	import { PageSwitch } from "@/components/PageSwitch";
 11	import { Dock } from "@/components/Guide";
 12	import { useCheckpoint } from "@/state/checkpoint";
 13	import { Scene, TYPE_COLOR, layerOf, studyValue, type Hover } from "./Scene";
 14	import { CAR_NAME, MARKET_NAME } from "./layout";
 15	import { HOME, NavPad, SPREAD_MAX, SPREAD_MIN, newNav } from "./navigate";
 16	import { DIMS, SCOPE_NOTE, commentMask, isActive, keyValues, passOption, passResearch, passSales, passStudy, valueName, type Dim, type Filter, type Scope } from "./filter";
 17	import "./scan.css";
 18	
 19	// the spread is a per-viewer convenience: remembered in this browser, 1× when storage is unavailable
 20	const SPREAD_KEY = "scan.spread";
 21	function storedSpread() {
 22	  try { const v = Number(localStorage.getItem(SPREAD_KEY)); return v >= SPREAD_MIN && v <= SPREAD_MAX ? v : 1; } catch { return 1; }
 23	}
 24	
 25	const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));
 26	
 27	
 28	export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" }) {
 29	  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
 30	  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
 31	                               staleTime: 30_000, placeholderData: (prev) => prev });
 32	  const [hoverKey, setHoverKey] = useState<string | null>(null);
 33	  const activity = useActivity();
 34	  // when a stage finishes, show its output without a reload
 35	  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
 36	  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
 37	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
 38	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
 39	  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
 40	  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
 41	  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
 42	    const vals = new Set(f[d]);
 43	    if (vals.has(v)) vals.delete(v); else vals.add(v);
 44	    const next = { ...f, [d]: vals };
 45	    if (!vals.size) delete next[d];
 46	    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
 47	  });
 48	  const clear = (d?: Dim) => setChosen(({ f, order }) => {
 49	    if (!d) return { f: {}, order: [] };
 50	    const next = { ...f }; delete next[d];
 51	    return { f: next, order: order.filter((x) => x !== d) };
 52	  });
 53	  const [hover, setHover] = useState<Hover | null>(null);
 54	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
 55	  const [spread, setSpread] = useState(storedSpread);
 56	  useEffect(() => { try { localStorage.setItem(SPREAD_KEY, String(spread)); } catch { /* private mode */ } }, [spread]);
 57	  const nav = useRef(newNav());
 58	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
 59	
 60	  // the filters work on page 1 only; page 2 hides them, so nothing stays filtered there unseen
 61	  const filter = useMemo<Filter | null>(() => (mode === "scan" && isActive(chosen.f) ? chosen.f : null), [mode, chosen]);
 62	  const mask = useMemo(() => (points.data ? commentMask(points.data, filter) : new Uint8Array(0)), [points.data, filter]);
 63	
 64	  useEffect(() => {
 65	    const onKey = (e: KeyboardEvent) => {
 66	      if (e.key !== "Escape") return;
 67	      if (selected) setSelected(null); else clear();
 68	    };
 69	    window.addEventListener("keydown", onKey);
 70	    return () => window.removeEventListener("keydown", onKey);
 71	  }, [selected]);
 72	  useEffect(() => { setSelected(null); setHover(null); }, [mode]);
 73	
 74	  return (
 75	    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
 76	      <div className="scan-canvas">
 77	        {points.data && (
 78	          <Canvas dpr={[1, 2]} camera={{ position: HOME, fov: 40, near: 0.05, far: 60 }}
 79	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
 80	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
 81	                  onPointerMissed={() => setSelected(null)}>
 82	            <Suspense fallback={null}>
 83	              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
 84	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
 85	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
 86	                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
 87	                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter}
 88	                     spread={spread} nav={nav} />
 89	            </Suspense>
 90	          </Canvas>
 91	        )}
 92	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
 93	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
 94	      </div>
 95	
 96	      {mode === "scan" ? (
 97	        <div className="hud-tl">
 98	          <Readout points={points.data} mask={mask} filter={filter} />
 99	          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
100	                                     onToggle={toggle} onClear={clear} />}
101	        </div>
102	      ) : <Funnel data={structure.data} />}
103	      <Dock mode={mode} sel={selected?.sel ?? null} agent={mode === "structure" ? <AgentPanel /> : undefined} running={!!activity.data?.running} />
104	      <PageSwitch />
105	      {points.data && <NavPad spread={spread} onSpread={setSpread} nav={nav} />}
106	
107	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
108	      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
109	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
110	    </main>
111	  );
112	}
113	
114	/* ------------------------------------------------------------------------------------------- glyphs */
115	type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
116	const GLYPH_COLOR: Record<GlyphKind, string> = {
117	  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
118	};
119	function Glyph({ kind }: { kind: GlyphKind }) {
120	  const c = "currentColor";
121	  return (
122	    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
123	      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
124	      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
125	      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
126	      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
127	      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
128	    </svg>
129	  );
130	}
131	
132	/* ------------------------------------------------------------------------------------------- readout */
133	// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
134	// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
135	// While filters are set, every count is what they leave visible.
136	function Readout({ points, mask, filter }: { points: PointsPayload | undefined; mask: Uint8Array; filter: Filter | null }) {
137	  const { current, position } = useCheckpoint();
138	  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
139	  const s = current?.sources;
140	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
141	  const comments = useMemo(() => {
142	    if (!filter || !points) return { n: s?.feedback.visible, nu: s?.feedback.new };
143	    let n = 0, nu = 0;
144	    for (let i = 0; i < points.n; i++) if (mask[i] && points.cols.cp[i] <= position) { n++; if (points.cols.cp[i] === position && position > 1) nu++; }
145	    return { n, nu };
146	  }, [filter, points, mask, position, s]);
147	  const research = (ring: ResearchItem["ring"]) => {
148	    const items = (src?.research ?? []).filter((r) => r.ring === ring && (position > 1 || !r.new) && passResearch(filter, r));
149	    return src ? { n: items.length, nu: items.filter((r) => r.new).length } : undefined;
150	  };
151	  const time = research(null), rating = research("study"), news = research("options"), pub = research("sales");
152	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number; pub?: { label: string; c?: { n: number; nu: number } } }[] = [
153	    { k: "comment", label: "Customer comments", n: comments.n, nu: comments.nu },
154	    { k: "research", label: "Web research", n: time?.n, nu: time?.nu },
155	    { k: "study", label: "Customer study", n: src?.study.filter((x) => passStudy(filter, x)).length, pub: { label: "public ratings", c: rating } },
156	    { k: "option", label: "Equipment options", n: src?.options.filter((x) => passOption(filter, x)).length, pub: { label: "product news", c: news } },
157	    { k: "sales", label: "Sales volumes", n: src?.sales.filter((r) => r.units && r.units > 0 && passSales(filter, r)).length, pub: { label: "public sales", c: pub } },
158	  ];
159	  return (
160	    <dl className="readout" aria-label="Evidence at this checkpoint">
161	      {cells.map((c) => (
162	        <div key={c.label}>
163	          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
164	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
165	          {c.pub && (
166	            <dd className="readout-pub">
167	              <i style={{ borderColor: GLYPH_COLOR[c.k] }} aria-hidden />
168	              <span>{fmt(c.pub.c?.n)} {c.pub.label}</span>{plus(c.pub.c?.nu)}
169	            </dd>
170	          )}
171	        </div>
172	      ))}
173	    </dl>
174	  );
175	}
176	
177	/* ------------------------------------------------------------------------------------------- filters */
178	// One chip per dimension, under the readout, always shown. Dimensions in use come first, in the order they were set,
179	// so choosing a value never moves a chip that is already set. A toggle at the head of the row folds the unused chips
180	// away (the ones in use stay, so nothing is filtered unseen) and unfolds them to the right again; the choice is kept
181	// per browser. Hovering a chip opens its values; choosing one closes the list again, so only the choice stays. Car and
182	// market filter every data type; the other chips belong to one type and carry its glyph (comments: channel, label,
183	// engine, length; research: trust, topic, fact type; study: result; options: category, availability; sales: year).
184	const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
185	const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";
186	
187	interface FilterProps {
188	  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
189	  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
190	}
191	
192	const FOLD_KEY = "scan.filters.folded";
193	const readFolded = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };
194	
195	function FilterBar(p: FilterProps) {
196	  const [folded, setFolded] = useState(readFolded);
197	  const [open, setOpen] = useState<Dim | null>(null);
198	  const fold = (f: boolean) => {
199	    setFolded(f); setOpen(null);
200	    try { localStorage.setItem(FOLD_KEY, f ? "1" : "0"); } catch { /* storage blocked: the choice just isn't kept */ }
201	  };
202	  const active = p.order.filter((d) => p.filter[d]?.size);
203	  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
204	  return (
205	    <div className="filters" role="toolbar" aria-label="Filter the scan" data-folded={folded ? "" : undefined}>
206	      <button className="filters-fold" aria-expanded={!folded} aria-controls="scan-filter-chips"
207	              aria-label={folded ? "Show all filters" : "Hide unused filters"} title={folded ? "Show all filters" : "Hide unused filters"}
208	              onClick={() => fold(!folded)}>
209	        <SlidersHorizontal size={12} aria-hidden />
210	        {folded && <span>Filter{idle.length ? ` · ${idle.length}` : ""}</span>}
211	        {folded ? <ChevronsRight size={13} aria-hidden /> : <ChevronsLeft size={13} aria-hidden />}
212	      </button>
213	      <div className="filters-chips" id="scan-filter-chips">
214	        {[...active, ...(folded ? [] : idle)].map((d) => (
215	          <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
216	        ))}
217	        {active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
218	      </div>
219	    </div>
220	  );
221	}
