257	/* ------------------------------------------------------------------------------------------- hover */
258	const useComment = (id: number | null) =>
259	  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });
