265	  return (
266	    <div className="hovercard" style={{ left, top }} role="tooltip">
267	      {id != null ? (
268	        <>
269	          <p>{q.data?.text ?? " "}</p>
270	          {q.data && (
271	            <div className="hovercard-meta">
272	              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
273	              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
274	            </div>
275	          )}
276	        </>
277	      ) : (
278	        <>
279	          <p>{hover.title}</p>
280	          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
281	        </>
282	      )}
283	    </div>
284	  );
