287	/* ------------------------------------------------------------------------------------------- inspector */
288	const LAYER: Record<Selection["kind"], { name: string; what: string; glyph: GlyphKind }> = {
289	  comment: { name: "Customer comment", what: "Placed by meaning: comments that say similar things sit close together.", glyph: "comment" },
290	  cluster: { name: "Cluster", what: "Signals from many comments that express the same need. Blue = improve, white = keep.", glyph: "comment" },
291	  theme: { name: "Theme", what: "Related findings grouped by the AI, connected to research, study and options that confirm or contradict them.", glyph: "research" },
292	  area: { name: "Potential requirement area", what: "Themes the AI grouped into an area a requirement could address. Requirements are drafted in the next step.", glyph: "sales" },
293	  study: { name: "Customer study 2025", what: "Tick length: how far this topic is rated above or below this car's average.", glyph: "study" },
294	  option: { name: "Equipment option", what: "Today's car, from the German price list.", glyph: "option" },
295	  sales: { name: "BMW sales volume", what: "BMW-internal figures, stylized (Q-015). Outline = 2030 forecast.", glyph: "sales" },
296	  research: { name: "Web research", what: "Cited source, placed on the outer ring by publication date.", glyph: "research" },
297	};
