299	const PUBLIC_LAYER: Record<"sales" | "study" | "options", { name: string; what: string; glyph: GlyphKind }> = {
300	  sales: { name: "Public sales figure", what: "Cited, published figure for this car. Dots and rings sit beside BMW's own bars, never mixed with them.", glyph: "sales" },
301	  study: { name: "Public rating", what: "Published review, award or study result about this car.", glyph: "study" },
302	  options: { name: "Product news", what: "Published news about this car's equipment, prices or availability.", glyph: "option" },
303	};
