305	function Inspector({ sel, sales, onClose, cpLabel, structure }: { sel: Selection; sales: SourcesPayload["sales"]; onClose: () => void; cpLabel: (id: string) => string; structure?: StructurePayload }) {
306	  const L = sel.kind === "research" && sel.item.ring ? PUBLIC_LAYER[sel.item.ring] : LAYER[sel.kind];
307	  return (
308	    <aside className="sheet" aria-label={L.name}>
309	      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
310	      <header className="sheet-head">
311	        <span className="sheet-layer"><Glyph kind={L.glyph} />{L.name}</span>
312	        <p className="sheet-what">{L.what}</p>
313	      </header>
314	      {sel.kind === "comment" && <><CommentBody id={sel.id} cpLabel={cpLabel} /><SignalList sourceId={sel.id} /></>}
315	      {sel.kind === "cluster" && <ClusterBody k={sel.key} data={structure} />}
316	      {sel.kind === "theme" && <ThemeBody k={sel.key} />}
317	      {sel.kind === "area" && <AreaBody k={sel.key} data={structure} />}
318	      {sel.kind === "study" && <><StudyBody s={sel.item} /><EvidenceUse type="study" id={sel.item.id} structure={structure} /></>}
319	      {sel.kind === "option" && (
320	        <>
321	          <h2 className="sheet-title">{sel.item.name ?? sel.item.code}</h2>
322	          <Facts rows={[["Car", CAR_NAME[sel.item.car] ?? sel.item.car], ["Category", sel.item.category], ["Availability", sel.item.availability],
323	                        ["Package", sel.item.package], ["Option code", sel.item.code]]} />
324	          <EvidenceUse type="option" id={sel.item.id} structure={structure} />
325	        </>
326	      )}
327	      {sel.kind === "sales" && <SalesBody row={sel.item} all={sales} />}
328	      {sel.kind === "research" && (
329	        <>
330	          <h2 className="sheet-title">{sel.item.headline}</h2>
331	          {(sel.item.value != null || sel.item.yoy != null) && (
332	            <div className="sheet-figure">
333	              {sel.item.value != null && <span className="num">{sel.item.value.toLocaleString("en-US")}{sel.item.unit === "pct" ? "%" : ""}</span>}
334	              {sel.item.yoy != null && <span className="sheet-yoy">{sel.item.yoy > 0 ? "+" : ""}{sel.item.yoy}% YoY</span>}
335	            </div>
336	          )}
337	          <Facts rows={[["Published", sel.item.published_at ?? "undated"], ["Known from", sel.item.new ? "JUL 26" : "JAN 26"],
338	                        ["About", sel.item.entity], ["Region", sel.item.region], ["Trust", sel.item.tier]]} />
339	          {sel.item.url && <a className="sheet-link" href={sel.item.url} target="_blank" rel="noreferrer">Open source <ExternalLink size={13} /></a>}
340	          <EvidenceUse type="research" id={sel.item.id} structure={structure} />
341	          <SignalList sourceId={sel.item.id} />
342	        </>
343	      )}
344	    </aside>
345	  );
346	}
347	
348	// Which themes the AI linked this research / study / option item to at this checkpoint, and why. Research, study and
349	// options are not split into signals like comments: they enter the analysis as evidence for themes.
350	const RELATION: Record<string, string> = {
351	  supports: "Supports", contradicts: "Contradicts", competes_with: "Competitor", trend_for: "Trend",
352	  available_as_option: "Already offered", context: "Context",
353	};
354	function EvidenceUse({ type, id, structure }: { type: "research" | "study" | "option"; id: number; structure?: StructurePayload }) {
355	  if (!structure) return null;
356	  const edges = structure.ready ? structure.edges.filter((e) => e.src_type === type && e.src_id === String(id) && e.dst_type === "theme") : [];
357	  const theme = Object.fromEntries((structure.themes ?? []).map((t) => [t.key, t]));
358	  return (
359	    <div className="use">
360	      <div className="label">Used as evidence</div>
361	      {!structure.ready ? <p className="use-none">The AI has not structured this checkpoint yet.</p>
362	        : !edges.length ? <p className="use-none">Not linked to any theme at this checkpoint.</p>
363	        : edges.map((e) => (
364	          <div key={`${e.relation}>${e.dst_id}`} className="use-row" data-rel={e.relation}>
365	            <div className="use-head"><span className="use-theme">{theme[e.dst_id]?.title ?? e.dst_id}</span><span className="use-rel">{RELATION[e.relation] ?? e.relation}</span></div>
366	            {e.why && <p className="use-why">{e.why}</p>}
367	          </div>
368	        ))}
369	    </div>
370	  );
371	}
372	
373	function Facts({ rows }: { rows: [string, string | null | undefined][] }) {
374	  return (
375	    <dl className="sheet-facts">
376	      {rows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
377	    </dl>
378	  );
379	}
380	
381	function CommentBody({ id, cpLabel }: { id: number; cpLabel: (id: string) => string }) {
382	  const q = useComment(id);
383	  const c = q.data;
384	  if (!c) return <div className="sheet-skel" aria-hidden><span /><span /><span /></div>;
385	  const label = c.bmw_labels?.[0];
386	  return (
387	    <>
388	      <blockquote className="sheet-quote">{c.text}</blockquote>
389	      <Facts rows={[["Car", CAR_NAME[c.car] ?? c.car],
390	                    ["Market", `${MARKET_NAME[c.market] ?? c.market}${c.country && c.country !== c.market ? ` · ${c.country}` : ""}`],
391	                    ["Channel", c.channel], ["Engine", c.engine],
392	                    ["BMW label", `${label?.feedback_type ?? "Unlabelled"}${label?.vfc_level2 && label.vfc_level2 !== "no_class_found" ? ` · ${label.vfc_level2}` : ""}`],
393	                    ["Acquired", cpLabel(c.checkpoint)], ["ID", c.external_id]]} />
394	    </>
395	  );
396	}
397	
398	function StudyBody({ s }: { s: Extract<Selection, { kind: "study" }>["item"] }) {
399	  const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0));
400	  return (
401	    <>
402	      <h2 className="sheet-title">{s.item}</h2>
403	      <div className="sheet-figure"><span className="num">{studyValue(s)}</span></div>
404	      <div className="zbar" role="img" aria-label={`${z >= 0 ? "Above" : "Below"} this car's average by ${Math.abs(z).toFixed(1)} standard deviations`}>
405	        <span className="zbar-mid" />
406	        <span className="zbar-fill" style={{ left: z >= 0 ? "50%" : `${50 + (z / 2.5) * 50}%`, width: `${(Math.abs(z) / 2.5) * 50}%` }} />
407	        <span className="zbar-l label">below average</span><span className="zbar-r label">above average</span>
408	      </div>
409	      <Facts rows={[["Car", CAR_NAME[s.car] ?? s.car], ["Market", MARKET_NAME[s.market] ?? s.market],
410	                    ["Scale", s.scale === "dist_7" ? "7-point, share of top two answers" : "Mean rating, 0–10"]]} />
411	    </>
412	  );
413	}
414	
415	function SalesBody({ row, all }: { row: Extract<Selection, { kind: "sales" }>["item"]; all: SourcesPayload["sales"] }) {
416	  const series = all.filter((s) => s.car === row.car && s.market === row.market).sort((a, b) => a.year - b.year);
417	  const max = Math.max(1, ...series.map((s) => s.units ?? 0));
418	  return (
419	    <>
420	      <h2 className="sheet-title">{CAR_NAME[row.car] ?? row.car} · {MARKET_NAME[row.market] ?? row.market}</h2>
421	      <div className="minibars" role="img" aria-label="Sales by year">
422	        {series.map((s) => (
423	          <div key={s.year} className="minibar" data-on={s.year === row.year ? "" : undefined} data-forecast={s.is_forecast ? "" : undefined}>
424	            <span className="minibar-n">{fmt(s.units)}</span>
425	            <span className="minibar-col"><span style={{ transform: `scaleY(${(s.units ?? 0) / max})` }} /></span>
426	            <span className="label">{s.year}{s.is_forecast ? " fc" : ""}</span>
427	          </div>
428	        ))}
429	      </div>
430	    </>
431	  );
432	}

