1	     1	// Page 2 inside the scan volume: what the AI made of the raw evidence at the current checkpoint.
2	     2	// Comment points have already flown into their clusters (the morph in Scene). This layer adds the structure on top:
3	     3	// cluster nodes (blue = something to improve, white = something to keep; mark shape = track state: dot held,
4	     4	// ring new, double ring strengthened, amber weakened, amber cross lost), theme halos around groups of clusters,
5	     5	// potential requirement AREAS as diamonds floating above the themes they group, and — for the theme in focus —
6	     6	// evidence arcs down to the exact research, study and option items on the rings.
7	     7	import { createContext, useCallback, useContext, useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
8	     8	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
9	     9	import { Billboard, Html } from "@react-three/drei";
10	    10	import * as THREE from "three";
11	    11	import type { AreaNode, ClusterNode, Selection, StructurePayload, ThemeNode, TrackState } from "@/lib/types";
12	    12	import type { Hover } from "../scan/Scene";
13	    13	import { TYPE_COLOR } from "../scan/colors";
14	    14	import { useSpread } from "../scan/navigate";
15	    15	
16	    16	export const AREA_Y = 1.15;
17	    17	const STATE_CODE: Record<TrackState, number> = { held: 0, new: 1, strengthened: 2, weakened: 3, lost: 4 };
18	    18	const SRC_COLOR: Record<string, string> = { research: TYPE_COLOR.research, study: TYPE_COLOR.study, option: TYPE_COLOR.option };
19	    19	
20	    20	const NODE_VERT = /* glsl */ `
21	    21	attribute float aState; attribute float aPol; attribute float aSize; attribute float aIdx;
22	    22	uniform float uScale, uShow, uHover;
23	    23	varying float vState; varying float vPol; varying float vHov;
24	    24	void main() {
25	    25	  vState = aState; vPol = aPol; vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
26	    26	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
27	    27	  gl_Position = projectionMatrix * mv;
28	    28	  gl_PointSize = aSize * uScale * (1.0 + vHov * 0.6) * uShow / -mv.z;
29	    29	}`;
30	    30	const NODE_FRAG = /* glsl */ `
31	    31	uniform float uShow;
32	    32	varying float vState; varying float vPol; varying float vHov;
33	    33	void main() {
34	    34	  vec2 c = gl_PointCoord - 0.5; float r = length(c);
35	    35	  if (r > 0.5) discard;
36	    36	  float dot = smoothstep(0.5, 0.44, r);
37	    37	  float ring = smoothstep(0.5, 0.45, r) * smoothstep(0.34, 0.39, r);
38	    38	  float dbl = ring + smoothstep(0.27, 0.23, r) * smoothstep(0.15, 0.19, r);
39	    39	  float cross = (abs(c.x - c.y) < 0.06 || abs(c.x + c.y) < 0.06) && r < 0.45 ? 1.0 : 0.0;
40	    40	  float a = vState < 0.5 ? dot : vState < 1.5 ? ring : vState < 2.5 ? dbl : vState < 3.5 ? dot : cross;
41	    41	  vec3 base = vPol > 0.5 ? vec3(0.224, 0.529, 0.898) : vec3(0.93, 0.95, 0.97);
42	    42	  vec3 amber = vec3(0.96, 0.65, 0.14);
43	    43	  vec3 col = vState > 2.5 ? amber : base;
44	    44	  col = mix(col, vec3(1.0), vHov);
45	    45	  gl_FragColor = vec4(col, a * uShow * (vState > 3.5 ? 0.8 : 0.95));
46	    46	}`;
47	    47	
48	    48	/** Fades every material below it with the morph (structure appears as the comments arrive). The labels are DOM
49	    49	 *  overlays (drei <Html>) that ignore `visible`, so the same fade goes to them as a CSS variable on the canvas
50	    50	 *  container they live in, and they are taken out entirely at 0: on the Evidence page none of them show. */
51	    51	function FadeIn({ morph, children }: { morph: MutableRefObject<number>; children: ReactNode }) {
52	    52	  const ref = useRef<THREE.Group>(null);
53	    53	  // the element drei <Html> mounts its labels into (the event source, else the canvas's parent)
54	    54	  const host = useThree((s) => ((s.events.connected as HTMLElement | undefined) ?? s.gl.domElement.parentElement) as HTMLElement | null);
55	    55	  const last = useRef(-1);
56	    56	  useFrame(() => {
57	    57	    const g = ref.current;
58	    58	    if (!g) return;
59	    59	    const a = Math.max(0, (morph.current - 0.45) / 0.55);
60	    60	    g.visible = a > 0.01;
61	    61	    if (host && Math.abs(a - last.current) > 0.004) {
62	    62	      last.current = a;
63	    63	      host.style.setProperty("--structure-fade", a.toFixed(3));
64	    64	      host.toggleAttribute("data-structure-off", a <= 0.01);
65	    65	    }
66	    66	    g.traverse((o) => {
67	    67	      const mat = (o as THREE.Mesh).material;
68	    68	      if (!mat) return;
69	    69	      for (const m of Array.isArray(mat) ? mat : [mat]) {
70	    70	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uShow) m.uniforms.uShow.value = a; continue; }
71	    71	        m.userData.baseOpacity ??= m.opacity;
72	    72	        m.transparent = true;
73	    73	        m.opacity = m.userData.baseOpacity * a;
74	    74	      }
75	    75	    });
76	    76	  });
77	    77	  return <group ref={ref}>{children}</group>;
78	    78	}
79	    79	
80	    80	/* ------------------------------------------------------------------------------------------- label collisions */
81	    81	// Labels are placed in priority order: the label in focus or under the pointer first, then requirement areas by
82	    82	// comments, then themes by comments. A label whose screen box would overlap one already placed is hidden (visibility
83	    83	// only, so it stays measurable) until the view turns or its node is hovered. Checked a few times a second.
84	    84	type Register = (key: string, prio: number) => (el: HTMLDivElement | null) => void;
85	    85	const LabelCtx = createContext<Register>(() => () => {});
86	    86	const PAD = 3;
87	    87	
88	    88	function useLabelCollisions() {
89	    89	  const labels = useRef(new Map<string, { el: HTMLDivElement; prio: number }>());
90	    90	  const tick = useRef(0);
91	    91	  const register = useCallback<Register>((key, prio) => (el) => {
92	    92	    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
93	    93	  }, []);
94	    94	  useFrame(() => {
95	    95	    if (tick.current++ % 6) return;
96	    96	    const placed: DOMRect[] = [];
97	    97	    const list = [...labels.current.values()].sort((a, b) => b.prio - a.prio);
98	    98	    for (const { el, prio } of list) {
99	    99	      const r = el.getBoundingClientRect();
100	   100	      if (!r.width) continue;
101	   101	      const hit = prio < FOCUS && placed.some((q) =>
102	   102	        r.left < q.right + PAD && r.right > q.left - PAD && r.top < q.bottom + PAD && r.bottom > q.top - PAD);
103	   103	      el.toggleAttribute("data-collide", hit);
104	   104	      if (!hit) placed.push(r);
105	   105	    }
