124	   124	export function StructureLayer(p: Props) {
125	   125	  const clusters = useMemo(() => p.data.clusters.filter((c) => c.comments > 0 && !c.tail), [p.data]);
126	   126	  const themeOf = useMemo(() => Object.fromEntries(p.data.themes.map((t) => [t.key, t])), [p.data]);
127	   127	
128	   128	
129	   129	  /* cluster nodes */
130	   130	  const nodeMat = useMemo(() => new THREE.ShaderMaterial({
131	   131	    vertexShader: NODE_VERT, fragmentShader: NODE_FRAG, transparent: true, depthWrite: false,
132	   132	    uniforms: { uScale: { value: 24 * p.dpr }, uShow: { value: 0 }, uHover: { value: -1 } },
133	   133	  }), [p.dpr]);
134	   134	  const nodes = useMemo(() => {
135	   135	    const n = clusters.length;
136	   136	    const pos = new Float32Array(n * 3), st = new Float32Array(n), pol = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
137	   137	    clusters.forEach((c, i) => {
138	   138	      pos.set([c.x, c.y, c.z], i * 3);
139	   139	      st[i] = STATE_CODE[c.state ?? "held"]; pol[i] = c.polarity === "improve" ? 1 : 0;
140	   140	      size[i] = 1.2 + Math.sqrt(c.comments) * 0.32; idx[i] = i;
141	   141	    });
142	   142	    const g = new THREE.BufferGeometry();
143	   143	    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
144	   144	    for (const [k, v] of Object.entries({ aState: st, aPol: pol, aSize: size, aIdx: idx })) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
145	   145	    g.computeBoundingSphere();
146	   146	    return g;
147	   147	  }, [clusters]);
148	   148	  nodeMat.uniforms.uHover.value = Math.max(-1, clusters.findIndex((c) => c.key === p.hoverKey));
149	   149	
150	   150	  /* cluster → theme lines */
151	   151	  const memberLines = useMemo(() => {
152	   152	    const v: number[] = [];
153	   153	    for (const c of clusters) {
154	   154	      const t = c.theme ? themeOf[c.theme] : null;
155	   155	      if (t) v.push(c.x, c.y, c.z, t.x, t.y, t.z);
156	   156	    }
157	   157	    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
158	   158	  }, [clusters, themeOf]);
159	   159	
160	   160	  /* requirement areas float on a ring above the galaxy: each at an evenly spaced slot, in the order of its themes'
161	   161	     bearing, so labels never pile up over the centre; stems tie every area to its themes below */
162	   162	  const areas = useMemo(() => {
163	   163	    const placed: { a: AreaNode; ts: ThemeNode[]; bearing: number }[] = [];
164	   164	    for (const a of p.data.areas) {
165	   165	      const ts = a.themes.map((k) => themeOf[k]).filter(Boolean);
166	   166	      if (!ts.length) continue;
167	   167	      const w = ts.reduce((n, t) => n + (t.comments || 1), 0);
168	   168	      const x = ts.reduce((n, t) => n + t.x * (t.comments || 1), 0) / w, z = ts.reduce((n, t) => n + t.z * (t.comments || 1), 0) / w;
169	   169	      placed.push({ a, ts, bearing: Math.atan2(z, x) });
170	   170	    }
171	   171	    placed.sort((m, n) => m.bearing - n.bearing);
172	   172	    const n = placed.length || 1;
173	   173	    return placed.map(({ a, ts }, i) => {
174	   174	      const ang = (i / n) * Math.PI * 2 - Math.PI / 2;
175	   175	      const r = a.kind === "quality" ? 0.35 : 1.05;
176	   176	      const y = a.kind === "quality" ? AREA_Y - 0.25 : AREA_Y + (i % 2) * 0.12;   // alternate heights for neighbours
177	   177	      return { a, ts, at: [r * Math.cos(ang), y, r * Math.sin(ang)] as [number, number, number] };
178	   178	    });
179	   179	  }, [p.data, themeOf]);
180	   180	  const focusArea = p.selected?.kind === "area" ? p.selected.key : null;
181	   181	  const stems = useMemo(() => {
182	   182	    const v: number[] = [], hot: number[] = [];
183	   183	    for (const { a, at, ts } of areas) for (const t of ts) (a.key === focusArea ? hot : v).push(t.x, t.y, t.z, ...at);
184	   184	    const g = (xs: number[]) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(xs, 3));
