186	   186	  }, [areas, focusArea]);
187	   187	
188	   188	  /* evidence arcs for the theme in focus */
189	   189	  const focusTheme = p.selected?.kind === "theme" ? p.selected.key
190	   190	    : p.selected?.kind === "cluster" ? clusters.find((c) => c.key === (p.selected as { key: string }).key)?.theme ?? null
191	   191	    : p.hoverKey && themeOf[p.hoverKey] ? p.hoverKey : null;
192	   192	  const arcs = useMemo(() => {
193	   193	    if (!focusTheme || !themeOf[focusTheme]) return [];
194	   194	    const t = themeOf[focusTheme];
195	   195	    const out: THREE.Line[] = [];
196	   196	    for (const e of p.data.edges) {
197	   197	      if (e.dst_id !== focusTheme || !(e.src_type in SRC_COLOR)) continue;
198	   198	      const end = p.ends(e.src_type, e.src_id);
199	   199	      if (!end) continue;
200	   200	      const a = new THREE.Vector3(t.x, t.y, t.z), b = new THREE.Vector3(...end);
201	   201	      const mid = a.clone().lerp(b, 0.5).add(new THREE.Vector3(0, 0.45 + a.distanceTo(b) * 0.15, 0));
