210	   210	    }
211	   211	    return out;
212	   212	  }, [focusTheme, themeOf, p.data, p.ends]);
213	   213	
214	   214	  const topThemes = useMemo(() => [...p.data.themes].sort((a, b) => b.comments - a.comments).slice(0, 8).map((t) => t.key), [p.data]);
215	   215	  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) => e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
216	   216	  const register = useLabelCollisions();
217	   217	
218	   218	  return (
219	   219	    <LabelCtx.Provider value={register}>
220	   220	    <FadeIn morph={p.morph}>
221	   221	      <lineSegments geometry={memberLines}><lineBasicMaterial color="#ffffff" transparent opacity={0.07} /></lineSegments>
222	   222	      <points geometry={nodes} material={nodeMat}
223	   223	              onPointerMove={(e) => {
224	   224	                const i = pick(e); if (i == null) return;
225	   225	                const c = clusters[i]; e.stopPropagation(); p.setCursor(true);
226	   226	                p.onHover({ title: c.insight?.title ?? c.category ?? "Cluster", sub: `${c.comments} comments · ${c.state ?? ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, c.key);
227	   227	              }}
228	   228	              onPointerOut={() => { p.setCursor(false); p.onHover(null, null); }}
229	   229	              onClick={(e) => { const i = pick(e); if (i == null) return; e.stopPropagation(); const c = clusters[i]; p.onSelect({ kind: "cluster", key: c.key }, [c.x, c.y, c.z]); }} />
230	   230	      {p.data.themes.map((t) => <ThemeHalo key={t.key} t={t} active={t.key === focusTheme} label={topThemes.includes(t.key) || t.key === focusTheme}
231	   231	                                            hot={p.hoverKey === t.key}
232	   232	                                            onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
233	   233	      <lineSegments geometry={stems.all}><lineBasicMaterial color="#ffffff" transparent opacity={0.12} /></lineSegments>
234	   234	      <lineSegments geometry={stems.hot}><lineBasicMaterial color="#ffffff" transparent opacity={0.7} /></lineSegments>
235	   235	      {areas.map(({ a, at }) => <Diamond key={a.key} a={a} at={at} active={focusArea === a.key} hot={p.hoverKey === a.key}
236	   236	                                         onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
237	   237	      {arcs.map((l, i) => <primitive key={`${focusTheme}-${i}`} object={l} />)}
238	   238	    </FadeIn>
239	   239	    </LabelCtx.Provider>
240	   240	  );
241	   241	}
