243	   243	function ThemeHalo({ t, active, hot, label, onHover, onSelect, setCursor }: {
244	   244	  t: ThemeNode; active: boolean; hot: boolean; label: boolean;
245	   245	  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
246	   246	}) {
