658	     7	const LIFE = 1.8; // seconds a pulse lives
659	     8	const MAX = 600;
660	     9	
661	    10	const VERT = /* glsl */ `
662	    11	attribute float aBorn; uniform float uNow, uScale;
663	    12	varying float vAge;
664	    13	void main() {
665	    14	  vAge = clamp((uNow - aBorn) / ${LIFE.toFixed(1)}, 0.0, 1.0);
666	    15	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
667	    16	  gl_Position = projectionMatrix * mv;
668	    17	  gl_PointSize = (aBorn < 0.0 ? 0.0 : uScale * (0.6 + vAge * 2.4)) / -mv.z;
669	    18	}`;
670	    19	const FRAG = /* glsl */ `
671	    20	varying float vAge;
672	    21	void main() {
673	    22	  float r = length(gl_PointCoord - 0.5);
674	    23	  float ring = smoothstep(0.5, 0.44, r) * smoothstep(0.30, 0.38, r);
675	    24	  float core = smoothstep(0.22, 0.0, r) * (1.0 - vAge);
676	    25	  float a = (ring * 0.9 + core) * (1.0 - vAge);
677	    26	  if (a < 0.01) discard;
678	    27	  gl_FragColor = vec4(1.0, 1.0, 1.0, a);
679	    28	}`;
