681	    30	export function ClassifyPulse({ ids, posOf, dpr }: { ids: number[] | undefined; posOf: (id: number) => [number, number, number] | null; dpr: number }) {
682	    31	  const born = useRef(new Map<number, number>());
683	    32	  const clock = useRef(0);
684	    33	  const geom = useMemo(() => {
685	    34	    const g = new THREE.BufferGeometry();
686	    35	    g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(MAX * 3), 3));
687	    36	    g.setAttribute("aBorn", new THREE.BufferAttribute(new Float32Array(MAX).fill(-1), 1));
688	    37	    return g;
689	    38	  }, []);
690	    39	  const mat = useMemo(() => new THREE.ShaderMaterial({
691	    40	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
692	    41	    uniforms: { uNow: { value: 0 }, uScale: { value: 30 * dpr } },
693	    42	  }), [dpr]);
694	    43	
695	    44	  // stagger new arrivals over ~1.5 s so a batch of 20 reads as the agent moving through them
696	    45	  useEffect(() => {
697	    46	    if (!ids?.length) return;
698	    47	    let k = 0;
699	    48	    for (const id of ids) {
700	    49	      if (!born.current.has(id)) born.current.set(id, clock.current + (k++ % 20) * 0.075);
701	    50	    }
702	    51	  }, [ids]);
703	    52	
704	    53	  useFrame((_, dt) => {
705	    54	    clock.current += dt;
706	    55	    mat.uniforms.uNow.value = clock.current;
707	    56	    const pos = geom.getAttribute("position") as THREE.BufferAttribute, b = geom.getAttribute("aBorn") as THREE.BufferAttribute;
708	    57	    let i = 0;
709	    58	    for (const [id, t] of born.current) {
710	    59	      if (clock.current - t > LIFE) { born.current.delete(id); continue; }
711	    60	      const p = posOf(id);
712	    61	      if (!p || i >= MAX) continue;
713	    62	      pos.setXYZ(i, p[0], p[1], p[2]); b.setX(i, t); i++;
714	    63	    }
715	    64	    for (let j = i; j < MAX; j++) b.setX(j, -1);
716	    65	    pos.needsUpdate = true; b.needsUpdate = true;
717	    66	    geom.setDrawRange(0, i);
718	    67	  });
719	    68	
720	    69	  return <points geometry={geom} material={mat} frustumCulled={false} />;
721	    70	}
