784	    63	      tyre: new THREE.CylinderGeometry(WHEEL_R, WHEEL_R, 0.25, 40, 1),
785	    64	      rim: new THREE.CylinderGeometry(WHEEL_R * 0.72, WHEEL_R * 0.72, 0.02, 40, 1),
786	    65	    }),
787	    66	    [],
788	    67	  );
789	    68	  const mat = useMemo(
790	    69	    () => ({
791	    70	      paint: new THREE.MeshPhysicalMaterial({
792	    71	        color: "#3a3f48",
793	    72	        metalness: 0.55,
794	    73	        roughness: 0.38,
795	    74	        clearcoat: 1,
796	    75	        clearcoatRoughness: 0.12,
797	    76	        envMapIntensity: 1.25,
798	    77	      }),
799	    78	      glass: new THREE.MeshPhysicalMaterial({ color: "#05070a", metalness: 0.9, roughness: 0.06, envMapIntensity: 1.6 }),
800	    79	      tyre: new THREE.MeshStandardMaterial({ color: "#0b0c0e", roughness: 0.92, metalness: 0 }),
