  1	// Page 2 inside the scan volume: what the AI made of the raw evidence at the current checkpoint.
  2	// Comment points have already flown into their clusters (the morph in Scene). This layer adds the structure on top:
  3	// cluster nodes (blue = something to improve, white = something to keep; mark shape = track state: dot held,
  4	// ring new, double ring strengthened, amber weakened, amber cross lost), theme halos around groups of clusters,
  5	// potential requirement AREAS as diamonds floating above the themes they group, and — for the theme in focus —
  6	// evidence arcs down to the exact research, study and option items on the rings.
  7	import { createContext, useCallback, useContext, useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
  8	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
  9	import { Billboard, Html } from "@react-three/drei";
 10	import * as THREE from "three";
 11	import type { AreaNode, ClusterNode, Selection, StructurePayload, ThemeNode, TrackState } from "@/lib/types";
 12	import type { Hover } from "../scan/Scene";
 13	import { TYPE_COLOR } from "../scan/colors";
 14	import { useSpread } from "../scan/navigate";
 15	
 16	export const AREA_Y = 1.15;
 17	const STATE_CODE: Record<TrackState, number> = { held: 0, new: 1, strengthened: 2, weakened: 3, lost: 4 };
 18	const SRC_COLOR: Record<string, string> = { research: TYPE_COLOR.research, study: TYPE_COLOR.study, option: TYPE_COLOR.option };
 19	
 20	const NODE_VERT = /* glsl */ `
 21	attribute float aState; attribute float aPol; attribute float aSize; attribute float aIdx;
 22	uniform float uScale, uShow, uHover;
 23	varying float vState; varying float vPol; varying float vHov;
 24	void main() {
 25	  vState = aState; vPol = aPol; vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
 26	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
 27	  gl_Position = projectionMatrix * mv;
 28	  gl_PointSize = aSize * uScale * (1.0 + vHov * 0.6) * uShow / -mv.z;
 29	}`;
 30	const NODE_FRAG = /* glsl */ `
 31	uniform float uShow;
 32	varying float vState; varying float vPol; varying float vHov;
 33	void main() {
 34	  vec2 c = gl_PointCoord - 0.5; float r = length(c);
 35	  if (r > 0.5) discard;
 36	  float dot = smoothstep(0.5, 0.44, r);
 37	  float ring = smoothstep(0.5, 0.45, r) * smoothstep(0.34, 0.39, r);
 38	  float dbl = ring + smoothstep(0.27, 0.23, r) * smoothstep(0.15, 0.19, r);
 39	  float cross = (abs(c.x - c.y) < 0.06 || abs(c.x + c.y) < 0.06) && r < 0.45 ? 1.0 : 0.0;
 40	  float a = vState < 0.5 ? dot : vState < 1.5 ? ring : vState < 2.5 ? dbl : vState < 3.5 ? dot : cross;
 41	  vec3 base = vPol > 0.5 ? vec3(0.224, 0.529, 0.898) : vec3(0.93, 0.95, 0.97);
 42	  vec3 amber = vec3(0.96, 0.65, 0.14);
 43	  vec3 col = vState > 2.5 ? amber : base;
 44	  col = mix(col, vec3(1.0), vHov);
 45	  gl_FragColor = vec4(col, a * uShow * (vState > 3.5 ? 0.8 : 0.95));
 46	}`;
 47	
 48	/** Fades every material below it with the morph (structure appears as the comments arrive). The labels are DOM
 49	 *  overlays (drei <Html>) that ignore `visible`, so the same fade goes to them as a CSS variable on the canvas
 50	 *  container they live in, and they are taken out entirely at 0: on the Evidence page none of them show. */
 51	function FadeIn({ morph, children }: { morph: MutableRefObject<number>; children: ReactNode }) {
 52	  const ref = useRef<THREE.Group>(null);
 53	  // the element drei <Html> mounts its labels into (the event source, else the canvas's parent)
 54	  const host = useThree((s) => ((s.events.connected as HTMLElement | undefined) ?? s.gl.domElement.parentElement) as HTMLElement | null);
 55	  const last = useRef(-1);
 56	  useFrame(() => {
 57	    const g = ref.current;
 58	    if (!g) return;
 59	    const a = Math.max(0, (morph.current - 0.45) / 0.55);
 60	    g.visible = a > 0.01;
 61	    if (host && Math.abs(a - last.current) > 0.004) {
 62	      last.current = a;
 63	      host.style.setProperty("--structure-fade", a.toFixed(3));
 64	      host.toggleAttribute("data-structure-off", a <= 0.01);
 65	    }
 66	    g.traverse((o) => {
 67	      const mat = (o as THREE.Mesh).material;
 68	      if (!mat) return;
 69	      for (const m of Array.isArray(mat) ? mat : [mat]) {
 70	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uShow) m.uniforms.uShow.value = a; continue; }
 71	        m.userData.baseOpacity ??= m.opacity;
 72	        m.transparent = true;
 73	        m.opacity = m.userData.baseOpacity * a;
 74	      }
 75	    });
 76	  });
 77	  return <group ref={ref}>{children}</group>;
 78	}
 79	
 80	/* ------------------------------------------------------------------------------------------- label collisions */
 81	// Labels are placed in priority order: the label in focus or under the pointer first, then requirement areas by
 82	// comments, then themes by comments. A label whose screen box would overlap one already placed is hidden (visibility
 83	// only, so it stays measurable) until the view turns or its node is hovered. Checked a few times a second.
 84	type Register = (key: string, prio: number) => (el: HTMLDivElement | null) => void;
 85	const LabelCtx = createContext<Register>(() => () => {});
 86	const PAD = 3;
 87	
 88	function useLabelCollisions() {
 89	  const labels = useRef(new Map<string, { el: HTMLDivElement; prio: number }>());
 90	  const tick = useRef(0);
 91	  const register = useCallback<Register>((key, prio) => (el) => {
 92	    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
 93	  }, []);
 94	  useFrame(() => {
 95	    if (tick.current++ % 6) return;
 96	    const placed: DOMRect[] = [];
 97	    const list = [...labels.current.values()].sort((a, b) => b.prio - a.prio);
 98	    for (const { el, prio } of list) {
 99	      const r = el.getBoundingClientRect();
100	      if (!r.width) continue;
101	      const hit = prio < FOCUS && placed.some((q) =>
102	        r.left < q.right + PAD && r.right > q.left - PAD && r.top < q.bottom + PAD && r.bottom > q.top - PAD);
103	      el.toggleAttribute("data-collide", hit);
104	      if (!hit) placed.push(r);
105	    }
106	  });
107	  return register;
108	}
109	const FOCUS = 1e9;          // focused or hovered: always shown
110	const AREA = 1e6;           // areas outrank themes
111	
112	interface Props {
113	  data: StructurePayload;
114	  morph: MutableRefObject<number>;
115	  dpr: number;
116	  selected: Selection | null;
117	  hoverKey: string | null;
118	  ends: (type: string, id: string) => [number, number, number] | null;
119	  onHover: (h: Hover | null, key?: string | null) => void;
120	  onSelect: (s: Selection, at: [number, number, number]) => void;
121	  setCursor: (on: boolean) => void;
122	}
123	
124	export function StructureLayer(p: Props) {
125	  const clusters = useMemo(() => p.data.clusters.filter((c) => c.comments > 0 && !c.tail), [p.data]);
126	  const themeOf = useMemo(() => Object.fromEntries(p.data.themes.map((t) => [t.key, t])), [p.data]);
127	
128	
129	  /* cluster nodes */
130	  const nodeMat = useMemo(() => new THREE.ShaderMaterial({
131	    vertexShader: NODE_VERT, fragmentShader: NODE_FRAG, transparent: true, depthWrite: false,
132	    uniforms: { uScale: { value: 24 * p.dpr }, uShow: { value: 0 }, uHover: { value: -1 } },
133	  }), [p.dpr]);
134	  const nodes = useMemo(() => {
135	    const n = clusters.length;
136	    const pos = new Float32Array(n * 3), st = new Float32Array(n), pol = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
137	    clusters.forEach((c, i) => {
138	      pos.set([c.x, c.y, c.z], i * 3);
139	      st[i] = STATE_CODE[c.state ?? "held"]; pol[i] = c.polarity === "improve" ? 1 : 0;
140	      size[i] = 1.2 + Math.sqrt(c.comments) * 0.32; idx[i] = i;
141	    });
142	    const g = new THREE.BufferGeometry();
143	    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
144	    for (const [k, v] of Object.entries({ aState: st, aPol: pol, aSize: size, aIdx: idx })) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
145	    g.computeBoundingSphere();
146	    return g;
147	  }, [clusters]);
148	  nodeMat.uniforms.uHover.value = Math.max(-1, clusters.findIndex((c) => c.key === p.hoverKey));
149	
150	  /* cluster → theme lines */
151	  const memberLines = useMemo(() => {
152	    const v: number[] = [];
153	    for (const c of clusters) {
154	      const t = c.theme ? themeOf[c.theme] : null;
155	      if (t) v.push(c.x, c.y, c.z, t.x, t.y, t.z);
156	    }
157	    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
158	  }, [clusters, themeOf]);
159	
160	  /* requirement areas float on a ring above the galaxy: each at an evenly spaced slot, in the order of its themes'
161	     bearing, so labels never pile up over the centre; stems tie every area to its themes below */
162	  const areas = useMemo(() => {
163	    const placed: { a: AreaNode; ts: ThemeNode[]; bearing: number }[] = [];
164	    for (const a of p.data.areas) {
165	      const ts = a.themes.map((k) => themeOf[k]).filter(Boolean);
166	      if (!ts.length) continue;
167	      const w = ts.reduce((n, t) => n + (t.comments || 1), 0);
168	      const x = ts.reduce((n, t) => n + t.x * (t.comments || 1), 0) / w, z = ts.reduce((n, t) => n + t.z * (t.comments || 1), 0) / w;
169	      placed.push({ a, ts, bearing: Math.atan2(z, x) });
170	    }
171	    placed.sort((m, n) => m.bearing - n.bearing);
172	    const n = placed.length || 1;
173	    return placed.map(({ a, ts }, i) => {
174	      const ang = (i / n) * Math.PI * 2 - Math.PI / 2;
175	      const r = a.kind === "quality" ? 0.35 : 1.05;
176	      const y = a.kind === "quality" ? AREA_Y - 0.25 : AREA_Y + (i % 2) * 0.12;   // alternate heights for neighbours
177	      return { a, ts, at: [r * Math.cos(ang), y, r * Math.sin(ang)] as [number, number, number] };
178	    });
179	  }, [p.data, themeOf]);
180	  const focusArea = p.selected?.kind === "area" ? p.selected.key : null;
181	  const stems = useMemo(() => {
182	    const v: number[] = [], hot: number[] = [];
183	    for (const { a, at, ts } of areas) for (const t of ts) (a.key === focusArea ? hot : v).push(t.x, t.y, t.z, ...at);
184	    const g = (xs: number[]) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(xs, 3));
185	    return { all: g(v), hot: g(hot) };
186	  }, [areas, focusArea]);
187	
188	  /* evidence arcs for the theme in focus */
189	  const focusTheme = p.selected?.kind === "theme" ? p.selected.key
190	    : p.selected?.kind === "cluster" ? clusters.find((c) => c.key === (p.selected as { key: string }).key)?.theme ?? null
191	    : p.hoverKey && themeOf[p.hoverKey] ? p.hoverKey : null;
192	  const arcs = useMemo(() => {
193	    if (!focusTheme || !themeOf[focusTheme]) return [];
194	    const t = themeOf[focusTheme];
195	    const out: THREE.Line[] = [];
196	    for (const e of p.data.edges) {
197	      if (e.dst_id !== focusTheme || !(e.src_type in SRC_COLOR)) continue;
198	      const end = p.ends(e.src_type, e.src_id);
199	      if (!end) continue;
200	      const a = new THREE.Vector3(t.x, t.y, t.z), b = new THREE.Vector3(...end);
201	      const mid = a.clone().lerp(b, 0.5).add(new THREE.Vector3(0, 0.45 + a.distanceTo(b) * 0.15, 0));
202	      const pts = new THREE.QuadraticBezierCurve3(a, mid, b).getPoints(40);
203	      const geom = new THREE.BufferGeometry().setFromPoints(pts);
204	      const contra = e.relation === "contradicts";
205	      const line = new THREE.Line(geom, contra
206	        ? new THREE.LineDashedMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.7, dashSize: 0.03, gapSize: 0.03 })
207	        : new THREE.LineBasicMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.85 }));
208	      if (contra) line.computeLineDistances();
209	      out.push(line);
210	    }
211	    return out;
212	  }, [focusTheme, themeOf, p.data, p.ends]);
213	
214	  const topThemes = useMemo(() => [...p.data.themes].sort((a, b) => b.comments - a.comments).slice(0, 8).map((t) => t.key), [p.data]);
215	  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) => e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
216	  const register = useLabelCollisions();
217	
218	  return (
219	    <LabelCtx.Provider value={register}>
220	    <FadeIn morph={p.morph}>
221	      <lineSegments geometry={memberLines}><lineBasicMaterial color="#ffffff" transparent opacity={0.07} /></lineSegments>
222	      <points geometry={nodes} material={nodeMat}
223	              onPointerMove={(e) => {
224	                const i = pick(e); if (i == null) return;
225	                const c = clusters[i]; e.stopPropagation(); p.setCursor(true);
226	                p.onHover({ title: c.insight?.title ?? c.category ?? "Cluster", sub: `${c.comments} comments · ${c.state ?? ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, c.key);
227	              }}
228	              onPointerOut={() => { p.setCursor(false); p.onHover(null, null); }}
229	              onClick={(e) => { const i = pick(e); if (i == null) return; e.stopPropagation(); const c = clusters[i]; p.onSelect({ kind: "cluster", key: c.key }, [c.x, c.y, c.z]); }} />
230	      {p.data.themes.map((t) => <ThemeHalo key={t.key} t={t} active={t.key === focusTheme} label={topThemes.includes(t.key) || t.key === focusTheme}
231	                                            hot={p.hoverKey === t.key}
232	                                            onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
233	      <lineSegments geometry={stems.all}><lineBasicMaterial color="#ffffff" transparent opacity={0.12} /></lineSegments>
234	      <lineSegments geometry={stems.hot}><lineBasicMaterial color="#ffffff" transparent opacity={0.7} /></lineSegments>
235	      {areas.map(({ a, at }) => <Diamond key={a.key} a={a} at={at} active={focusArea === a.key} hot={p.hoverKey === a.key}
236	                                         onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
237	      {arcs.map((l, i) => <primitive key={`${focusTheme}-${i}`} object={l} />)}
238	    </FadeIn>
239	    </LabelCtx.Provider>
240	  );
241	}
242	
243	function ThemeHalo({ t, active, hot, label, onHover, onSelect, setCursor }: {
244	  t: ThemeNode; active: boolean; hot: boolean; label: boolean;
245	  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
246	}) {
247	  const r = 0.05 + Math.sqrt(t.comments) * 0.006;
248	  const lost = t.state === "lost", changed = t.state === "strengthened" || t.state === "new";
249	  const register = useContext(LabelCtx);
250	  const { k } = useSpread();   // the halo keeps its size when the spread opens the universe up
251	  return (
252	    <Billboard position={[t.x, t.y, t.z]} scale={k}>
253	      <mesh onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: t.title, sub: `Theme · ${t.comments} comments${t.state ? ` · ${t.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, t.key); }}
254	            onPointerOut={() => { setCursor(false); onHover(null, null); }}
255	            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "theme", key: t.key }, [t.x, t.y, t.z]); }}>
256	        <ringGeometry args={[r, r + (active ? 0.008 : 0.004), 48]} />
257	        <meshBasicMaterial color={lost ? "#f5a524" : "#ffffff"} transparent opacity={active ? 0.95 : changed ? 0.55 : 0.32} depthWrite={false} />
258	      </mesh>
259	      {label && (
260	        <Html position={[0, r + 0.06, 0]} center zIndexRange={[12, 0]}>
261	          <div className="theme-label" data-active={active ? "" : undefined}
262	               ref={register(`theme:${t.key}`, active || hot ? FOCUS : t.comments)}>{t.title}</div>
263	        </Html>
264	      )}
265	    </Billboard>
266	  );
267	}
268	
269	function Diamond({ a, at, active, hot, onHover, onSelect, setCursor }: {
270	  a: AreaNode; at: [number, number, number]; active: boolean; hot: boolean;
271	  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
272	}) {
273	  const ref = useRef<THREE.Mesh>(null);
274	  const register = useContext(LabelCtx);
275	  useFrame((_, dt) => { if (ref.current) ref.current.rotation.y += dt * (active ? 1.6 : 0.4); });
276	  const quality = a.kind === "quality";
277	  const color = quality ? "#f5a524" : a.kind === "keep" ? "#eef1f5" : a.kind === "emerging" ? "#d95926" : "#3987e5";
278	  const size = 0.028 + Math.min(0.03, Math.sqrt(a.metrics.comments ?? 1) * 0.0012);
279	  const { k } = useSpread();
280	  return (
281	    <group position={at} scale={k}>
282	      <mesh ref={ref}
283	            onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: a.title, sub: quality ? "Quality hand-over" : `Requirement area · ${a.kind} · ${a.metrics.comments ?? 0} comments${a.state ? ` · ${a.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, a.key); }}
284	            onPointerOut={() => { setCursor(false); onHover(null, null); }}
285	            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "area", key: a.key }, at); }}>
286	        <octahedronGeometry args={[active ? size * 1.5 : size, 0]} />
287	        <meshBasicMaterial color={color} wireframe={a.state === "new" || quality} transparent opacity={active ? 1 : 0.9} />
288	      </mesh>
289	      {(active || (a.metrics.comments ?? 0) > 0) && (
290	        <Html position={[0, size + 0.05, 0]} center zIndexRange={[12, 0]}>
291	          <div className="area-label" data-active={active ? "" : undefined}
292	               ref={register(`area:${a.key}`, active || hot ? FOCUS : AREA + (a.metrics.comments ?? 0))}>{a.title}</div>
293	        </Html>
294	      )}
295	    </group>
296	  );
297	}
298	
299	export type { ClusterNode };
  1	// Page 2 overlays: the stage funnel (top-left), inspector bodies for clusters, themes and potential requirements,
  2	// and the list of signals the AI extracted from one source (also shown on page 1 when a comment is opened).
  3	import { useQuery } from "@tanstack/react-query";
  4	import { ExternalLink } from "lucide-react";
  5	import { api } from "@/lib/api";
  6	import type { SignalRow, StructurePayload, TrackState, AreaMarket } from "@/lib/types";
  7	import { useCheckpoint } from "@/state/checkpoint";
  8	import "./structure.css";
  9	
 10	const fmt = (n: unknown) => (typeof n === "number" ? n.toLocaleString("en-US") : "–");
 11	const ASPECT = (a: string | null) => (a ?? "other").replace(/_/g, " ");
 12	const LINE_MARKET = (k: string) => k.replace(":", " · ").replace("RoW", "Rest of world").replace("EU", "Europe").replace("US", "USA").replace("CN", "China");
 13	
 14	export function StateMark({ state }: { state: TrackState | null | undefined }) {
 15	  return <i className={`smark s-${state ?? "held"}`} title={state ?? "held"} aria-label={state ?? "held"} />;
 16	}
 17	
 18	/* ------------------------------------------------------------------------------------------- funnel */
 19	export function Funnel({ data }: { data: StructurePayload | undefined }) {
 20	  const { position } = useCheckpoint();
 21	  if (!data?.ready) {
 22	    return (
 23	      <div className="funnel funnel-wait">
