  1	// While the agent classifies, each comment it just read flashes with an expanding ring at its place in the galaxy.
  2	// Fed by /api/structure/activity `recent` (comments classified in the last few seconds).
  3	import { useEffect, useMemo, useRef } from "react";
  4	import { useFrame } from "@react-three/fiber";
  5	import * as THREE from "three";
  6	
  7	const LIFE = 1.8; // seconds a pulse lives
  8	const MAX = 600;
  9	
 10	const VERT = /* glsl */ `
 11	attribute float aBorn; uniform float uNow, uScale;
 12	varying float vAge;
 13	void main() {
 14	  vAge = clamp((uNow - aBorn) / ${LIFE.toFixed(1)}, 0.0, 1.0);
 15	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
 16	  gl_Position = projectionMatrix * mv;
 17	  gl_PointSize = (aBorn < 0.0 ? 0.0 : uScale * (0.6 + vAge * 2.4)) / -mv.z;
 18	}`;
 19	const FRAG = /* glsl */ `
 20	varying float vAge;
 21	void main() {
 22	  float r = length(gl_PointCoord - 0.5);
 23	  float ring = smoothstep(0.5, 0.44, r) * smoothstep(0.30, 0.38, r);
 24	  float core = smoothstep(0.22, 0.0, r) * (1.0 - vAge);
 25	  float a = (ring * 0.9 + core) * (1.0 - vAge);
 26	  if (a < 0.01) discard;
 27	  gl_FragColor = vec4(1.0, 1.0, 1.0, a);
 28	}`;
 29	
 30	export function ClassifyPulse({ ids, posOf, dpr }: { ids: number[] | undefined; posOf: (id: number) => [number, number, number] | null; dpr: number }) {
 31	  const born = useRef(new Map<number, number>());
 32	  const clock = useRef(0);
 33	  const geom = useMemo(() => {
 34	    const g = new THREE.BufferGeometry();
 35	    g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(MAX * 3), 3));
 36	    g.setAttribute("aBorn", new THREE.BufferAttribute(new Float32Array(MAX).fill(-1), 1));
 37	    return g;
 38	  }, []);
 39	  const mat = useMemo(() => new THREE.ShaderMaterial({
 40	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
 41	    uniforms: { uNow: { value: 0 }, uScale: { value: 30 * dpr } },
 42	  }), [dpr]);
 43	
 44	  // stagger new arrivals over ~1.5 s so a batch of 20 reads as the agent moving through them
 45	  useEffect(() => {
 46	    if (!ids?.length) return;
 47	    let k = 0;
 48	    for (const id of ids) {
 49	      if (!born.current.has(id)) born.current.set(id, clock.current + (k++ % 20) * 0.075);
 50	    }
 51	  }, [ids]);
 52	
 53	  useFrame((_, dt) => {
 54	    clock.current += dt;
 55	    mat.uniforms.uNow.value = clock.current;
 56	    const pos = geom.getAttribute("position") as THREE.BufferAttribute, b = geom.getAttribute("aBorn") as THREE.BufferAttribute;
 57	    let i = 0;
 58	    for (const [id, t] of born.current) {
 59	      if (clock.current - t > LIFE) { born.current.delete(id); continue; }
 60	      const p = posOf(id);
 61	      if (!p || i >= MAX) continue;
 62	      pos.setXYZ(i, p[0], p[1], p[2]); b.setX(i, t); i++;
 63	    }
 64	    for (let j = i; j < MAX; j++) b.setX(j, -1);
 65	    pos.needsUpdate = true; b.needsUpdate = true;
