  1	// Procedural stand-in car (no assets): satin dark-grey body, dark glasshouse, four wheels.
  2	// Already in the normalised world frame: front = +X, up = +Y, length ≈ 4.8, wheels on y = 0.
  3	import { useMemo } from "react";
  4	import * as THREE from "three";
  5	import type { CarFrame } from "./frame";
  6	
  7	export const PLACEHOLDER_FRAME: CarFrame = { L: 2.4, W: 0.95, H: 1.44 };
  8	
  9	const WHEEL_X = 1.46;
 10	const WHEEL_R = 0.355;
 11	const ARCH_R = 0.44;
 12	
 13	function bodyShape(): THREE.Shape {
 14	  const s = new THREE.Shape();
 15	  s.moveTo(-2.3, 0.3);
 16	  // bottom, rear arch, front arch
 17	  s.lineTo(-WHEEL_X - ARCH_R, 0.3);
 18	  s.absarc(-WHEEL_X, 0.3, ARCH_R, Math.PI, 0, true);
 19	  s.lineTo(WHEEL_X - ARCH_R, 0.3);
 20	  s.absarc(WHEEL_X, 0.3, ARCH_R, Math.PI, 0, true);
 21	  s.lineTo(2.28, 0.3);
 22	  // front fascia → bonnet
 23	  s.quadraticCurveTo(2.42, 0.32, 2.42, 0.56);
 24	  s.quadraticCurveTo(2.41, 0.78, 2.14, 0.86);
 25	  s.quadraticCurveTo(1.4, 0.95, 0.78, 0.99);
 26	  // beltline → boot lid
 27	  s.lineTo(-1.7, 1.01);
 28	  s.quadraticCurveTo(-2.26, 1.0, -2.36, 0.88);
 29	  s.quadraticCurveTo(-2.44, 0.6, -2.4, 0.4);
 30	  s.quadraticCurveTo(-2.38, 0.3, -2.3, 0.3);
 31	  return s;
 32	}
 33	
 34	function glassShape(): THREE.Shape {
 35	  const s = new THREE.Shape();
 36	  s.moveTo(0.86, 0.93);
 37	  s.quadraticCurveTo(0.32, 1.36, -0.12, 1.4);
 38	  s.quadraticCurveTo(-0.6, 1.43, -1.02, 1.39);
 39	  s.quadraticCurveTo(-1.62, 1.3, -1.95, 0.97);
 40	  s.lineTo(0.86, 0.93);
 41	  return s;
 42	}
 43	
 44	function extrude(shape: THREE.Shape, depth: number, bevel: number) {
 45	  const g = new THREE.ExtrudeGeometry(shape, {
 46	    depth,
 47	    bevelEnabled: true,
 48	    bevelThickness: bevel,
 49	    bevelSize: bevel * 0.9,
 50	    bevelSegments: 6,
 51	    curveSegments: 32,
 52	  });
 53	  g.translate(0, 0, -depth / 2);
 54	  g.computeVertexNormals();
 55	  return g;
 56	}
 57	
 58	export function PlaceholderCar() {
 59	  const geo = useMemo(
 60	    () => ({
 61	      body: extrude(bodyShape(), 1.62, 0.13),
 62	      glass: extrude(glassShape(), 1.3, 0.12),
 63	      tyre: new THREE.CylinderGeometry(WHEEL_R, WHEEL_R, 0.25, 40, 1),
 64	      rim: new THREE.CylinderGeometry(WHEEL_R * 0.72, WHEEL_R * 0.72, 0.02, 40, 1),
 65	    }),
 66	    [],
 67	  );
 68	  const mat = useMemo(
 69	    () => ({
 70	      paint: new THREE.MeshPhysicalMaterial({
 71	        color: "#3a3f48",
 72	        metalness: 0.55,
 73	        roughness: 0.38,
 74	        clearcoat: 1,
 75	        clearcoatRoughness: 0.12,
 76	        envMapIntensity: 1.25,
 77	      }),
 78	      glass: new THREE.MeshPhysicalMaterial({ color: "#05070a", metalness: 0.9, roughness: 0.06, envMapIntensity: 1.6 }),
 79	      tyre: new THREE.MeshStandardMaterial({ color: "#0b0c0e", roughness: 0.92, metalness: 0 }),
 80	      rim: new THREE.MeshStandardMaterial({ color: "#7d838e", roughness: 0.28, metalness: 1, envMapIntensity: 1.4 }),
 81	      front: new THREE.MeshBasicMaterial({ color: "#dfe9ff", toneMapped: false }),
 82	      rear: new THREE.MeshBasicMaterial({ color: "#d4252f", toneMapped: false }),
 83	    }),
 84	    [],
 85	  );
 86	
 87	  const wheels: [number, number][] = [
 88	    [WHEEL_X, 1],
 89	    [WHEEL_X, -1],
 90	    [-WHEEL_X, 1],
 91	    [-WHEEL_X, -1],
 92	  ];
 93	
 94	  return (
 95	    <group name="placeholder-car">
 96	      <mesh name="body" geometry={geo.body} material={mat.paint} />
 97	      <mesh name="glass" geometry={geo.glass} material={mat.glass} />
 98	      {wheels.map(([x, side]) => (
 99	        <group key={`${x}${side}`} position={[x, WHEEL_R, side * 0.8]} rotation={[Math.PI / 2, 0, 0]}>
100	          <mesh geometry={geo.tyre} material={mat.tyre} />
101	          <mesh geometry={geo.rim} material={mat.rim} position={[0, side * 0.13, 0]} />
102	        </group>
103	      ))}
104	      {/* light signatures */}
105	      {[1, -1].map((side) => (
106	        <mesh key={`h${side}`} material={mat.front} position={[2.535, 0.7, side * 0.6]} rotation={[0, 0, 0.35]}>
107	          <boxGeometry args={[0.02, 0.035, 0.42]} />
108	        </mesh>
109	      ))}
110	      <mesh material={mat.rear} position={[-2.545, 0.8, 0]}>
111	        <boxGeometry args={[0.02, 0.03, 1.5]} />
112	      </mesh>
113	    </group>
114	  );
115	}

